                  <div className="text-[11px] text-muted-foreground truncate">
                    {phone.provider === 'twilio' ? 'Twilio' : phone.provider === 'plivo' ? 'Plivo' : 'TCXC'} · {phone.country}
                  </div>
                </div>
              </button>
