        <h3 className="text-[11px] font-semibold text-zinc-400 dark:text-zinc-500 uppercase tracking-wide px-3 mb-1">
          {title}
        </h3>
      )}
      <div>
        {children}
      </div>
    </div>
  );
}

interface SubPanelItemProps {
