  label: string;
  isActive?: boolean;
  onClick?: () => void;
  badge?: React.ReactNode | string | number;
  className?: string;
  "data-testid"?: string;
}

export function SubPanelItem({
  icon,
  label,
  isActive,
  onClick,
  badge,
  className,
  "data-testid": dataTestId,
}: SubPanelItemProps) {
  return (
    <button
