   ======================== */

/* Arabic font family support */
html[lang="ar"] {
  --font-sans: 'IBM Plex Sans Arabic', 'Cairo', 'Segoe UI', sans-serif;
  --font-serif: 'IBM Plex Sans Arabic', 'Cairo', serif;
}

/* RTL specific adjustments */
html[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

/* Flip directional icons in RTL */
html[dir="rtl"] .rtl-flip {
  transform: scaleX(-1);
}

/* Don't flip certain icons that should remain the same in RTL */
html[dir="rtl"] .rtl-no-flip {
  transform: none !important;
}

/* RTL sidebar positioning - use inset-inline-start/end for auto-mirroring */
html[dir="rtl"] [data-slot="sidebar-container"] {
  left: auto;
  right: 0;
  border-right: none;
  border-left: 1px solid hsl(var(--sidebar-border));
}

html[dir="rtl"] [data-slot="sidebar-container"][data-side="left"] {
  left: auto;
  right: 0;
}

html[dir="rtl"] [data-state="collapsed"] [data-slot="sidebar-container"] {
  right: calc(var(--sidebar-width) * -1);
  left: auto;
}

/* RTL sidebar inner border */
html[dir="rtl"] [data-sidebar="sidebar"] {
  border-left: 1px solid hsl(var(--sidebar-border));
  border-right: none;
}

/* RTL sidebar gap mirror */
html[dir="rtl"] [data-slot="sidebar-gap"] {
  margin-left: 0;
  margin-right: 0;
}

/* RTL form adjustments */
html[dir="rtl"] input,
html[dir="rtl"] textarea,
html[dir="rtl"] select {
  text-align: right;
}

/* Keep numbers LTR within RTL context */
html[dir="rtl"] .ltr-numbers {
