          conditions: [
            {
              type: "keyword",
              value: "transfer,human,agent,person,team,speak,talk",
              targetNodeId: "transfer",
              label: "Wants Transfer",
            },
            {
              type: "yes_no",
              value: "no",
              targetNodeId: "end",
              label: "No More Help",
            },
          ],
          defaultTargetNodeId: "knowledge_base",
