    {
      id: "transfer",
      type: "transfer",
      position: { x: 100, y: 570 },
      data: {
        label: "Transfer Call",
        config: {
          type: "transfer",
          transferNumber: "",
          message: "I'll transfer you now. Please hold.",
        },
      },
