}

export interface ElevenLabsWebSocketMessage {
  type: string;
  audio?: {
    chunk?: string;
    format?: string;
    sample_rate?: number;
  };
  user_transcript?: {
    text: string;
    is_final: boolean;
  };
  agent_response?: {
    text: string;
    is_final: boolean;
  };
  conversation_id?: string;
  ping_event?: {
    event_id: number;
  };
  error?: {
    message: string;
    code?: string;
  };
}

