    >
      {/* iOS 18 Style Column Header */}
      <div className="px-4 py-3 cursor-grab active:cursor-grabbing border-b border-border/20">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <GripVertical className="w-4 h-4 text-foreground/30" />
            <div 
              className="flex items-center justify-center w-8 h-8 rounded-xl"
              style={{ backgroundColor: `${category.color}15` }}
            >
              <Icon className="w-4 h-4" style={{ color: category.color }} />
            </div>
            <h3 className="font-medium text-sm text-foreground">
              {category.label}
            </h3>
            <Badge variant="secondary" className="rounded-full">
              {total}
            </Badge>
          </div>
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button size="icon" variant="ghost">
                <MoreHorizontal className="w-4 h-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="rounded-xl">
              <DropdownMenuItem 
                onClick={() => onSortChange?.('newest')}
                className={sortBy === 'newest' ? 'bg-accent' : ''}
              >
                <ArrowDownUp className="w-4 h-4 mr-2" />
                Newest First
              </DropdownMenuItem>
              <DropdownMenuItem 
                onClick={() => onSortChange?.('oldest')}
                className={sortBy === 'oldest' ? 'bg-accent' : ''}
              >
                <ArrowDownUp className="w-4 h-4 mr-2" />
                Oldest First
              </DropdownMenuItem>
              <DropdownMenuItem 
                onClick={() => onSortChange?.('score-high')}
                className={sortBy === 'score-high' ? 'bg-accent' : ''}
              >
                <Star className="w-4 h-4 mr-2" />
                Highest Score
              </DropdownMenuItem>
              <DropdownMenuItem 
                onClick={() => onSortChange?.('score-low')}
                className={sortBy === 'score-low' ? 'bg-accent' : ''}
              >
                <Star className="w-4 h-4 mr-2" />
                Lowest Score
              </DropdownMenuItem>
              <Separator className="my-1" />
              <div className="px-2 py-1.5">
                <p className="text-xs font-medium mb-2">Column Color</p>
                <div className="grid grid-cols-4 gap-1">
                  {COLOR_PRESETS.slice(0, 8).map((preset) => (
                    <Button
                      key={preset.hex}
                      size="icon"
                      variant="ghost"
                      className={`rounded-lg ${
                        category.color.toLowerCase() === preset.hex.toLowerCase() ? 'ring-2 ring-primary ring-offset-1' : ''
                      }`}
                      style={{ backgroundColor: preset.hex }}
                      onClick={() => onColorChange?.(preset.hex)}
                      title={preset.name}
                    />
                  ))}
                </div>
              </div>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <ScrollArea 
        className="flex-1 p-2" 
        style={{ maxHeight: "calc(100vh - 260px)" }}
        onDragOver={(e) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        onDrop={(e) => {
          e.preventDefault();
          e.stopPropagation();
          const leadId = e.dataTransfer.getData("leadId");
          if (leadId && onLeadDrop) {
            onLeadDrop(leadId, category.id);
          }
        }}
      >
        <div className="space-y-2">
          <AnimatePresence mode="popLayout">
            {leads.map((lead) => (
              <div 
                key={lead.id}
                draggable
                onDragStart={(e) => {
                  e.stopPropagation();
                  e.dataTransfer.setData("leadId", lead.id);
                  e.dataTransfer.effectAllowed = 'move';
                }}
              >
                <LeadCard 
                  lead={lead} 
                  onClick={() => onLeadClick(lead)} 
                  stageColor={category.color}
                  isSelected={selectedLeadIds?.has(lead.id)}
                  onToggleSelect={onToggleSelect}
                />
              </div>
            ))}
          </AnimatePresence>
          {leads.length === 0 && (
            <div className="flex flex-col items-center justify-center py-10 text-center min-h-[100px]">
              <div 
                className="w-10 h-10 rounded-xl flex items-center justify-center mb-2"
                style={{ backgroundColor: `${category.color}10` }}
              >
                <Icon className="w-4 h-4" style={{ color: category.color }} />
              </div>
              <p className="text-xs text-foreground/50">No leads</p>
              <p className="text-xs text-foreground/30 mt-0.5">Drop leads here</p>
            </div>
          )}
        </div>
      </ScrollArea>
    </div>
  );
}

function LeadDetailModal({ lead, open, onClose, stageColor }: { lead: Lead | null; open: boolean; onClose: () => void; stageColor?: string }) {
  const { toast } = useToast();
  const queryClientRef = useQueryClient();
  const [noteText, setNoteText] = useState("");
  const [isPlaying, setIsPlaying] = useState(false);
  const [activeTab, setActiveTab] = useState("notes");

  const displayName = lead ? [lead.firstName, lead.lastName].filter(Boolean).join(" ") || "Unknown" : "";

  const notesQueryKey = `/api/crm/leads/${lead?.id}/notes`;
  const { data: notes = [], isLoading: notesLoading } = useQuery<LeadNote[]>({
    queryKey: [notesQueryKey],
    enabled: !!lead?.id && open,
  });

  const activitiesQueryKey = `/api/crm/leads/${lead?.id}/activities`;
  const { data: activities = [], isLoading: activitiesLoading } = useQuery<LeadActivity[]>({
    queryKey: [activitiesQueryKey],
    enabled: !!lead?.id && open,
  });

  const addNoteMutation = useMutation({
    mutationFn: async (content: string) => {
      return apiRequest("POST", `/api/crm/leads/${lead?.id}/notes`, { content });
    },
    onSuccess: () => {
      toast({ title: "Note added" });
      setNoteText("");
      queryClientRef.invalidateQueries({ queryKey: [notesQueryKey] });
      queryClientRef.invalidateQueries({ queryKey: [activitiesQueryKey] });
    },
    onError: (error: any) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'call': return <Phone className="w-3 h-3" />;
      case 'note': return <MessageSquare className="w-3 h-3" />;
      case 'stage_change': return <ArrowRightLeft className="w-3 h-3" />;
      case 'tag_added': case 'tag_removed': return <Tag className="w-3 h-3" />;
      case 'created': return <Plus className="w-3 h-3" />;
      case 'transfer': return <PhoneForwarded className="w-3 h-3" />;
      case 'appointment': return <Calendar className="w-3 h-3" />;
      default: return <History className="w-3 h-3" />;
    }
  };

  if (!lead) return null;

  const theme = getStageTheme(lead.stage, stageColor);

  return (
    <Dialog open={open} onOpenChange={() => onClose()}>
      <DialogContent className="max-w-2xl max-h-[85vh] overflow-y-auto rounded-2xl" data-testid="lead-detail-modal">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-4">
            <ScoreIndicator score={lead.leadScore} />
            <div>
              <span className="text-xl font-semibold tracking-tight">{displayName}</span>
              <div className="flex items-center gap-2 mt-1.5">
                <Badge variant="secondary" className="rounded-full">
                  {lead.stage}
                </Badge>
                {lead.sentiment && (
                  <Badge variant="outline" className="flex items-center gap-1">
                    <SentimentIcon sentiment={lead.sentiment} />
                    <span className="capitalize">{lead.sentiment}</span>
                  </Badge>
                )}
              </div>
            </div>
          </DialogTitle>
          <DialogDescription className="text-foreground/50">
            Lead details and conversation history
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-4">
          {/* iOS 18 Style Info Grid */}
          <div className="grid grid-cols-2 gap-4 p-4 rounded-2xl bg-foreground/[0.02] border border-border/30">
            <div>
              <p className="text-xs text-foreground/50 mb-1">Phone</p>
              <p className="font-mono text-sm" data-testid="lead-detail-phone">{lead.phone}</p>
            </div>
            {lead.email && (
              <div>
                <p className="text-xs text-foreground/50 mb-1">Email</p>
                <p className="text-sm" data-testid="lead-detail-email">{lead.email}</p>
              </div>
            )}
            <div>
              <p className="text-xs text-foreground/50 mb-1">Source</p>
              <Badge variant="outline" className="flex items-center gap-1 w-fit">
                {lead.sourceType === "campaign" ? <Zap className="w-3 h-3" /> : <PhoneCall className="w-3 h-3" />}
                {lead.sourceType === "campaign" ? "Campaign" : "Incoming"}
              </Badge>
            </div>
            <div>
              <p className="text-xs text-foreground/50 mb-1">Created</p>
              <p className="text-sm">{new Date(lead.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          {/* iOS 18 Style Activity Badges */}
          <div className="flex flex-wrap gap-2">
            {lead.hasAppointment && (
              <Badge variant="secondary" className="bg-blue-500/10 text-blue-600 dark:text-blue-400">
                <Calendar className="w-3 h-3 mr-1" /> Appointment Booked
              </Badge>
            )}
            {lead.hasFormSubmission && (
              <Badge variant="secondary" className="bg-purple-500/10 text-purple-600 dark:text-purple-400">
                <ClipboardCheck className="w-3 h-3 mr-1" /> Form Submitted
              </Badge>
            )}
            {lead.hasTransfer && (
              <Badge variant="secondary" className="bg-violet-500/10 text-violet-600 dark:text-violet-400">
                <PhoneForwarded className="w-3 h-3 mr-1" /> Transferred
              </Badge>
            )}
            {lead.hasCallback && (
              <Badge variant="secondary" className="bg-amber-500/10 text-amber-600 dark:text-amber-400">
                <PhoneCall className="w-3 h-3 mr-1" /> Callback Scheduled
              </Badge>
            )}
          </div>

          {/* iOS 18 Style Recording Section */}
          {lead.recordingUrl && (
            <div className="p-4 rounded-2xl bg-foreground/[0.02] border border-border/30">
              <p className="text-xs text-foreground/50 mb-2">Recording</p>
              <div className="flex items-center gap-3">
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => {
                    const audio = document.getElementById(`audio-${lead.id}`) as HTMLAudioElement;
                    if (audio) {
                      if (isPlaying) {
                        audio.pause();
                      } else {
                        audio.play();
                      }
                      setIsPlaying(!isPlaying);
                    }
                  }}
                  data-testid="play-recording-button"
                >
                  {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
                </Button>
                <audio id={`audio-${lead.id}`} src={lead.recordingUrl} onEnded={() => setIsPlaying(false)} className="hidden" />
                <span className="text-sm text-foreground/60">Call Recording</span>
              </div>
            </div>
          )}

          {/* iOS 18 Style AI Summary */}
          {lead.aiSummary && (
            <div className="p-4 rounded-2xl bg-foreground/[0.02] border border-border/30">
              <p className="text-xs text-foreground/50 mb-2">AI Summary</p>
              <p className="text-sm text-foreground/70 leading-relaxed" data-testid="lead-ai-summary">{lead.aiSummary}</p>
            </div>
          )}

          {/* iOS 18 Style Transcript */}
          {lead.transcript && (
            <div className="p-4 rounded-2xl bg-foreground/[0.02] border border-border/30">
              <p className="text-xs text-foreground/50 mb-2">Transcript</p>
              <ScrollArea className="h-48">
                <pre className="text-xs whitespace-pre-wrap font-sans text-foreground/60" data-testid="lead-transcript">{lead.transcript}</pre>
              </ScrollArea>
            </div>
          )}

          {/* iOS 18 Style Tabs */}
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsList className="w-full bg-foreground/[0.04] rounded-xl p-1">
              <TabsTrigger value="notes" className="flex-1 rounded-lg data-[state=active]:bg-background data-[state=active]:shadow-sm" data-testid="tab-notes">
                <MessageSquare className="w-4 h-4 mr-2" />
                Notes ({notes.length})
              </TabsTrigger>
              <TabsTrigger value="activity" className="flex-1 rounded-lg data-[state=active]:bg-background data-[state=active]:shadow-sm" data-testid="tab-activity">
                <History className="w-4 h-4 mr-2" />
                Activity ({activities.length})
              </TabsTrigger>
            </TabsList>

            <TabsContent value="notes" className="mt-4" data-testid="notes-section">
              {notesLoading ? (
                <div className="flex items-center justify-center py-4" data-testid="notes-loading">
                  <Loader2 className="w-4 h-4 animate-spin text-foreground/40" />
                </div>
              ) : notes.length > 0 ? (
                <div className="space-y-3 mb-4" data-testid="notes-list">
                  {notes.map((note, index) => (
                    <div key={note.id} className="p-3.5 rounded-xl bg-foreground/[0.03] border border-border/20" data-testid={`note-item-${index}`}>
                      <p className="text-sm text-foreground/80" data-testid={`note-content-${index}`}>{note.content}</p>
                      <p className="text-xs text-foreground/40 mt-2" data-testid={`note-date-${index}`}>
                        {new Date(note.createdAt).toLocaleString()}
                      </p>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-sm text-foreground/50 mb-4" data-testid="notes-empty">No notes yet</p>
              )}

              <div className="space-y-3">
                <Textarea 
                  placeholder="Add a note about this lead..."
                  value={noteText}
                  onChange={(e) => setNoteText(e.target.value)}
                  className="min-h-[80px]"
                  data-testid="lead-note-input"
                />
                <Button 
                  onClick={() => noteText.trim() && addNoteMutation.mutate(noteText.trim())}
                  disabled={!noteText.trim() || addNoteMutation.isPending}
                  data-testid="add-note-button"
                >
                  {addNoteMutation.isPending ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                  Add Note
                </Button>
              </div>
            </TabsContent>

            <TabsContent value="activity" className="mt-4" data-testid="activity-section">
              {activitiesLoading ? (
                <div className="flex items-center justify-center py-4">
                  <Loader2 className="w-4 h-4 animate-spin text-foreground/40" />
                </div>
              ) : activities.length > 0 ? (
                <ScrollArea className="h-64">
                  <div className="space-y-2" data-testid="activity-list">
                    {activities.map((activity, index) => (
                      <div key={activity.id} className="flex gap-3 p-3 rounded-xl bg-foreground/[0.03] border border-border/20" data-testid={`activity-item-${index}`}>
                        <div className="flex items-center justify-center w-8 h-8 rounded-lg bg-foreground/[0.06] shrink-0">
                          {getActivityIcon(activity.activityType)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-foreground/80">{activity.title}</p>
                          {activity.description && (
                            <p className="text-xs text-foreground/50 mt-1">{activity.description}</p>
                          )}
                          <p className="text-xs text-foreground/40 mt-1">
                            {new Date(activity.createdAt).toLocaleString()}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              ) : (
                <p className="text-sm text-foreground/50">No activity recorded yet</p>
              )}
            </TabsContent>
          </Tabs>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose} data-testid="close-lead-modal">Close</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function ListViewCard({ lead, onClick, stageColor, isSelected, onToggleSelect }: { 
  lead: Lead; 
  onClick: () => void; 
  stageColor?: string;
  isSelected?: boolean;
  onToggleSelect?: (leadId: string) => void;
}) {
  // Show name if available, otherwise show phone number as the display name
  const fullName = [lead.firstName, lead.lastName].filter(Boolean).join(" ");
  const hasValidPhone = lead.phone && lead.phone !== 'Unknown';
  const displayName = fullName || (hasValidPhone ? lead.phone : "Unknown Contact");
  const initials = fullName 
    ? fullName.split(" ").map(n => n[0]).join("").slice(0, 2).toUpperCase() 
    : (hasValidPhone ? lead.phone!.slice(-2) : "??");
  const theme = getStageTheme(lead.stage, stageColor);

  const borderStyle = stageColor && stageColor !== "#6B7280" 
    ? { borderLeftColor: stageColor } 
    : undefined;

  return (
    <Card 
      className={`cursor-pointer hover-elevate transition-all rounded-2xl border-border/30 bg-card/50 ${isSelected ? 'ring-2 ring-primary' : ''}`}
      onClick={onClick}
      data-testid={`list-lead-${lead.id}`}
    >
      <CardContent className="p-3.5">
        <div className="flex items-center gap-3">
          {onToggleSelect && (
            <Checkbox
              checked={isSelected}
              onCheckedChange={() => onToggleSelect(lead.id)}
              onClick={(e) => e.stopPropagation()}
              className="shrink-0"
              data-testid={`select-list-lead-${lead.id}`}
            />
          )}
          <Avatar className="h-9 w-9 shrink-0">
            <AvatarFallback className="text-xs font-medium bg-muted">
              {initials}
            </AvatarFallback>
          </Avatar>

          <div className="flex-1 min-w-0">
            <h4 className="font-medium text-sm truncate">{displayName}</h4>
            {fullName && hasValidPhone && (
              <p className="text-xs text-muted-foreground font-mono">{lead.phone}</p>
            )}
          </div>

          <ScoreIndicator score={lead.leadScore} />

          <ActivityIndicators lead={lead} />

          <Badge variant="secondary" className="rounded-full">
            {lead.stage.replace(/_/g, " ")}
          </Badge>

          <span className="text-xs text-muted-foreground whitespace-nowrap">
            {new Date(lead.createdAt).toLocaleDateString()}
          </span>
        </div>
      </CardContent>
    </Card>
  );
}

// CRM Filter Settings Dialog Component with local state buffering
function CRMFilterSettingsDialog({
  open,
  onOpenChange,
  categoryPreferences,
  stages,
  onSave,
  isSaving,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  categoryPreferences?: CrmCategoryPreferences;
  stages: LeadStage[];
  onSave: (settings: {
    hideLeadsWithoutPhone?: boolean;
    hotScoreThreshold?: number;
    warmScoreThreshold?: number;
    hiddenCategories?: string[];
  }) => void;
  isSaving: boolean;
}) {
  // Local state for buffering changes
  const [localSettings, setLocalSettings] = useState({
    hideLeadsWithoutPhone: false,
    hotScoreThreshold: 80,
    warmScoreThreshold: 50,
    hiddenCategories: [] as string[],
  });

  // Sync local state when dialog opens or preferences change
  useEffect(() => {
    if (open && categoryPreferences) {
      setLocalSettings({
        hideLeadsWithoutPhone: categoryPreferences.hideLeadsWithoutPhone ?? false,
        hotScoreThreshold: categoryPreferences.hotScoreThreshold ?? 80,
        warmScoreThreshold: categoryPreferences.warmScoreThreshold ?? 50,
        hiddenCategories: categoryPreferences.hiddenCategories ?? [],
      });
    }
  }, [open, categoryPreferences]);

  const handleSave = () => {
    onSave(localSettings);
    onOpenChange(false);
  };

  const toggleCategory = (catId: string) => {
    setLocalSettings(prev => ({
      ...prev,
      hiddenCategories: prev.hiddenCategories.includes(catId)
        ? prev.hiddenCategories.filter(id => id !== catId)
        : [...prev.hiddenCategories, catId],
    }));
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg" data-testid="filter-settings-modal">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            CRM Filter Settings
          </DialogTitle>
          <DialogDescription>
            Configure how leads are displayed and filtered in your CRM.
          </DialogDescription>
        </DialogHeader>

        <ScrollArea className="max-h-[60vh]">
          <div className="space-y-6 py-4 pr-4">
            {/* Hide leads without phone toggle */}
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label className="text-sm font-medium">Hide leads without phone</Label>
                <p className="text-xs text-muted-foreground">
                  Only show leads that have a valid phone number
                </p>
              </div>
              <Switch
                checked={localSettings.hideLeadsWithoutPhone}
                onCheckedChange={(checked) => {
                  setLocalSettings(prev => ({ ...prev, hideLeadsWithoutPhone: checked }));
                }}
                data-testid="toggle-hide-no-phone"
              />
            </div>

            <Separator />

            {/* Score Thresholds */}
            <div className="space-y-4">
              <Label className="text-sm font-medium">Lead Score Thresholds</Label>
              <p className="text-xs text-muted-foreground mb-4">
                Define score ranges for Hot and Warm lead classifications
              </p>

              <div className="space-y-4">
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <Flame className="w-4 h-4 text-orange-500" />
                      <span className="text-sm">Hot Lead Threshold</span>
                    </div>
                    <span className="text-sm font-medium">{localSettings.hotScoreThreshold}+</span>
                  </div>
                  <Slider
                    value={[localSettings.hotScoreThreshold]}
                    onValueChange={([value]) => {
                      setLocalSettings(prev => ({ ...prev, hotScoreThreshold: value }));
                    }}
                    min={50}
                    max={100}
                    step={5}
                    className="w-full"
                    data-testid="slider-hot-threshold"
                  />
                </div>

                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <TrendingUp className="w-4 h-4 text-yellow-500" />
                      <span className="text-sm">Warm Lead Threshold</span>
                    </div>
                    <span className="text-sm font-medium">{localSettings.warmScoreThreshold}+</span>
                  </div>
                  <Slider
                    value={[localSettings.warmScoreThreshold]}
                    onValueChange={([value]) => {
                      setLocalSettings(prev => ({ ...prev, warmScoreThreshold: value }));
                    }}
                    min={20}
                    max={79}
                    step={5}
                    className="w-full"
                    data-testid="slider-warm-threshold"
                  />
                </div>
              </div>
            </div>

            <Separator />

            {/* Hidden Categories */}
            <div className="space-y-3">
              <Label className="text-sm font-medium">Visible Categories</Label>
              <p className="text-xs text-muted-foreground mb-2">
                Choose which AI categories to show in the kanban view
              </p>
              <div className="grid grid-cols-2 gap-2">
                {AI_CATEGORIES.map((cat) => {
                  const isHidden = localSettings.hiddenCategories.includes(cat.id);
                  return (
                    <div
                      key={cat.id}
                      className="flex items-center gap-2 p-2 rounded-md border hover-elevate cursor-pointer"
                      onClick={() => toggleCategory(cat.id)}
                      data-testid={`toggle-category-${cat.id}`}
                    >
                      {isHidden ? (
                        <EyeOff className="w-4 h-4 text-muted-foreground" />
                      ) : (
                        <Eye className="w-4 h-4 text-primary" />
                      )}
                      <span className={`text-sm ${isHidden ? 'text-muted-foreground' : ''}`}>
                        {cat.label}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

          </div>
        </ScrollArea>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button variant="outline" onClick={() => onOpenChange(false)} data-testid="cancel-filter-settings">
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isSaving} data-testid="save-filter-settings">
            {isSaving ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
            Save Settings
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export default function CRMPage() {
  const { toast } = useToast();
  const queryClientRef = useQueryClient();
  const searchString = useSearch();
  const validViews = ["list", "analytics"] as const;
  const urlViewRaw = new URLSearchParams(searchString).get('view');
  const urlViewParam = validViews.includes(urlViewRaw as any) ? (urlViewRaw as "list" | "analytics") : null;
