    if (normalizedUpdates.paystackYearlyPrice !== undefined) {
      const val = normalizedUpdates.paystackYearlyPrice;
      if (val === null || (typeof val === 'number' && (isNaN(val) || val === 0))) {
        normalizedUpdates.paystackYearlyPrice = null;
      }
    }
    // MercadoPago
