export type Status = 
  | "pending" 
  | "in_progress" 
  | "completed" 
  | "failed" 
  | "warm" 
  | "cold" 
  | "hot" 
  | "calling"
  | "scheduled"
  | "draft"
  | "running"
  | "paused";

interface StatusBadgeProps {
  status: Status;
  label?: string;
}

const statusConfig = {
  pending: {
    icon: Clock,
    variant: "secondary" as const,
    label: "Pending",
  },
  in_progress: {
    icon: Phone,
    variant: "default" as const,
    label: "In Progress",
  },
  calling: {
    icon: Phone,
    variant: "default" as const,
    label: "Calling",
  },
  completed: {
    icon: CheckCircle2,
    variant: "secondary" as const,
    label: "Completed",
  },
  failed: {
    icon: XCircle,
    variant: "destructive" as const,
    label: "Failed",
  },
  scheduled: {
    icon: Clock,
    variant: "secondary" as const,
    label: "Scheduled",
  },
  warm: {
    icon: Circle,
    variant: "secondary" as const,
    label: "Warm Lead",
    color: "text-warning",
  },
  cold: {
    icon: Circle,
    variant: "secondary" as const,
    label: "Cold Lead",
    color: "text-info",
  },
  hot: {
    icon: Circle,
    variant: "secondary" as const,
    label: "Hot Lead",
    color: "text-destructive",
  },
  draft: {
    icon: Circle,
    variant: "outline" as const,
    label: "Draft",
  },
  running: {
    icon: Phone,
    variant: "default" as const,
    label: "Running",
  },
  paused: {
    icon: PhoneOff,
    variant: "secondary" as const,
    label: "Paused",
  },
};

export function StatusBadge({ status, label }: StatusBadgeProps) {
  const config = statusConfig[status] || {
    icon: Circle,
    variant: "outline" as const,
    label: status,
  };
  const Icon = config.icon;
  const displayLabel = label || config.label;
  const iconColor = "color" in config ? config.color : "";

  return (
    <Badge variant={config.variant} className="gap-1.5" data-testid={`badge-status-${status}`}>
      <Icon className={`h-3 w-3 ${iconColor}`} />
      {displayLabel}
    </Badge>
  );
}

