  | 'ringing'
  | 'in-progress'
  | 'completed'
  | 'busy'
  | 'failed'
  | 'no-answer'
  | 'canceled';

export type CallDirection = 'inbound' | 'outbound';

export type CallSentiment = 'positive' | 'neutral' | 'negative';

export interface TwilioOpenAICall {
  id: string;

  userId: string | null;
