          </TabsTrigger>
          <TabsTrigger value="addresses" data-testid="tab-addresses">
            <MapPin className="h-4 w-4 mr-2" />
            Addresses
          </TabsTrigger>
          {isRestApiPluginEnabled && (
            <TabsTrigger value="developer" data-testid="tab-developer">
