  return {
    type: "webhook",
    name: toolName,
    description: "Book an appointment for the caller. Use this tool when the caller wants to schedule an appointment. Collect the date, time, and their contact information before calling this tool.",
    api_schema: {
      url: webhookUrl,
      method: "POST",
      headers: {
