            </div>
          </CardContent>
        </Card>

        {/* 8. KYC Verification Requirements */}
        <Card>
          <CardHeader className="pb-4">
            <div className="flex items-center gap-3">
              <ShieldAlert className="h-5 w-5" />
              <div>
                <CardTitle className="text-lg">KYC Verification Requirements</CardTitle>
