    // Razorpay
    if (normalizedUpdates.razorpayMonthlyPrice !== undefined) {
      const val = normalizedUpdates.razorpayMonthlyPrice;
      if (val === null || (typeof val === 'number' && (isNaN(val) || val === 0))) {
        normalizedUpdates.razorpayMonthlyPrice = null;
      }
