      const result = await response.json();

      toast({
        title: result.alreadyExists ? "Invoice Exists" : "Invoice Generated",
        description: `Invoice ${result.invoice?.invoiceNumber || ""} ${result.alreadyExists ? "already exists" : "has been generated"}`,
      });

