interface PermissionActions {
  canCreate: boolean;
  canRead: boolean;
  canUpdate: boolean;
  canDelete: boolean;
}

interface TeamMemberPermissions {
  [sectionId: string]: {
    [subsectionId: string]: PermissionActions;
  };
}

interface TeamMemberData {
  id: string;
  email: string;
  firstName?: string;
  lastName?: string;
  role?: {
    id: string;
    name: string;
    permissions?: TeamMemberPermissions;
  };
}

interface TeamData {
  id: string;
  name: string;
  type: 'user' | 'admin';
  parentUserId?: string;
}

interface TeamAuthResponse {
  member: TeamMemberData;
  team: TeamData;
  permissions: TeamMemberPermissions;
}

