   */
  static async getPurchasedRoutes(): Promise<Array<{
    connectionName: string;
    techPrefix: string;
    accountName: string;
    tariffId: number;
    connectionId: number;
    vendorId: number;
    vendorName: string;
    blocked: boolean;
    status: string;
