      amount: inrPrice,
      currency: 'INR',
      receipt,
      notes: {
        userId,
        packageId,
        credits: pkg.credits.toString(),
        type: 'credits',
        customer_name: user.billingName || user.name || '',
        customer_email: user.email || '',
        billing_address_line1: user.billingAddressLine1 || '',
        billing_address_line2: user.billingAddressLine2 || '',
