  qualifiedLeads: number;
  avgDuration: number;
  leadDistribution: Array<{ name: string; value: number }>;
  sentimentDistribution: Array<{ name: string; value: number }>;
  campaignPerformance: Array<{ name: string; value: number }>;
  dailyCalls: Array<{ date: string; count: number }>;
  typeBreakdown?: TypeBreakdown;
}

export default function Analytics() {
  const { t } = useTranslation();
  const [timeRange, setTimeRange] = useState("7days");
  const [callType, setCallType] = useState("all");
  const [isExporting, setIsExporting] = useState(false);
  const reportRef = useRef<HTMLDivElement>(null);
  const { toast } = useToast();
  const currentUser = AuthStorage.getUser();
  const isAdmin = currentUser?.role === 'admin';

  const { data: analytics, isLoading, error } = useQuery<AnalyticsData>({
    queryKey: ['/api/analytics', timeRange, callType],
    queryFn: async () => {
      const headers: Record<string, string> = {};
      const authHeader = AuthStorage.getAuthHeader();
      if (authHeader) {
        headers['Authorization'] = authHeader;
      }
      const response = await fetch(`/api/analytics?timeRange=${timeRange}&callType=${callType}`, {
        credentials: 'include',
        headers
      });
      if (!response.ok) throw new Error('Failed to fetch analytics');
      return response.json();
    }
  });

  const formatDuration = (seconds: number) => {
    if (!seconds) return "0:00";
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const getTimeRangeLabel = () => {
    switch (timeRange) {
      case '7days': return t('analytics.timeRange.last7Days');
      case '30days': return t('analytics.timeRange.last30Days');
      case '90days': return t('analytics.timeRange.last90Days');
      case 'year': return t('analytics.timeRange.thisYear');
      default: return t('analytics.timeRange.last7Days');
    }
  };

  const getCallTypeLabel = () => {
    switch (callType) {
      case 'all': return t('analytics.callTypes.all');
      case 'incoming': return t('analytics.callTypes.incoming');
      case 'outgoing': return t('analytics.callTypes.outgoing');
      case 'batch': return t('analytics.callTypes.campaigns');
      default: return t('analytics.callTypes.all');
    }
  };

  const handleExportPDF = async () => {
    setIsExporting(true);
    try {
      const response = await apiRequest('POST', '/api/analytics/export-pdf', {
        timeRange,
        callType
      });

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `analytics-report-${new Date().toISOString().split('T')[0]}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
      toast({
        title: t('analytics.toast.reportExported'),
        description: t('analytics.toast.reportExportedDesc')
      });
    } catch (error) {
      toast({
        title: t('analytics.toast.exportFailed'),
        description: t('analytics.toast.exportFailedDesc'),
        variant: "destructive"
      });
    } finally {
      setIsExporting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const {
    totalCalls = 0,
    successRate = 0,
    qualifiedLeads = 0,
    avgDuration = 0,
    leadDistribution = [],
    sentimentDistribution = [],
    campaignPerformance = [],
    dailyCalls = [],
    typeBreakdown = { incoming: 0, outgoing: 0, batch: 0, campaigns: 0, total: 0 }
  } = analytics || {};

  const formattedDailyCalls = dailyCalls.map(d => ({
    name: new Date(d.date).toLocaleDateString('en-US', { weekday: 'short' }),
    value: d.count
  }));

  const getCallVolumeTitle = () => {
    if (timeRange === 'year') return t('analytics.monthlyCallVolume');
    if (timeRange === '30days' || timeRange === '90days') return t('analytics.weeklyCallVolume');
    return t('analytics.dailyCallVolume');
  };

  const callTypes = [
    { value: 'all', label: t('analytics.callTypes.all'), labelShort: t('analytics.callTypes.allShort'), icon: Phone, count: typeBreakdown.total },
    { value: 'incoming', label: t('analytics.callTypes.incoming'), labelShort: t('analytics.callTypes.incomingShort'), icon: PhoneIncoming, count: typeBreakdown.incoming },
    { value: 'outgoing', label: t('analytics.callTypes.outgoing'), labelShort: t('analytics.callTypes.outgoingShort'), icon: PhoneOutgoing, count: typeBreakdown.outgoing },
    { value: 'batch', label: t('analytics.callTypes.campaigns'), labelShort: t('analytics.callTypes.campaignsShort'), icon: Target, count: typeBreakdown.batch },
  ];

  const callTypeItems = [
    { value: 'all', label: t('analytics.callTypes.all'), icon: Phone, count: typeBreakdown.total },
    { value: 'incoming', label: t('analytics.callTypes.incoming'), icon: PhoneIncoming, count: typeBreakdown.incoming },
    { value: 'outgoing', label: t('analytics.callTypes.outgoing'), icon: PhoneOutgoing, count: typeBreakdown.outgoing },
    { value: 'batch', label: t('analytics.callTypes.campaigns'), icon: Target, count: typeBreakdown.batch },
  ];

  const subPanelContent = (
    <div className="space-y-1">
      <SubPanelSection title={t('analytics.callTypes.title', 'CALL TYPES')}>
        {callTypeItems.map((filter) => (
          <SubPanelItem
            key={filter.value}
            icon={<filter.icon className="w-4 h-4" />}
            label={filter.label}
            isActive={callType === filter.value}
            onClick={() => setCallType(filter.value)}
            badge={filter.count}
          />
        ))}
      </SubPanelSection>

      <SubPanelSection title={t('analytics.metrics', 'METRICS')}>
        <div className="px-2.5 py-2 space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">{t('analytics.successRate')}</span>
            <span className="font-medium text-emerald-600">{successRate}%</span>
          </div>
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground">{t('analytics.avgDurationLabel')}</span>
            <span className="font-medium">{formatDuration(avgDuration)}</span>
          </div>
        </div>
      </SubPanelSection>
    </div>
  );

  return (
    <ThreeColumnLayout 
      subPanel={subPanelContent} 
      subPanelWidth="sm"
      subPanelHeader={<span className="font-medium text-sm">{t('analytics.filters', 'Filters')}</span>}
    >
      <div className="space-y-6" ref={reportRef}>
        {/* iOS 18 Style Header - Clean and Minimal */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-2xl bg-foreground/[0.06] flex items-center justify-center">
              <BarChart3 className="h-6 w-6 text-foreground/70" />
            </div>
            <div>
              <h1 className="text-2xl font-semibold tracking-tight text-foreground" data-testid="text-analytics-title">
                {t('analytics.title')}
              </h1>
              <p className="text-sm text-foreground/50 mt-0.5">{t('analytics.subtitle')}</p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <Select value={timeRange} onValueChange={setTimeRange}>
              <SelectTrigger 
                className="w-[150px] h-10 rounded-xl border-border/40 bg-foreground/[0.03] hover:bg-foreground/[0.06] transition-colors" 
                data-testid="select-time-range"
              >
                <SelectValue placeholder={t('analytics.selectPeriod')} />
              </SelectTrigger>
              <SelectContent className="rounded-xl">
                <SelectItem value="7days">{t('analytics.timeRange.last7Days')}</SelectItem>
                <SelectItem value="30days">{t('analytics.timeRange.last30Days')}</SelectItem>
                <SelectItem value="90days">{t('analytics.timeRange.last90Days')}</SelectItem>
                <SelectItem value="year">{t('analytics.timeRange.thisYear')}</SelectItem>
              </SelectContent>
            </Select>
            <Button 
              variant="default"
              className="h-10 rounded-xl"
              onClick={handleExportPDF}
              disabled={isExporting}
              data-testid="button-export-report"
            >
              {isExporting ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <Download className="h-4 w-4 mr-2" />
              )}
              {t('analytics.exportReport')}
            </Button>
          </div>
        </div>

      {/* iOS 18 Style Pill Tabs */}
      <div className="flex flex-wrap gap-2" data-testid="tabs-call-type">
        {callTypes.map((type) => {
          const Icon = type.icon;
          const isActive = callType === type.value;
          return (
            <button
              key={type.value}
              onClick={() => setCallType(type.value)}
              className={cn(
                "flex items-center gap-2 px-4 py-2.5 rounded-2xl text-sm font-medium transition-all duration-200",
                isActive 
                  ? "bg-foreground/[0.08] text-foreground" 
                  : "text-foreground/60 hover:text-foreground hover:bg-foreground/[0.04]"
              )}
              data-testid={`tab-${type.value}-calls`}
            >
              <Icon className="h-4 w-4" />
              <span className="hidden sm:inline">{type.label}</span>
              <span className="sm:hidden">{type.labelShort}</span>
              {type.count > 0 && (
                <span className={cn(
                  "ml-1 text-xs px-2 py-0.5 rounded-full",
                  isActive 
                    ? "bg-foreground/[0.08] text-foreground" 
                    : "bg-foreground/[0.05] text-foreground/50"
                )}>
                  {type.count}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {/* Metrics Grid - iOS 18 Style Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard
          title={t('analytics.totalCalls')}
          value={totalCalls.toLocaleString()}
          icon={Phone}
          trend={totalCalls > 0 ? { value: 0, direction: "up" as const } : undefined}
          testId="metric-total-calls"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
          iconClassName="text-cyan-500"
        />
        <MetricCard
          title={t('analytics.successRate')}
          value={`${successRate}%`}
          icon={TrendingUp}
          trend={successRate > 0 ? { value: 0, direction: "up" as const } : undefined}
          testId="metric-success-rate"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
          iconClassName="text-emerald-500"
        />
        <MetricCard
          title={t('analytics.qualifiedLeads')}
          value={qualifiedLeads.toLocaleString()}
          icon={Users}
          trend={qualifiedLeads > 0 ? { value: 0, direction: "up" as const } : undefined}
          testId="metric-qualified-leads"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
          iconClassName="text-blue-500"
        />
        <MetricCard
          title={t('analytics.avgDurationLabel')}
          value={formatDuration(avgDuration)}
          icon={Clock}
          subtitle={t('analytics.minutesPerCall')}
          testId="metric-avg-duration"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
          iconClassName="text-violet-500"
        />
      </div>

      {/* Charts Grid - iOS 18 Style */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <AnalyticsChart 
          title={getCallVolumeTitle()} 
          type="bar" 
          data={formattedDailyCalls.length > 0 ? formattedDailyCalls : [{ name: t('analytics.noData'), value: 0 }]} 
          testId="chart-calls-this-week"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
        />
        <AnalyticsChart 
          title={t('analytics.leadDistribution')} 
          type="pie" 
          data={leadDistribution.length > 0 ? leadDistribution : [{ name: t('analytics.noData'), value: 1 }]} 
          testId="chart-lead-distribution"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <AnalyticsChart 
          title={t('analytics.campaignSuccessRate')} 
          type="bar" 
          data={campaignPerformance.length > 0 ? campaignPerformance : [{ name: t('analytics.noCampaigns'), value: 0 }]} 
          xAxisKey="name"
          dataKey="value"
          testId="chart-campaign-success"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
        />
        <AnalyticsChart 
          title={t('analytics.sentimentAnalysis')} 
          type="pie" 
          data={sentimentDistribution.length > 0 ? sentimentDistribution : [{ name: t('analytics.noData'), value: 1 }]} 
          testId="chart-sentiment-analysis"
          gradientClassName="rounded-2xl bg-foreground/[0.02] border-border/30"
        />
      </div>

      {/* Call Type Breakdown - iOS 18 Style */}
      {callType === 'all' && typeBreakdown.total > 0 && (
        <div className="rounded-2xl bg-foreground/[0.02] border border-border/30 p-6" data-testid="card-call-breakdown">
          <h3 className="text-base font-semibold text-foreground mb-5">{t('analytics.callTypeBreakdown')}</h3>
          <div className="grid grid-cols-3 gap-4">
            <div className="p-4 rounded-2xl bg-foreground/[0.03] border border-border/20">
              <div className="flex items-center justify-center gap-2 mb-2">
                <div className="h-8 w-8 rounded-xl bg-emerald-500/10 flex items-center justify-center">
                  <PhoneIncoming className="h-4 w-4 text-emerald-500" />
                </div>
              </div>
              <p className="text-center text-sm text-foreground/50 mb-1">{t('analytics.callTypes.incoming')}</p>
              <p className="text-center text-2xl font-bold text-foreground" data-testid="breakdown-incoming">
                {typeBreakdown.incoming}
              </p>
            </div>
            <div className="p-4 rounded-2xl bg-foreground/[0.03] border border-border/20">
              <div className="flex items-center justify-center gap-2 mb-2">
                <div className="h-8 w-8 rounded-xl bg-blue-500/10 flex items-center justify-center">
                  <PhoneOutgoing className="h-4 w-4 text-blue-500" />
                </div>
              </div>
              <p className="text-center text-sm text-foreground/50 mb-1">{t('analytics.callTypes.outgoing')}</p>
              <p className="text-center text-2xl font-bold text-foreground" data-testid="breakdown-outgoing">
                {typeBreakdown.outgoing}
              </p>
            </div>
            <div className="p-4 rounded-2xl bg-foreground/[0.03] border border-border/20">
              <div className="flex items-center justify-center gap-2 mb-2">
                <div className="h-8 w-8 rounded-xl bg-violet-500/10 flex items-center justify-center">
                  <Target className="h-4 w-4 text-violet-500" />
                </div>
              </div>
              <p className="text-center text-sm text-foreground/50 mb-1">{t('analytics.callTypes.campaigns')}</p>
              <p className="text-center text-2xl font-bold text-foreground" data-testid="breakdown-campaigns">
                {typeBreakdown.batch}
              </p>
            </div>
          </div>
        </div>
      )}
      </div>
    </ThreeColumnLayout>
  );
}

server/services/crm-lead.service.ts.content:
'use strict';
import { db } from '../db';
import { leads, leadStages, contacts, plivoCalls, twilioOpenaiCalls, campaigns, incomingConnections, agents } from '@shared/schema';
import { eq, and, or, asc } from 'drizzle-orm';
import { nanoid } from 'nanoid';
import OpenAI from 'openai';

interface CallData {
  userId: string;
  callId: string;
  engine: 'plivo' | 'twilio-openai' | 'twilio-elevenlabs';
  sourceType: 'campaign' | 'incoming';
  campaignId?: string | null;
  incomingConnectionId?: string | null;
  phone: string;
  firstName?: string | null;
  lastName?: string | null;
  email?: string | null;
  transcript?: string | null;
  aiSummary?: string | null;
  sentiment?: string | null;
  classification?: string | null;
  duration?: number | null;
  recordingUrl?: string | null;
  toolsExecuted?: {
    appointment?: boolean;
    formSubmission?: boolean;
    transfer?: boolean;
    callback?: boolean;
  };
  metadata?: Record<string, unknown>;
}

interface LeadScoreResult {
  score: number;
  stage: string;
  summary: string;
  suggestedNextAction?: string;
}

export class CRMLeadService {
  static async createLeadFromCall(callData: CallData): Promise<{ leadId: string } | null> {
    try {
      // Guard against missing identifiers
      if (callData.sourceType === 'campaign' && !callData.campaignId) {
        console.log('[CRM] Skipping lead creation - campaign call missing campaignId');
        return null;
      }
      if (callData.sourceType === 'incoming' && !callData.incomingConnectionId) {
        console.log('[CRM] Skipping lead creation - incoming call missing incomingConnectionId');
        return null;
      }

      const sourceConditions = callData.sourceType === 'campaign'
        ? and(
            eq(leads.userId, callData.userId),
            eq(leads.phone, callData.phone),
            eq(leads.sourceType, 'campaign'),
            eq(leads.campaignId, callData.campaignId!)
          )
        : and(
            eq(leads.userId, callData.userId),
            eq(leads.phone, callData.phone),
            eq(leads.sourceType, 'incoming'),
            eq(leads.incomingConnectionId, callData.incomingConnectionId!)
          );

      const existingLead = await db
        .select()
        .from(leads)
        .where(sourceConditions)
        .limit(1);

      if (existingLead.length > 0) {
        const lead = existingLead[0];
        const updateData: Record<string, unknown> = {
          updatedAt: new Date(),
        };

        if (callData.transcript) updateData.transcript = callData.transcript;
        if (callData.aiSummary) updateData.aiSummary = callData.aiSummary;
        if (callData.sentiment) updateData.sentiment = callData.sentiment;
        if (callData.recordingUrl) updateData.recordingUrl = callData.recordingUrl;
        if (callData.engine === 'plivo') {
          updateData.plivoCallId = callData.callId;
        } else if (callData.engine === 'twilio-openai') {
          updateData.twilioOpenaiCallId = callData.callId;
        } else {
          updateData.callId = callData.callId;
        }

        if (callData.toolsExecuted) {
          if (callData.toolsExecuted.appointment) updateData.hasAppointment = true;
          if (callData.toolsExecuted.formSubmission) updateData.hasFormSubmission = true;
          if (callData.toolsExecuted.transfer) updateData.hasTransfer = true;
          if (callData.toolsExecuted.callback) updateData.hasCallback = true;
        }

        await db
          .update(leads)
          .set(updateData)
          .where(eq(leads.id, lead.id));

        if (callData.transcript && callData.transcript.length > 50) {
          await this.updateLeadScore(lead.id, callData.userId, callData.transcript);
        }

        console.log(`[CRM] Updated existing lead ${lead.id} for ${callData.phone}`);
        return { leadId: lead.id };
      }

      let defaultStage = await db
        .select()
        .from(leadStages)
        .where(and(
          eq(leadStages.userId, callData.userId),
          eq(leadStages.isDefault, true)
        ))
        .limit(1);

      if (defaultStage.length === 0) {
        defaultStage = await db
          .select()
          .from(leadStages)
          .where(eq(leadStages.userId, callData.userId))
          .orderBy(asc(leadStages.order))
          .limit(1);
      }

      const stageName = defaultStage.length > 0 ? defaultStage[0].name : 'new';
      const stageId = defaultStage.length > 0 ? defaultStage[0].id : null;

      const leadId = nanoid();
      const leadData: Record<string, unknown> = {
        id: leadId,
        userId: callData.userId,
        sourceType: callData.sourceType,
        phone: callData.phone,
        firstName: callData.firstName || null,
        lastName: callData.lastName || null,
        email: callData.email || null,
        stage: stageName,
        stageId: stageId,
        leadScore: 50,
        aiSummary: callData.aiSummary || null,
        sentiment: callData.sentiment || null,
        transcript: callData.transcript || null,
        recordingUrl: callData.recordingUrl || null,
        hasAppointment: callData.toolsExecuted?.appointment || false,
        hasFormSubmission: callData.toolsExecuted?.formSubmission || false,
        hasTransfer: callData.toolsExecuted?.transfer || false,
        hasCallback: callData.toolsExecuted?.callback || false,
        customFields: callData.metadata || {},
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      if (callData.sourceType === 'campaign' && callData.campaignId) {
        leadData.campaignId = callData.campaignId;
      } else if (callData.sourceType === 'incoming' && callData.incomingConnectionId) {
        leadData.incomingConnectionId = callData.incomingConnectionId;
      }

      if (callData.engine === 'plivo') {
        leadData.plivoCallId = callData.callId;
      } else if (callData.engine === 'twilio-openai') {
        leadData.twilioOpenaiCallId = callData.callId;
      } else {
        leadData.callId = callData.callId;
      }

      await db.insert(leads).values(leadData as any);

      if (callData.transcript && callData.transcript.length > 50) {
        await this.updateLeadScore(leadId, callData.userId, callData.transcript);
      }

      console.log(`[CRM] Created new lead ${leadId} for ${callData.phone} from ${callData.sourceType}`);
      return { leadId };
    } catch (error: any) {
      console.error('[CRM] Error creating lead from call:', error.message);
      return null;
    }
  }

  static async updateLeadScore(leadId: string, userId: string, transcript: string): Promise<void> {
    try {
      const openaiApiKey = process.env.OPENAI_API_KEY;
      if (!openaiApiKey) {
        console.log('[CRM] No OpenAI API key for lead scoring');
        return;
      }

      const openai = new OpenAI({ apiKey: openaiApiKey });
      const scoreResult = await this.analyzeLeadFromTranscript(openai, transcript);

      if (scoreResult) {
        const userStages = await db
          .select()
          .from(leadStages)
          .where(eq(leadStages.userId, userId))
          .orderBy(asc(leadStages.order));

        let matchedStageId: string | null = null;
        let matchedStageName = scoreResult.stage;

        for (const stage of userStages) {
          if (stage.name.toLowerCase() === scoreResult.stage.toLowerCase()) {
            matchedStageId = stage.id;
            matchedStageName = stage.name;
            break;
          }
        }

        const updateData: Record<string, unknown> = {
          leadScore: scoreResult.score,
          aiSummary: scoreResult.summary,
          updatedAt: new Date(),
        };

        if (matchedStageId) {
          updateData.stage = matchedStageName;
          updateData.stageId = matchedStageId;
        }

        if (scoreResult.suggestedNextAction) {
          updateData.aiNextAction = scoreResult.suggestedNextAction;
        }

        await db
          .update(leads)
          .set(updateData)
          .where(eq(leads.id, leadId));

        console.log(`[CRM] Updated lead ${leadId} with score ${scoreResult.score} -> ${matchedStageName}`);
      }
    } catch (error: any) {
      console.error('[CRM] Error updating lead score:', error.message);
    }
  }

  static async analyzeLeadFromTranscript(openai: OpenAI, transcript: string): Promise<LeadScoreResult | null> {
    try {
      const prompt = `Analyze this sales/support call transcript and provide lead scoring.

TRANSCRIPT:
${transcript.substring(0, 4000)}

Analyze and return a JSON object with:
1. "score": Number 1-100 indicating lead quality/interest level
   - 80-100: Hot lead, high intent, ready to buy/book
   - 60-79: Warm lead, interested but needs follow-up
   - 40-59: Neutral, some interest but uncertain
   - 20-39: Cool lead, minimal interest
   - 1-19: Not interested or wrong number

2. "stage": One of these stages based on the conversation:
   - "hot" - Expressed strong interest or intent
   - "appointment" - Scheduled a meeting/demo
   - "form_submitted" - Provided information/signed up
   - "follow_up" - Requested callback or more info
   - "not_interested" - Declined or uninterested
   - "no_answer" - Voicemail or no response
   - "new" - Default for unclear outcomes

3. "summary": 2-3 sentence summary of the call outcome and lead status

4. "suggestedNextAction": Brief recommended next step (optional)

Return ONLY valid JSON:`;

      const response = await openai.chat.completions.create({
        model: 'gpt-4o-mini',
        messages: [{ role: 'user', content: prompt }],
        response_format: { type: 'json_object' },
        max_tokens: 500,
        temperature: 0.3,
      });

      const content = response.choices[0]?.message?.content;
      if (!content) return null;

      const result = JSON.parse(content);
      return {
        score: Math.max(1, Math.min(100, result.score || 50)),
        stage: result.stage || 'new',
        summary: result.summary || 'Call completed',
        suggestedNextAction: result.suggestedNextAction,
      };
    } catch (error: any) {
      console.error('[CRM] Error analyzing transcript:', error.message);
      return null;
    }
  }

  static async trackToolExecution(leadId: string, toolName: 'appointment' | 'form' | 'transfer' | 'callback'): Promise<void> {
    try {
      const updateData: Record<string, unknown> = {
        updatedAt: new Date(),
      };

      switch (toolName) {
        case 'appointment':
          updateData.hasAppointment = true;
          break;
        case 'form':
          updateData.hasFormSubmission = true;
          break;
        case 'transfer':
          updateData.hasTransfer = true;
          break;
        case 'callback':
          updateData.hasCallback = true;
          break;
      }

      await db
        .update(leads)
        .set(updateData)
        .where(eq(leads.id, leadId));

      console.log(`[CRM] Tracked tool execution: ${toolName} for lead ${leadId}`);
    } catch (error: any) {
      console.error('[CRM] Error tracking tool:', error.message);
    }
  }
}

