import { Pool } from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
import { eq } from "drizzle-orm";
import { db } from "../../db";
import { globalSettings } from "@shared/schema";

interface PoolSettings {
  minConnections: number;
  maxConnections: number;
  idleTimeoutMs: number;
}

interface PoolStats {
  total: number;
  idle: number;
  waiting: number;
}

export class DatabasePoolManager {
  private pool: Pool | null = null;
  private isInitialized = false;
  private settings: PoolSettings = {
    minConnections: 2,
    maxConnections: 20,
    idleTimeoutMs: 30000,
  };

  async initialize(): Promise<void> {
    if (this.isInitialized) {
      console.log("[DB Pool] Already initialized, skipping");
      return;
    }

    console.log("[DB Pool] Initializing connection pool...");

    await this.loadSettings();
    await this.createPool();

    this.isInitialized = true;
    console.log("[DB Pool] Initialization complete");
  }

  private async loadSettings(): Promise<void> {
    console.log("[DB Pool] Loading settings from globalSettings table...");

    try {
      const settings = await db
        .select()
        .from(globalSettings)
        .where(
          eq(globalSettings.key, "db_pool_min_connections")
        );

      const minConnectionsSetting = settings[0];

      const maxConnectionsResult = await db
        .select()
        .from(globalSettings)
        .where(eq(globalSettings.key, "db_pool_max_connections"));

      const idleTimeoutResult = await db
        .select()
        .from(globalSettings)
        .where(eq(globalSettings.key, "db_pool_idle_timeout_ms"));

      if (minConnectionsSetting?.value) {
        this.settings.minConnections = Number(minConnectionsSetting.value);
      }

      if (maxConnectionsResult[0]?.value) {
        this.settings.maxConnections = Number(maxConnectionsResult[0].value);
      }

      if (idleTimeoutResult[0]?.value) {
        this.settings.idleTimeoutMs = Number(idleTimeoutResult[0].value);
      }

      console.log(`[DB Pool] Settings loaded: min=${this.settings.minConnections}, max=${this.settings.maxConnections}, idleTimeout=${this.settings.idleTimeoutMs}ms`);
    } catch (error) {
      console.log(`[DB Pool] Failed to load settings, using defaults: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  private async createPool(): Promise<void> {
    if (!process.env.DATABASE_URL) {
      throw new Error("[DB Pool] DATABASE_URL environment variable is not set");
    }

    console.log("[DB Pool] Creating pool with dynamic configuration...");

    this.pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      min: this.settings.minConnections,
      max: this.settings.maxConnections,
      idleTimeoutMillis: this.settings.idleTimeoutMs,
    });

    this.setupEventListeners();

    console.log("[DB Pool] Pool created successfully");
  }

  private setupEventListeners(): void {
    if (!this.pool) return;

    this.pool.on("connect", (client) => {
      console.log("[DB Pool] New client connected");
    });

    this.pool.on("acquire", (client) => {
      console.log("[DB Pool] Client acquired from pool");
    });

    this.pool.on("remove", (client) => {
      console.log("[DB Pool] Client removed from pool");
    });

    this.pool.on("error", (err, client) => {
      console.log(`[DB Pool] Error on idle client: ${err.message}`);
    });

    console.log("[DB Pool] Event listeners configured");
  }

  async healthCheck(): Promise<{ healthy: boolean; message: string; stats?: PoolStats }> {
    if (!this.pool) {
      return {
        healthy: false,
        message: "Pool not initialized",
      };
    }

    try {
      const client = await this.pool.connect();
      const result = await client.query("SELECT 1 as health_check");
      client.release();

      if (result.rows[0]?.health_check === 1) {
        const stats = this.getStats();
        console.log("[DB Pool] Health check passed");
        return {
          healthy: true,
          message: "Database connection is healthy",
          stats,
        };
      }

      return {
        healthy: false,
        message: "Health check query returned unexpected result",
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.log(`[DB Pool] Health check failed: ${message}`);
      return {
        healthy: false,
        message: `Health check failed: ${message}`,
      };
    }
  }

  getStats(): PoolStats {
    if (!this.pool) {
      return {
        total: 0,
        idle: 0,
        waiting: 0,
      };
    }

    return {
      total: this.pool.totalCount,
      idle: this.pool.idleCount,
      waiting: this.pool.waitingCount,
    };
  }

  async shutdown(): Promise<void> {
    if (!this.pool) {
      console.log("[DB Pool] No pool to shut down");
      return;
    }

    console.log("[DB Pool] Initiating graceful shutdown...");

    try {
      await this.pool.end();
      this.pool = null;
      this.isInitialized = false;
      console.log("[DB Pool] Graceful shutdown complete");
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.log(`[DB Pool] Shutdown error: ${message}`);
      throw error;
    }
  }

  getPool(): Pool | null {
    return this.pool;
  }

  getDrizzle() {
    if (!this.pool) {
      throw new Error("[DB Pool] Pool not initialized. Call initialize() first.");
    }
    return drizzle(this.pool);
  }

  getSettings(): PoolSettings {
    return { ...this.settings };
  }

  isReady(): boolean {
    return this.isInitialized && this.pool !== null;
  }
}

export const databasePoolManager = new DatabasePoolManager();

/**
 * ============================================================
 * Platform Language Seed Script
 * Seeds all 11 default platform UI languages with complete translations.
 * Run with: npx tsx server/seed-platform-languages.ts
 * Use --force to reseed and overwrite existing languages
 * ============================================================
 */
import { db } from './db';
import { platformLanguages } from '@shared/schema';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';

interface LanguageConfig {
  code: string;
  name: string;
  nativeName: string;
  flag: string;
  direction: 'ltr' | 'rtl';
  isDefault: boolean;
  sortOrder: number;
}

const PLATFORM_LANGUAGES: LanguageConfig[] = [
  { code: 'en', name: 'English', nativeName: 'English', flag: '🇺🇸', direction: 'ltr', isDefault: true, sortOrder: 0 },
  { code: 'ar', name: 'Arabic', nativeName: 'العربية', flag: '🇸🇦', direction: 'rtl', isDefault: false, sortOrder: 1 },
  { code: 'de', name: 'German', nativeName: 'Deutsch', flag: '🇩🇪', direction: 'ltr', isDefault: false, sortOrder: 2 },
  { code: 'es', name: 'Spanish', nativeName: 'Español', flag: '🇪🇸', direction: 'ltr', isDefault: false, sortOrder: 3 },
  { code: 'fr', name: 'French', nativeName: 'Français', flag: '🇫🇷', direction: 'ltr', isDefault: false, sortOrder: 4 },
  { code: 'hi', name: 'Hindi', nativeName: 'हिन्दी', flag: '🇮🇳', direction: 'ltr', isDefault: false, sortOrder: 5 },
  { code: 'it', name: 'Italian', nativeName: 'Italiano', flag: '🇮🇹', direction: 'ltr', isDefault: false, sortOrder: 6 },
  { code: 'ja', name: 'Japanese', nativeName: '日本語', flag: '🇯🇵', direction: 'ltr', isDefault: false, sortOrder: 7 },
  { code: 'pl', name: 'Polish', nativeName: 'Polski', flag: '🇵🇱', direction: 'ltr', isDefault: false, sortOrder: 8 },
  { code: 'pt', name: 'Portuguese', nativeName: 'Português', flag: '🇧🇷', direction: 'ltr', isDefault: false, sortOrder: 9 },
  { code: 'sv', name: 'Swedish', nativeName: 'Svenska', flag: '🇸🇪', direction: 'ltr', isDefault: false, sortOrder: 10 },
];

function loadTranslations(code: string): Record<string, unknown> {
  const localesDir = path.join(process.cwd(), 'client', 'src', 'i18n', 'locales');
  const filePath = path.join(localesDir, `${code}.json`);

  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    return JSON.parse(content);
  } catch (error) {
    console.error(`Failed to load translations for ${code}:`, error);
    return {};
  }
}

export async function seedPlatformLanguages(force: boolean = false): Promise<{ success: boolean; message: string }> {
  try {
    const existing = await db.select().from(platformLanguages).limit(1);

    if (existing.length > 0 && !force) {
      return { 
        success: false, 
        message: 'Languages already exist. Use --force to reseed.' 
      };
    }

    if (force && existing.length > 0) {
      console.log('Force mode: Deleting existing languages...');
      await db.delete(platformLanguages);
    }

    console.log('Seeding platform UI languages...');

    for (const lang of PLATFORM_LANGUAGES) {
      const translations = loadTranslations(lang.code);

      console.log(`  Seeding ${lang.name} (${lang.code})...`);

      await db.insert(platformLanguages).values({
        code: lang.code,
        name: lang.name,
        nativeName: lang.nativeName,
        flag: lang.flag,
        direction: lang.direction,
        isEnabled: true,
        isDefault: lang.isDefault,
        sortOrder: lang.sortOrder,
        translations: translations,
        createdAt: new Date(),
        updatedAt: new Date(),
      });
    }

    console.log(`\nSuccessfully seeded ${PLATFORM_LANGUAGES.length} languages.`);
    return { 
      success: true, 
      message: `Seeded ${PLATFORM_LANGUAGES.length} languages successfully` 
    };
  } catch (error) {
    console.error('Error seeding languages:', error);
    return { 
      success: false, 
      message: `Failed to seed languages: ${error}` 
    };
  }
}

// Run directly if called as script (ES module compatible)
const isMainModule = process.argv[1] === fileURLToPath(import.meta.url);

if (isMainModule) {
  const force = process.argv.includes('--force');

  console.log('========================================');
  console.log('Platform Language Seeder');
  console.log('========================================');
  if (force) {
    console.log('Running in FORCE mode - will overwrite existing languages');
  }
  console.log('');

  seedPlatformLanguages(force)
    .then((result) => {
      console.log('');
      console.log(result.message);
      process.exit(result.success ? 0 : 1);
    })
    .catch((error) => {
      console.error('Seed failed:', error);
      process.exit(1);
    });
}

server/services/openai-voice-agent/hydra.content:
'use strict';
/**
 * ============================================================
 * Flow Hydrator Utility
 * 
 * Takes pre-compiled flow data from the flows table and creates
 * executable agent configurations with proper tool handlers.
 * 
 * This utility converts stored CompiledFunctionTool definitions
 * into runtime AgentTool objects with actual handler functions.
 * ============================================================
 */

import type { CompiledFunctionTool, CompiledConversationState } from '@shared/schema';
import { RAGKnowledgeService } from '../rag-knowledge';
import { db } from '../../db';
import { appointments, appointmentSettings, agents, formSubmissions, forms, formFields as formFieldsTable } from '@shared/schema';
import { eq, and } from 'drizzle-orm';
import { nanoid } from 'nanoid';

/**
 * Runtime AgentTool with handler function
 */
export interface AgentTool {
  name: string;
  description: string;
  parameters: Record<string, unknown>;
  handler: (params: Record<string, unknown>) => Promise<unknown>;
}

/**
 * Agent configuration with tool context
 */
export interface AgentConfigWithContext {
  voice: string;
  model: string;
  systemPrompt: string;
  firstMessage?: string;
  temperature?: number;
  tools: AgentTool[];
  toolContext?: ToolContext;
  knowledgeBaseIds?: string[];
}

/**
 * Context for tool execution
 */
export interface ToolContext {
  userId: string;
  agentId: string;
  callId?: string;
}

/**
 * Parameters for hydrating a compiled flow
 */
export interface HydrateFlowParams {
  compiledSystemPrompt: string;
  compiledFirstMessage: string | null;
  compiledTools: CompiledFunctionTool[];
  compiledStates: CompiledConversationState[];
  voice: string;
  model: string;
  temperature: number;
  toolContext: ToolContext;
  language?: string;
  knowledgeBaseIds?: string[];
  transferPhoneNumber?: string;
  transferEnabled?: boolean;
}

/**
 * Language code to name mapping
 */
const LANGUAGE_NAMES: Record<string, string> = {
  en: 'English',
  es: 'Spanish',
  fr: 'French',
  de: 'German',
  it: 'Italian',
  pt: 'Portuguese',
  nl: 'Dutch',
  pl: 'Polish',
  ru: 'Russian',
  ja: 'Japanese',
  ko: 'Korean',
  zh: 'Chinese',
  ar: 'Arabic',
  hi: 'Hindi',
  tr: 'Turkish',
  vi: 'Vietnamese',
  th: 'Thai',
  id: 'Indonesian',
  sv: 'Swedish',
  da: 'Danish',
  fi: 'Finnish',
  no: 'Norwegian',
  cs: 'Czech',
  el: 'Greek',
  he: 'Hebrew',
  hu: 'Hungarian',
  ro: 'Romanian',
  uk: 'Ukrainian',
};

/**
 * Get language name from code
 */
function getLanguageName(code: string): string {
  return LANGUAGE_NAMES[code] || code;
}

/**
 * Substitute {{variable}} placeholders in a value recursively
 */
function substituteVariables(
  template: unknown,
  params: Record<string, unknown>
): unknown {
  if (typeof template === 'string') {
    let result = template;
    const variablePattern = /\{\{(\w+)\}\}/g;
    let match;
    while ((match = variablePattern.exec(template)) !== null) {
      const varName = match[1];
      const value = params[varName];
      if (value !== undefined) {
        result = result.replace(match[0], String(value));
      }
    }
    return result;
  }
  if (Array.isArray(template)) {
    return template.map(item => substituteVariables(item, params));
  }
  if (template !== null && typeof template === 'object') {
    const result: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(template)) {
      result[key] = substituteVariables(value, params);
    }
    return result;
  }
  return template;
}

/**
 * Create end_call tool handler
 */
function createEndCallHandler(): (params: Record<string, unknown>) => Promise<unknown> {
  return async (params: Record<string, unknown>) => {
    console.log(`[End Call Tool] Ending call, reason: ${params.reason || 'conversation complete'}`);
    return { 
