                      </div>
                      <VoicePreviewButton
                        voiceId={formData.elevenLabsVoiceId}
                        voiceSettings={{
                          stability: formData.voiceStability,
                          similarity_boost: formData.voiceSimilarityBoost,
                          speed: formData.voiceSpeed,
