import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { 
  Plus, 
  Phone, 
  PhoneIncoming, 
  PhoneOutgoing, 
  Users,
  UserPlus,
  Loader2,
  Megaphone,
  Bot,
  Workflow,
  Flame,
  ThermometerSun,
  Snowflake,
  XCircle,
  Target,
  CheckCircle2,
  ArrowUp,
  ArrowDown,
  Contact2,
  Calendar,
  FileText,
  BookOpen,
  Webhook
} from "lucide-react";
import { useState } from "react";
import { CreateCampaignDialog } from "@/components/CreateCampaignDialog";
