          const yearlyPrice = yearlyPriceInfo.price !== "0" ? `${yearlyPriceInfo.symbol}${yearlyPriceInfo.price}` : null;

          const yearlySavings = monthlyPriceInfo.price && yearlyPriceInfo.price !== "0"
