import { storage } from "../storage";

// Default fallbacks - only used if database is unavailable
const DEFAULT_LOW_CREDITS_THRESHOLD = 50;
const DEFAULT_APP_NAME = '';

// Cache for low credits threshold to avoid repeated DB calls
let cachedLowCreditsThreshold: number | null = null;
let thresholdCacheTime: number = 0;
const THRESHOLD_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

// Cache for app name
let cachedAppName: string | null = null;
let appNameCacheTime: number = 0;

async function getLowCreditsThreshold(): Promise<number> {
  const now = Date.now();
  if (cachedLowCreditsThreshold !== null && (now - thresholdCacheTime) < THRESHOLD_CACHE_TTL) {
    return cachedLowCreditsThreshold;
  }

  try {
    const setting = await storage.getGlobalSetting('low_credits_threshold');
    const threshold = typeof setting?.value === 'number' ? setting.value : DEFAULT_LOW_CREDITS_THRESHOLD;
    cachedLowCreditsThreshold = threshold;
    thresholdCacheTime = now;
    return threshold;
  } catch (error) {
    console.error('[NotificationService] Failed to fetch low_credits_threshold, using default:', error);
    return DEFAULT_LOW_CREDITS_THRESHOLD;
  }
}

async function getAppName(): Promise<string> {
  const now = Date.now();
  if (cachedAppName !== null && (now - appNameCacheTime) < THRESHOLD_CACHE_TTL) {
    return cachedAppName;
  }

  try {
    const setting = await storage.getGlobalSetting('app_name');
    const appName = typeof setting?.value === 'string' ? setting.value : DEFAULT_APP_NAME;
    cachedAppName = appName;
    appNameCacheTime = now;
    return appName;
  } catch (error) {
    console.error('[NotificationService] Failed to fetch app_name, using default:', error);
    return DEFAULT_APP_NAME;
  }
}

export interface NotificationOptions {
  userId: string;
  type: string;
  title: string;
  message: string;
  link?: string;
  icon?: string;
  displayType?: 'bell' | 'banner' | 'both';
  priority?: number;
  dismissible?: boolean;
  expiresAt?: Date | null;
}

export const NotificationService = {
  async create(options: NotificationOptions) {
    try {
      await storage.createNotification({
        userId: options.userId,
        type: options.type,
        title: options.title,
        message: options.message,
        link: options.link || null,
        icon: options.icon || null,
        displayType: options.displayType || 'bell',
        priority: options.priority ?? 0,
        dismissible: options.dismissible ?? true,
        expiresAt: options.expiresAt || null,
      });
    } catch (error) {
      console.error("Failed to create notification:", error);
    }
  },

  async notifyLowCredits(userId: string, currentCredits: number) {
    await this.create({
      userId,
      type: "low_credits",
      title: "Low Credits Warning",
      message: `Your credit balance is low (${currentCredits} credits remaining). Purchase more credits to continue using phone numbers and making calls.`,
      link: "/app/billing",
    });
  },

  async notifyMembershipUpgraded(userId: string, planName: string) {
    await this.create({
      userId,
      type: "membership_upgraded",
      title: "Welcome to Pro",
      message: `Your membership has been upgraded to ${planName}. You now have unlimited agents, campaigns, and contacts!`,
      link: "/app/billing",
    });
  },

  async notifyMembershipCancelled(userId: string) {
    await this.create({
      userId,
      type: "membership_expiry",
      title: "Membership Cancelled",
      message: "Your Pro membership has been cancelled. You'll continue to have Pro access until the end of your billing period.",
      link: "/app/billing",
    });
  },

  async notifyCampaignCompleted(userId: string, campaignId: string, campaignName: string, callCount: number) {
    await this.create({
      userId,
      type: "campaign_completed",
      title: "Campaign Completed",
      message: `Campaign "${campaignName}" has completed with ${callCount} calls made.`,
      link: `/app/campaigns/${campaignId}`,
    });
  },

  async notifyCampaignFailed(userId: string, campaignId: string, campaignName: string, error: string) {
    await this.create({
      userId,
      type: "campaign_failed",
      title: "Campaign Failed",
      message: `Campaign "${campaignName}" failed: ${error}`,
      link: `/app/campaigns/${campaignId}`,
    });
  },

  async notifyCampaignPaused(userId: string, campaignId: string, campaignName: string, reason: string) {
    await this.create({
      userId,
      type: "campaign_paused",
      title: "Campaign Paused",
      message: `Campaign "${campaignName}" has been paused: ${reason}`,
      link: `/app/campaigns/${campaignId}`,
    });
  },

  async notifyPhoneBillingSuccess(userId: string, phoneNumber: string, creditsCharged: number) {
    await this.create({
      userId,
      type: "phone_billing_success",
      title: "Phone Number Renewed",
      message: `Phone number ${phoneNumber} has been renewed for ${creditsCharged} credits.`,
      link: "/app/phone-numbers",
    });
  },

  async notifyPhoneBillingFailed(userId: string, phoneNumber: string, reason: string) {
    await this.create({
      userId,
      type: "phone_billing_failed",
      title: "Phone Number Billing Failed",
      message: `Phone number ${phoneNumber} billing failed: ${reason}. The number has been released.`,
      link: "/app/phone-numbers",
    });
  },

  async notifyPhoneReleased(userId: string, phoneNumber: string) {
    await this.create({
      userId,
      type: "phone_released",
      title: "Phone Number Released",
      message: `Phone number ${phoneNumber} has been released due to insufficient credits.`,
      link: "/app/phone-numbers",
    });
  },

  async notifyWelcome(userId: string, userName: string) {
    const appName = await getAppName();
    await this.create({
      userId,
      type: "welcome",
      title: `Welcome to ${appName}, ${userName}`,
      message: "Get started by creating your first AI agent and launching a campaign. Check out our knowledge base for tips and best practices.",
      link: "/app/agents",
    });
  },

  async createNotificationForAllAdmins(options: Omit<NotificationOptions, "userId">) {
    try {
      // Get all admin users
      const adminUsers = await storage.getAllAdminUsers();

      // Create a notification for each admin
      for (const admin of adminUsers) {
        await this.create({
          ...options,
          userId: admin.id,
        });
      }
    } catch (error) {
      console.error("Failed to create admin notifications:", error);
    }
  },

  async notifyAdmins(title: string, message: string, severity: 'info' | 'warning' | 'critical' = 'info') {
    const icon = severity === 'critical' ? 'alert-triangle' : severity === 'warning' ? 'alert-circle' : 'info';
    await this.createNotificationForAllAdmins({
      type: `admin_${severity}`,
      title,
      message,
      icon,
      priority: severity === 'critical' ? 100 : severity === 'warning' ? 50 : 0,
      displayType: severity === 'critical' ? 'both' : 'bell',
    });
  },

  async notifyPaymentFailed(userId: string) {
    await this.create({
      userId,
      type: "payment_failed",
      title: "Payment Failed",
      message: "Your subscription payment failed. Please update your payment method to maintain your Pro membership.",
      link: "/app/billing",
      icon: "credit-card",
      priority: 80,
      displayType: 'both',
    });
  },

  async notifySubscriptionPastDue(userId: string) {
    await this.create({
      userId,
      type: "subscription_past_due",
      title: "Payment Overdue",
      message: "Your subscription is past due. Please update your payment method to avoid losing access to Pro features.",
      link: "/app/billing",
      icon: "alert-triangle",
      priority: 90,
      displayType: 'both',
    });
  },

  async shouldNotifyLowCredits(currentCredits: number): Promise<boolean> {
    const threshold = await getLowCreditsThreshold();
    return currentCredits > 0 && currentCredits <= threshold;
  },

  // Utility to get current threshold (for email service, etc.)
  async getLowCreditsThreshold(): Promise<number> {
    return getLowCreditsThreshold();
  },
};

server/services/phone-billing-cron.ts.content:
'use strict';
/**
 * ============================================================
 * © 2025 Diploy — a brand of Bisht Technologies Private Limited
 * Original Author: BTPL Engineering Team
 * Website: https://diploy.in
 * Contact: cs@diploy.in
 *
 * Distributed under the Envato / CodeCanyon License Agreement.
 * Licensed to the purchaser for use as defined by the
 * Envato Market (CodeCanyon) Regular or Extended License.
 *
 * You are NOT permitted to redistribute, resell, sublicense,
 * or share this source code, in whole or in part.
 * Respect the author's rights and Envato licensing terms.
 * ============================================================
 */
import { db } from "../db";
import { phoneNumbers, creditTransactions, phoneNumberRentals, campaigns } from "@shared/schema";
import { storage } from "../storage";
import { twilioService } from "./twilio";
import { lte, eq, sql } from "drizzle-orm";
import { NotificationService } from "./notification-service";
import { emailService } from "./email-service";

const BILLING_CHECK_INTERVAL = 60 * 60 * 1000; // Check every hour

/**
 * Get the phone number monthly cost from global settings
 */
async function getPhoneNumberMonthlyCost(): Promise<number> {
  const setting = await storage.getGlobalSetting('phone_number_monthly_credits');
  return (setting?.value as number) || 50; // Default to 50 if not configured
}

/**
 * Process monthly billing for all phone numbers with due billing dates
 * Runs as a cron job checking every hour
 */
export async function processPhoneNumberBilling() {
  console.log('📞 [Phone Billing] Starting monthly billing check...');

  try {
    // Get all active phone numbers with billing due (nextBillingDate <= now)
    const duePhoneNumbers = await db.select()
      .from(phoneNumbers)
      .where(
        sql`${phoneNumbers.nextBillingDate} <= NOW() AND ${phoneNumbers.status} = 'active'`
      );

    console.log(`📞 [Phone Billing] Found ${duePhoneNumbers.length} phone numbers due for billing`);

    for (const phoneNumber of duePhoneNumbers) {
      await processPhoneNumberRenewal(phoneNumber);
    }

    console.log('📞 [Phone Billing] Monthly billing check complete');
  } catch (error: any) {
    console.error('📞 [Phone Billing] Error processing monthly billing:', error);
  }
}

/**
 * Process renewal for a single phone number
 */
async function processPhoneNumberRenewal(phoneNumber: any) {
  console.log(`📞 [Phone Billing] Processing renewal for ${phoneNumber.phoneNumber}`);

  try {
    // Get user to check credits
    const user = await storage.getUser(phoneNumber.userId);
    if (!user) {
      console.error(`📞 [Phone Billing] User not found for phone number ${phoneNumber.id}`);
      return;
    }

    // Get monthly cost from phone number record, or fall back to global setting
    const defaultCost = await getPhoneNumberMonthlyCost();
    const monthlyCredits = phoneNumber.monthlyCredits || defaultCost;

    // Check if user has sufficient credits
    if ((user.credits || 0) >= monthlyCredits) {
      // Sufficient credits - deduct and renew
      await renewPhoneNumber(phoneNumber, user, monthlyCredits);
    } else {
      // Insufficient credits - disable and release
      await disablePhoneNumber(phoneNumber, user, monthlyCredits);
    }
  } catch (error: any) {
    console.error(`📞 [Phone Billing] Error processing renewal for ${phoneNumber.phoneNumber}:`, error);
  }
}

/**
 * Renew phone number by deducting credits and updating billing date
 */
async function renewPhoneNumber(phoneNumber: any, user: any, monthlyCredits: number) {
  console.log(`📞 [Phone Billing] Renewing ${phoneNumber.phoneNumber} (sufficient credits)`);

  try {
    // Atomic transaction: deduct credits, create rental record, update next billing date
    await db.transaction(async (tx) => {
      // Create debit transaction
      const [transaction] = await tx.insert(creditTransactions).values({
        userId: user.id,
        type: 'debit',
        amount: monthlyCredits,
        description: `Monthly phone number rental: ${phoneNumber.phoneNumber}`,
      }).returning();

      // Atomically deduct credits
      await tx.execute(sql`
        UPDATE users 
        SET credits = COALESCE(credits, 0) - ${monthlyCredits}
        WHERE id = ${user.id}
      `);

      // Create rental record
      await tx.insert(phoneNumberRentals).values({
        phoneNumberId: phoneNumber.id,
        userId: user.id,
        creditsCharged: monthlyCredits,
        status: 'success',
        transactionId: transaction.id,
      });

      // Update next billing date to 30 days from now
      const nextBillingDate = new Date();
      nextBillingDate.setDate(nextBillingDate.getDate() + 30);

      await tx.update(phoneNumbers)
        .set({ nextBillingDate })
        .where(eq(phoneNumbers.id, phoneNumber.id));
    });

    console.log(`✅ [Phone Billing] Successfully renewed ${phoneNumber.phoneNumber}`);

    // Send success notification
    await NotificationService.notifyPhoneBillingSuccess(
      user.id,
      phoneNumber.phoneNumber,
      monthlyCredits
    );

    // Check if user should be notified about low credits
    const updatedUser = await storage.getUser(user.id);
    if (updatedUser && await NotificationService.shouldNotifyLowCredits(updatedUser.credits || 0)) {
      await NotificationService.notifyLowCredits(user.id, updatedUser.credits || 0);

      // Send low credits email notification
      try {
        await emailService.sendLowCreditsAlert(user.id, updatedUser.credits || 0);
        console.log(`✅ [Phone Billing] Low credits email sent to user ${user.id}`);
      } catch (emailError: any) {
        console.error(`❌ [Phone Billing] Failed to send low credits email:`, emailError);
      }
    }
  } catch (error: any) {
    console.error(`❌ [Phone Billing] Failed to renew ${phoneNumber.phoneNumber}:`, error);

    // Create failed rental record
    try {
      await storage.createPhoneNumberRental({
        phoneNumberId: phoneNumber.id,
        userId: user.id,
        creditsCharged: monthlyCredits,
        status: 'failed',
      });
    } catch (rentalError) {
      console.error(`❌ [Phone Billing] Failed to create failed rental record:`, rentalError);
    }
  }
}

/**
 * Disable phone number due to insufficient credits
 * - Release from Twilio immediately
 * - Pause all campaigns using this number
 * - Create failed rental record
 */
async function disablePhoneNumber(phoneNumber: any, user: any, monthlyCredits: number) {
  console.log(`⚠️  [Phone Billing] Disabling ${phoneNumber.phoneNumber} (insufficient credits)`);

  try {
    await db.transaction(async (tx) => {
      // Create failed rental record
      await tx.insert(phoneNumberRentals).values({
        phoneNumberId: phoneNumber.id,
        userId: user.id,
        creditsCharged: monthlyCredits,
        status: 'insufficient_credits',
      });

      // Update phone number status to inactive
      await tx.update(phoneNumbers)
        .set({ 
          status: 'inactive',
          nextBillingDate: null, // Clear billing date since it's inactive
        })
        .where(eq(phoneNumbers.id, phoneNumber.id));

      // Pause all campaigns using this phone number
      await tx.execute(sql`
        UPDATE campaigns 
        SET status = 'paused'
        WHERE phone_number_id = ${phoneNumber.id} AND status = 'active'
      `);
    });

    // Release phone number from Twilio (outside transaction)
    try {
      await twilioService.releasePhoneNumber(phoneNumber.twilioSid);
      console.log(`✅ [Phone Billing] Released ${phoneNumber.phoneNumber} from Twilio`);
    } catch (twilioError: any) {
      console.error(`⚠️  [Phone Billing] Failed to release ${phoneNumber.phoneNumber} from Twilio:`, twilioError);
      // Continue even if Twilio release fails - number is disabled in our system
    }

    console.log(`✅ [Phone Billing] Disabled ${phoneNumber.phoneNumber} and paused campaigns`);

    // Send notification about phone number being released
    await NotificationService.notifyPhoneBillingFailed(
      user.id,
      phoneNumber.phoneNumber,
      `Insufficient credits (${user.credits || 0} available, ${monthlyCredits} required)`
    );
  } catch (error: any) {
    console.error(`❌ [Phone Billing] Failed to disable ${phoneNumber.phoneNumber}:`, error);
  }
}

let billingIntervalId: NodeJS.Timeout | null = null;

/**
 * Start the phone billing cron job
 */
export function startPhoneBillingCron() {
  if (billingIntervalId) {
    console.log('📞 [Phone Billing] Cron job already running');
    return;
  }

  console.log('📞 [Phone Billing] Starting cron job (checking every hour)');

  // Run immediately on startup
  processPhoneNumberBilling();

  // Then run every hour
  billingIntervalId = setInterval(processPhoneNumberBilling, BILLING_CHECK_INTERVAL);
}

/**
 * Stop the phone billing cron job
 */
export function stopPhoneBillingCron() {
  if (billingIntervalId) {
    clearInterval(billingIntervalId);
    billingIntervalId = null;
    console.log('📞 [Phone Billing] Cron job stopped');
  }
}

