/**
 * Pipeline Orchestrator Service
 * 
 * Manages automated ML pipeline workflows for the Knowledge Intelligence System.
 * Features:
 * - Scheduled pipeline execution
 * - Event-triggered processing
 * - Pipeline state management
 * - Progress tracking and notifications
 * - Content refresh detection
 */

import { db } from "../db";
import { 
  knowledgePipelineJobs,
  crawlJobs,
  crawlPages,
  knowledgeBase,
  contentAuditLog
} from "@shared/schema";
import { eq, and, sql, desc, lte, gte, isNull } from "drizzle-orm";
import { createCrawler } from "./knowledge-crawler";
import { createContentProcessor } from "./content-processor";
import { createKnowledgeAIAnalyzer } from "./knowledge-ai-analyzer";
import { createTopicIntelligence } from "./topic-intelligence";
import { createMLContentAnalyzer } from "./ml-content-analyzer";

export interface PipelineConfig {
  name: string;
  crawlJobId?: string;
  startUrl?: string;
  crawlType?: 'single' | 'sitemap' | 'recursive' | 'comprehensive';
  maxPages?: number;
  maxDepth?: number;
  respectRobotsTxt?: boolean;
  includePaths?: string[];
  excludePaths?: string[];
  folderId?: string;
  maxArticles?: number;
  scheduleEnabled?: boolean;
  scheduleInterval?: 'daily' | 'weekly' | 'monthly';
  scheduledAt?: Date;
}

export interface PipelineProgress {
  stage: string;
  stageProgress: number;
  overallProgress: number;
  estimatedTimeRemaining: number | null;
  stageDetails: {
    crawling: {
      pagesDiscovered: number;
      pagesCrawled: number;
      startedAt?: string;
      completedAt?: string;
    };
    analyzing: {
      itemsTotal: number;
      itemsProcessed: number;
      entitiesFound: number;
      topicsFound: number;
      faqsFound: number;
      startedAt?: string;
      completedAt?: string;
    };
    generating: {
      articlesPlanned: number;
      articlesGenerated: number;
      startedAt?: string;
      completedAt?: string;
    };
    websiteNature?: {
      industry: string;
      productCategory: string;
      features: number;
      personas: number;
    };
    topicMining?: {
      topicsDiscovered: number;
      topicsExpanded: number;
      topicsSelected: number;
      clusters: number;
    };
    contentQuality?: {
      averageScore: number;
      duplicatesFound: number;
      clustersDetected: number;
    };
  };
}

export interface ScheduledPipeline {
  id: string;
  name: string;
  config: PipelineConfig;
  nextRun: Date;
  lastRun?: Date;
  status: 'active' | 'paused' | 'error';
  runCount: number;
}

/**
 * Pipeline Orchestrator class
 */
export class PipelineOrchestrator {
  private userId: string;
  private activeJobs: Map<string, { cancel: () => void }> = new Map();

  constructor(userId: string) {
    this.userId = userId;
  }

  /**
   * Create and start a new pipeline
   */
  async createPipeline(config: PipelineConfig): Promise<string> {
    let crawlJobId = config.crawlJobId;

    if (!crawlJobId && config.startUrl) {
      const [crawlJob] = await db.insert(crawlJobs).values({
        userId: this.userId,
        name: `${config.name} - Crawl`,
        startUrl: config.startUrl,
        crawlType: config.crawlType || 'comprehensive',
        maxPages: config.maxPages || 50,
        maxDepth: config.maxDepth || 3,
        respectRobotsTxt: config.respectRobotsTxt ?? true,
        includePaths: config.includePaths,
        excludePaths: config.excludePaths,
        folderId: config.folderId
      }).returning();

      crawlJobId = crawlJob.id;
    }

    if (!crawlJobId) {
      throw new Error("Either crawlJobId or startUrl must be provided");
    }

    const [pipelineJob] = await db.insert(knowledgePipelineJobs).values({
      userId: this.userId,
      crawlJobId,
      name: config.name,
      status: "pending",
      currentStage: "pending",
      stageProgress: 0,
      overallProgress: 0
    }).returning();

    await db.insert(contentAuditLog).values({
      userId: this.userId,
      actionType: 'create',
      resourceType: 'pipeline_job',
      resourceId: pipelineJob.id,
      details: { config }
    });

    return pipelineJob.id;
  }

  /**
   * Start a pipeline execution
   */
  async startPipeline(pipelineJobId: string): Promise<void> {
    const [pipelineJob] = await db.select().from(knowledgePipelineJobs)
      .where(eq(knowledgePipelineJobs.id, pipelineJobId));

    if (!pipelineJob) {
      throw new Error("Pipeline job not found");
    }

    if (pipelineJob.status === "running" || pipelineJob.status === "crawling" || 
        pipelineJob.status === "analyzing" || pipelineJob.status === "generating") {
      throw new Error("Pipeline is already running");
    }

    this.runPipelineAsync(pipelineJobId).catch(err => {
      console.error(`Pipeline ${pipelineJobId} failed:`, err);
    });
  }

  /**
   * Run pipeline asynchronously
   */
  private async runPipelineAsync(pipelineJobId: string): Promise<void> {
    let cancelled = false;
    this.activeJobs.set(pipelineJobId, {
      cancel: () => { cancelled = true; }
    });

    const updateProgress = async (progress: Partial<PipelineProgress>) => {
      if (cancelled) return;

      await db.update(knowledgePipelineJobs)
        .set({
          currentStage: progress.stage,
          stageProgress: progress.stageProgress,
          overallProgress: progress.overallProgress,
          estimatedTimeRemaining: progress.estimatedTimeRemaining,
          stageDetails: progress.stageDetails as any,
          updatedAt: new Date()
        })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));
    };

    try {
      const [pipelineJob] = await db.select().from(knowledgePipelineJobs)
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));

      if (!pipelineJob?.crawlJobId) {
        throw new Error("Pipeline job not found or missing crawl job");
      }

      const stageDetails: PipelineProgress['stageDetails'] = {
        crawling: { pagesDiscovered: 0, pagesCrawled: 0 },
        analyzing: { itemsTotal: 0, itemsProcessed: 0, entitiesFound: 0, topicsFound: 0, faqsFound: 0 },
        generating: { articlesPlanned: 0, articlesGenerated: 0 }
      };

      await db.update(knowledgePipelineJobs)
        .set({ status: "crawling", startedAt: new Date(), updatedAt: new Date() })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));

      stageDetails.crawling.startedAt = new Date().toISOString();
      await updateProgress({
        stage: "crawling",
        stageProgress: 0,
        overallProgress: 5,
        estimatedTimeRemaining: 120,
        stageDetails
      });

      const crawler = createCrawler(this.userId);
      await crawler.startCrawl(pipelineJob.crawlJobId);

      let crawlComplete = false;
      const crawlStartTime = Date.now();

      while (!crawlComplete && !cancelled) {
        await new Promise(resolve => setTimeout(resolve, 2000));

        const [crawlJob] = await db.select().from(crawlJobs)
          .where(eq(crawlJobs.id, pipelineJob.crawlJobId));

        if (!crawlJob) break;

        stageDetails.crawling.pagesDiscovered = crawlJob.pagesDiscovered;
        stageDetails.crawling.pagesCrawled = crawlJob.pagesCrawled;

        const progress = crawlJob.maxPages > 0
          ? Math.min(95, Math.round((crawlJob.pagesCrawled / crawlJob.maxPages) * 100))
          : 50;

        const elapsed = (Date.now() - crawlStartTime) / 1000;
        const remaining = Math.max(0, Math.round((elapsed / Math.max(progress, 1)) * (100 - progress)));

        await updateProgress({
          stage: "crawling",
          stageProgress: progress,
          overallProgress: Math.round(progress * 0.33),
          estimatedTimeRemaining: remaining + 60,
          stageDetails
        });

        if (crawlJob.status === "completed" || crawlJob.status === "failed") {
          crawlComplete = true;
          stageDetails.crawling.completedAt = new Date().toISOString();
        }
      }

      if (cancelled) return;

      const processor = createContentProcessor(this.userId);
      await processor.processJobPages(pipelineJob.crawlJobId);

      const mlAnalyzer = createMLContentAnalyzer(this.userId);
      const clusterResult = await mlAnalyzer.detectContentClusters();
      stageDetails.contentQuality = {
        averageScore: 0,
        duplicatesFound: 0,
        clustersDetected: clusterResult.clusters.length
      };

      await updateProgress({
        stage: "crawling",
        stageProgress: 100,
        overallProgress: 33,
        estimatedTimeRemaining: 60,
        stageDetails
      });

      if (cancelled) return;

      await db.update(knowledgePipelineJobs)
        .set({ status: "analyzing", updatedAt: new Date() })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));

      stageDetails.analyzing.startedAt = new Date().toISOString();
      await updateProgress({
        stage: "analyzing",
        stageProgress: 0,
        overallProgress: 35,
        estimatedTimeRemaining: 90,
        stageDetails
      });

      const knowledgeItems = await db.select().from(knowledgeBase)
        .where(eq(knowledgeBase.userId, this.userId))
        .limit(20);

      stageDetails.analyzing.itemsTotal = knowledgeItems.length;

      const analyzer = createKnowledgeAIAnalyzer(this.userId);
      let analyzed = 0;
      let totalQuality = 0;

      for (const item of knowledgeItems) {
        if (cancelled) return;

        try {
          const result = await analyzer.analyzeKnowledgeBaseItem(item.id);
          analyzed++;

          if (item.content) {
            const contentAnalysis = mlAnalyzer.analyzeContent(item.content);
            totalQuality += contentAnalysis.quality.overall;
          }

          stageDetails.analyzing.itemsProcessed = analyzed;
          stageDetails.analyzing.entitiesFound += result?.entities || 0;
          stageDetails.analyzing.topicsFound += result?.topics || 0;
          stageDetails.analyzing.faqsFound += result?.faqs || 0;

          if (stageDetails.contentQuality) {
            stageDetails.contentQuality.averageScore = Math.round(totalQuality / analyzed);
          }

          const progress = Math.round((analyzed / knowledgeItems.length) * 100);
          const remaining = Math.max(0, Math.round((knowledgeItems.length - analyzed) * 3));

          await updateProgress({
            stage: "analyzing",
            stageProgress: progress,
            overallProgress: 33 + Math.round(progress * 0.33),
            estimatedTimeRemaining: remaining + 30,
            stageDetails
          });
        } catch (error) {
          console.error(`Failed to analyze item ${item.id}:`, error);
        }
      }

      stageDetails.analyzing.completedAt = new Date().toISOString();
      await updateProgress({
        stage: "analyzing",
        stageProgress: 100,
        overallProgress: 66,
        estimatedTimeRemaining: 30,
        stageDetails
      });

      if (cancelled) return;

      await db.update(knowledgePipelineJobs)
        .set({ status: "generating", updatedAt: new Date() })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));

      stageDetails.generating.startedAt = new Date().toISOString();
      await updateProgress({
        stage: "generating",
        stageProgress: 0,
        overallProgress: 68,
        estimatedTimeRemaining: 120,
        stageDetails
      });

      const topicIntelligence = createTopicIntelligence(this.userId);

      try {
        const autoGenResult = await topicIntelligence.runAutoGeneration(
          pipelineJobId,
          pipelineJob.crawlJobId,
          pipelineJob.maxArticles || 15
        );

        stageDetails.websiteNature = {
          industry: autoGenResult.websiteNature.industryDomain,
          productCategory: autoGenResult.websiteNature.productCategory,
          features: autoGenResult.websiteNature.productFeatures?.length || 0,
          personas: autoGenResult.websiteNature.customerPersonas?.length || 0
        };

        stageDetails.topicMining = {
          topicsDiscovered: autoGenResult.topicsDiscovered,
          topicsExpanded: autoGenResult.topicsExpanded,
          topicsSelected: autoGenResult.topicsSelected,
          clusters: autoGenResult.clusters?.length || 0
        };

        stageDetails.generating.articlesPlanned = autoGenResult.topicsSelected;
        stageDetails.generating.articlesGenerated = autoGenResult.articlesGenerated;
        stageDetails.generating.completedAt = new Date().toISOString();
      } catch (error) {
        console.error("Topic intelligence failed:", error);
        stageDetails.generating.completedAt = new Date().toISOString();
      }

      await db.update(knowledgePipelineJobs)
        .set({
          status: "completed",
          currentStage: "completed",
          stageProgress: 100,
          overallProgress: 100,
          stageDetails: stageDetails as any,
          completedAt: new Date(),
          updatedAt: new Date()
        })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));

      await db.insert(contentAuditLog).values({
        userId: this.userId,
        actionType: 'complete',
        resourceType: 'pipeline_job',
        resourceId: pipelineJobId,
        details: { stageDetails }
      });

    } catch (error) {
      console.error(`Pipeline ${pipelineJobId} failed:`, error);

      await db.update(knowledgePipelineJobs)
        .set({
          status: "failed",
          errorMessage: error instanceof Error ? error.message : "Unknown error",
          updatedAt: new Date()
        })
        .where(eq(knowledgePipelineJobs.id, pipelineJobId));
    } finally {
      this.activeJobs.delete(pipelineJobId);
    }
  }

  /**
   * Cancel a running pipeline
   */
  async cancelPipeline(pipelineJobId: string): Promise<void> {
    const activeJob = this.activeJobs.get(pipelineJobId);
    if (activeJob) {
      activeJob.cancel();
    }

    await db.update(knowledgePipelineJobs)
      .set({
        status: "failed",
        errorMessage: "Cancelled by user",
        updatedAt: new Date()
      })
      .where(eq(knowledgePipelineJobs.id, pipelineJobId));
  }

  /**
   * Get active pipeline job
   */
  async getActivePipeline(): Promise<any | null> {
    const [job] = await db.select()
      .from(knowledgePipelineJobs)
      .where(and(
        eq(knowledgePipelineJobs.userId, this.userId),
        sql`${knowledgePipelineJobs.status} IN ('pending', 'crawling', 'analyzing', 'generating')`
      ))
      .orderBy(desc(knowledgePipelineJobs.createdAt))
      .limit(1);

    return job || null;
  }

  /**
   * Get pipeline history
   */
  async getPipelineHistory(limit: number = 20): Promise<any[]> {
    const jobs = await db.select()
      .from(knowledgePipelineJobs)
      .where(eq(knowledgePipelineJobs.userId, this.userId))
      .orderBy(desc(knowledgePipelineJobs.createdAt))
      .limit(limit);

    return jobs;
  }

  /**
   * Check for content that needs refresh
   */
  async getStaleContent(daysThreshold: number = 30): Promise<{
    id: string;
    title: string;
    url?: string;
    lastUpdated: Date;
    staleDays: number;
  }[]> {
    const thresholdDate = new Date();
    thresholdDate.setDate(thresholdDate.getDate() - daysThreshold);

    const staleItems = await db.select({
      id: knowledgeBase.id,
      title: knowledgeBase.title,
      url: knowledgeBase.url,
      createdAt: knowledgeBase.createdAt
    })
      .from(knowledgeBase)
      .where(and(
        eq(knowledgeBase.userId, this.userId),
        eq(knowledgeBase.type, 'url'),
        lte(knowledgeBase.createdAt, thresholdDate)
      ))
      .orderBy(knowledgeBase.createdAt)
      .limit(50);

    return staleItems.map(item => ({
      id: item.id,
      title: item.title,
      url: item.url || undefined,
      lastUpdated: item.createdAt,
      staleDays: Math.floor((Date.now() - item.createdAt.getTime()) / (1000 * 60 * 60 * 24))
    }));
  }

  /**
   * Get pipeline analytics
   */
  async getPipelineAnalytics(): Promise<{
    totalPipelines: number;
    completedPipelines: number;
    failedPipelines: number;
    averageDuration: number;
    totalArticlesGenerated: number;
    totalPagesProcessed: number;
  }> {
    const jobs = await db.select()
      .from(knowledgePipelineJobs)
      .where(eq(knowledgePipelineJobs.userId, this.userId));

    const completed = jobs.filter(j => j.status === 'completed');
    const failed = jobs.filter(j => j.status === 'failed');

    let totalDuration = 0;
    let totalArticles = 0;
    let totalPages = 0;

    for (const job of completed) {
      if (job.startedAt && job.completedAt) {
        totalDuration += job.completedAt.getTime() - job.startedAt.getTime();
      }

      const details = job.stageDetails as any;
      if (details?.generating?.articlesGenerated) {
        totalArticles += details.generating.articlesGenerated;
      }
      if (details?.crawling?.pagesCrawled) {
        totalPages += details.crawling.pagesCrawled;
      }
    }

    return {
      totalPipelines: jobs.length,
      completedPipelines: completed.length,
      failedPipelines: failed.length,
      averageDuration: completed.length > 0 ? Math.round(totalDuration / completed.length / 1000) : 0,
      totalArticlesGenerated: totalArticles,
      totalPagesProcessed: totalPages
    };
  }
}

export const createPipelineOrchestrator = (userId: string) => new PipelineOrchestrator(userId);

server/services/qa-analysis.service.ts.content:
'use strict';

import OpenAI from 'openai';
import { db } from '../db';
import { calls, callQaAnalyses, agents } from '@shared/schema';
import { eq, and, desc, sql, gte, lte, count } from 'drizzle-orm';
import { logger } from '../utils/logger';
import type { InsertCallQaAnalysis, CallQaAnalysis } from '@shared/schema';

export interface QaAnalysisResult {
  overallScore: number;
  audioQualityScore: number;
  languageScore: number;
  complianceScore: number;
  performanceScore: number;
  resolutionStatus: 'resolved' | 'unresolved' | 'partial' | 'transferred';
  resolutionNotes: string;
  avgResponseLatency: number;
  maxResponseLatency: number;
  hasHallucinations: boolean;
  hasInterruptions: boolean;
  hasNegativeSentiment: boolean;
  hasComplianceIssues: boolean;
  hasKbInaccuracies: boolean;
  diagnostics: {
    hallucinations: Array<{ text: string; context: string }>;
    interruptions: Array<{ timestamp: number; description: string }>;
    sentimentBreakdown: { positive: number; neutral: number; negative: number };
    complianceIssues: Array<{ issue: string; severity: string }>;
  };
  keyMoments: Array<{ timestamp: number; type: string; description: string }>;
  evidence: Array<{ transcriptIndex: number; issue: string; severity: string }>;
}

const QA_SYSTEM_PROMPT = `You are an AI Quality Assurance analyst for voice calls. Analyze the call transcript and provide a comprehensive quality assessment.

Respond ONLY with valid JSON in this exact format:
{
  "overallScore": <0-100>,
  "audioQualityScore": <0-100>,
  "languageScore": <0-100>,
  "complianceScore": <0-100>,
  "performanceScore": <0-100>,
  "resolutionStatus": "resolved" | "unresolved" | "partial" | "transferred",
  "resolutionNotes": "<brief explanation of resolution status>",
  "avgResponseLatency": <estimated avg response time in ms, 0 if unknown>,
  "maxResponseLatency": <estimated max response time in ms, 0 if unknown>,
  "hasHallucinations": <boolean - did AI make up false information?>,
  "hasInterruptions": <boolean - were there frequent interruptions?>,
  "hasNegativeSentiment": <boolean - was customer sentiment negative?>,
  "hasComplianceIssues": <boolean - any compliance/script violations?>,
  "hasKbInaccuracies": <boolean - knowledge base accuracy issues?>,
  "diagnostics": {
    "hallucinations": [{"text": "<false statement>", "context": "<surrounding context>"}],
    "interruptions": [{"timestamp": 0, "description": "<description>"}],
    "sentimentBreakdown": {"positive": <0-100>, "neutral": <0-100>, "negative": <0-100>},
    "complianceIssues": [{"issue": "<issue description>", "severity": "low|medium|high"}]
  },
  "keyMoments": [{"timestamp": 0, "type": "positive|negative|neutral", "description": "<key moment>"}],
  "evidence": [{"transcriptIndex": 0, "issue": "<issue found>", "severity": "low|medium|high"}]
}

Scoring Guidelines:
- 90-100: Excellent - exceeds expectations
- 70-89: Good - meets expectations
- 50-69: Needs improvement
- 0-49: Poor - requires immediate attention

Focus on:
1. Audio Quality: Speech clarity, background noise, volume levels
2. Language: Grammar, vocabulary, professionalism, courtesy
3. Compliance: Script adherence, required disclosures, proper greetings/closings
4. Performance: Goal achievement, call efficiency, problem resolution`;

export class QaAnalysisService {
  private static openai: OpenAI | null = null;

  private static getOpenAIClient(apiKey?: string): OpenAI {
    if (apiKey) {
      return new OpenAI({ apiKey });
    }
    if (!this.openai) {
      const envApiKey = process.env.OPENAI_API_KEY;
      if (!envApiKey) {
        throw new Error('OPENAI_API_KEY environment variable is not set');
      }
      this.openai = new OpenAI({ apiKey: envApiKey });
    }
    return this.openai;
  }

  static async analyzeCall(
    callId: string,
    userId: string,
    apiKey?: string
  ): Promise<CallQaAnalysis | null> {
    const source = 'QaAnalysisService';

    const [call] = await db
      .select()
      .from(calls)
      .where(eq(calls.id, callId))
      .limit(1);

    if (!call) {
      logger.warn(`Call not found: ${callId}`, {}, source);
      return null;
    }

    if (!call.transcript || call.transcript.trim().length === 0) {
      logger.warn(`No transcript available for call: ${callId}`, {}, source);
      return null;
    }

    try {
      const openai = this.getOpenAIClient(apiKey);

      const userMessage = `Analyze this call transcript:

Call ID: ${callId}
Duration: ${call.duration || 'Unknown'} seconds
Direction: ${call.callDirection}
Status: ${call.status}

Transcript:
${call.transcript}

${call.aiSummary ? `AI Summary: ${call.aiSummary}` : ''}
${call.sentiment ? `Current Sentiment: ${call.sentiment}` : ''}`;

      logger.info(`Analyzing QA for call ${callId}`, {
        transcriptLength: call.transcript.length,
        duration: call.duration
      }, source);

      const response = await openai.chat.completions.create({
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: QA_SYSTEM_PROMPT },
          { role: 'user', content: userMessage }
        ],
        response_format: { type: 'json_object' },
        max_tokens: 2000,
        temperature: 0.3
      });

      const content = response.choices[0]?.message?.content;
      if (!content) {
        logger.error(`Empty response from OpenAI for call ${callId}`, {}, source);
        return null;
      }

      const analysis: QaAnalysisResult = JSON.parse(content);

      const qaData: InsertCallQaAnalysis = {
        callId,
        userId,
        overallScore: analysis.overallScore,
        audioQualityScore: analysis.audioQualityScore,
        languageScore: analysis.languageScore,
        complianceScore: analysis.complianceScore,
        performanceScore: analysis.performanceScore,
        resolutionStatus: analysis.resolutionStatus,
        resolutionNotes: analysis.resolutionNotes,
        avgResponseLatency: analysis.avgResponseLatency,
        maxResponseLatency: analysis.maxResponseLatency,
        hasHallucinations: analysis.hasHallucinations,
        hasInterruptions: analysis.hasInterruptions,
        hasNegativeSentiment: analysis.hasNegativeSentiment,
        hasComplianceIssues: analysis.hasComplianceIssues,
        hasKbInaccuracies: analysis.hasKbInaccuracies,
        diagnostics: analysis.diagnostics,
        keyMoments: analysis.keyMoments,
        evidence: analysis.evidence,
        analysisModel: 'gpt-4o-mini',
        analysisVersion: '1.0',
        analyzedAt: new Date()
      };

      const [savedAnalysis] = await db
        .insert(callQaAnalyses)
        .values(qaData)
        .returning();

      logger.info(`QA analysis saved for call ${callId}`, {
        overallScore: analysis.overallScore,
        resolutionStatus: analysis.resolutionStatus
      }, source);

      return savedAnalysis;
    } catch (error: any) {
      logger.error(`QA analysis failed for call ${callId}`, {
        error: error.message
      }, source);
      return null;
    }
  }

  static async getAnalysis(callId: string): Promise<CallQaAnalysis | null> {
    const [analysis] = await db
      .select()
      .from(callQaAnalyses)
      .where(eq(callQaAnalyses.callId, callId))
      .limit(1);

    return analysis || null;
  }

  static async getDashboardStats(userId: string, startDate?: Date, endDate?: Date) {
    const conditions = [eq(callQaAnalyses.userId, userId)];

    if (startDate) {
      conditions.push(gte(callQaAnalyses.analyzedAt, startDate));
    }
    if (endDate) {
      conditions.push(lte(callQaAnalyses.analyzedAt, endDate));
    }

    const analyses = await db
      .select()
      .from(callQaAnalyses)
      .where(and(...conditions))
      .orderBy(desc(callQaAnalyses.analyzedAt));

    if (analyses.length === 0) {
      return {
        totalAnalyzed: 0,
        averageScore: 0,
        resolutionRate: 0,
        issueBreakdown: {
          hallucinations: 0,
          interruptions: 0,
          negativeSentiment: 0,
          complianceIssues: 0,
          kbInaccuracies: 0
        },
        scoreTrend: [],
        recentAnalyses: []
      };
    }

    const totalAnalyzed = analyses.length;
    const averageScore = Math.round(
      analyses.reduce((sum, a) => sum + (a.overallScore || 0), 0) / totalAnalyzed
    );
    const resolvedCount = analyses.filter(
      a => a.resolutionStatus === 'resolved'
    ).length;
    const resolutionRate = Math.round((resolvedCount / totalAnalyzed) * 100);

    const issueBreakdown = {
      hallucinations: analyses.filter(a => a.hasHallucinations).length,
      interruptions: analyses.filter(a => a.hasInterruptions).length,
      negativeSentiment: analyses.filter(a => a.hasNegativeSentiment).length,
      complianceIssues: analyses.filter(a => a.hasComplianceIssues).length,
      kbInaccuracies: analyses.filter(a => a.hasKbInaccuracies).length
    };

    const scoreTrend = analyses.slice(0, 30).map(a => ({
      date: a.analyzedAt,
      score: a.overallScore
    })).reverse();

    return {
      totalAnalyzed,
      averageScore,
      resolutionRate,
      issueBreakdown,
      scoreTrend,
      recentAnalyses: analyses.slice(0, 10)
    };
  }

  static async getCallsForAnalysis(userId: string, limit = 50) {
    const analyzedCallIds = await db
      .select({ callId: callQaAnalyses.callId })
      .from(callQaAnalyses)
      .where(eq(callQaAnalyses.userId, userId));

    const analyzedIds = new Set(analyzedCallIds.map(a => a.callId));

    const callsToAnalyze = await db
      .select({
        id: calls.id,
        phoneNumber: calls.phoneNumber,
        status: calls.status,
        duration: calls.duration,
        createdAt: calls.createdAt,
        transcript: calls.transcript
      })
      .from(calls)
      .where(
        and(
          eq(calls.userId, userId),
          eq(calls.status, 'completed'),
          sql`${calls.transcript} IS NOT NULL AND ${calls.transcript} != ''`
        )
      )
      .orderBy(desc(calls.createdAt))
      .limit(limit * 2);

    return callsToAnalyze
      .filter(call => !analyzedIds.has(call.id))
      .slice(0, limit);
  }

  static async getUserAnalyses(
    userId: string,
    page = 1,
    pageSize = 20
  ): Promise<{ analyses: CallQaAnalysis[]; total: number }> {
    const offset = (page - 1) * pageSize;

    const [countResult] = await db
      .select({ count: count() })
      .from(callQaAnalyses)
      .where(eq(callQaAnalyses.userId, userId));

    const analyses = await db
      .select()
      .from(callQaAnalyses)
      .where(eq(callQaAnalyses.userId, userId))
      .orderBy(desc(callQaAnalyses.analyzedAt))
      .offset(offset)
      .limit(pageSize);

    return {
      analyses,
      total: countResult?.count || 0
    };
  }
}

server/plugins/team-management-adapter.t.content:
/**
 * Team Management Plugin Adapter
 * 
 * Provides optional dynamic loading of the Team Management plugin.
 * Returns no-op stubs when the plugin is not installed, allowing
 * the core application to function without the plugin.
 * 
 * Uses async dynamic import() for ES module compatibility.
 * Supports both .ts (development) and .js (production) files.
 */

import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import type { Request, Response, NextFunction } from 'express';

// Handle both ESM (development) and CJS (production bundle) contexts
const getDirname = () => {
  try {
    if (typeof import.meta?.url === 'string') {
      return path.dirname(fileURLToPath(import.meta.url));
    }
  } catch {}
  return __dirname ?? process.cwd();
};

const currentDir = getDirname();
const PLUGIN_DIR = path.resolve(currentDir, '..', '..', 'plugins', 'team-management');

export interface TeamMemberContext {
  memberId: string;
  teamId: string;
  userId: string | number;
  roleId: string;
  roleName?: string;
  permissions: any;
  isAdminTeam?: boolean;
}

export interface AdminTeamMemberContext extends TeamMemberContext {
  isAdminTeam: boolean;
  adminId: string;
}

let pluginAvailable: boolean | null = null;
let cachedServices: {
  TeamAuthService?: any;
  AdminTeamService?: any;
  TeamService?: any;
  applyTeamContext?: any;
} = {};
let loadAttempted = false;

function isPluginInstalled(): boolean {
  if (pluginAvailable === null) {
    try {
      pluginAvailable = fs.existsSync(PLUGIN_DIR) && 
                        fs.existsSync(path.join(PLUGIN_DIR, 'services'));
    } catch {
      pluginAvailable = false;
    }
  }
  return pluginAvailable;
}

function resolveModulePath(basePath: string): string | null {
  const extensions = ['.ts', '.js', '.mjs'];

  for (const ext of extensions) {
    const fullPath = basePath + ext;
    if (fs.existsSync(fullPath)) {
      return fullPath;
    }
  }

  if (fs.existsSync(basePath)) {
    return basePath;
  }

  return null;
}

async function dynamicImport(basePath: string): Promise<any> {
  const resolvedPath = resolveModulePath(basePath);

  if (!resolvedPath) {
    throw new Error(`Module not found: ${basePath}`);
  }

  const fileUrl = pathToFileURL(resolvedPath).href;
  return import(fileUrl);
}

async function loadServices(): Promise<boolean> {
  if (!isPluginInstalled()) {
    return false;
  }

  try {
    const teamAuthBase = path.join(PLUGIN_DIR, 'services', 'team-auth.service');
    const adminTeamBase = path.join(PLUGIN_DIR, 'services', 'admin-team.service');
    const teamBase = path.join(PLUGIN_DIR, 'services', 'team.service');

    const results = await Promise.allSettled([
      dynamicImport(teamAuthBase),
      dynamicImport(adminTeamBase),
      dynamicImport(teamBase),
    ]);

    if (results[0].status === 'fulfilled') {
      cachedServices.TeamAuthService = results[0].value.TeamAuthService;
    }
    if (results[1].status === 'fulfilled') {
      cachedServices.AdminTeamService = results[1].value.AdminTeamService;
    }
    if (results[2].status === 'fulfilled') {
      cachedServices.TeamService = results[2].value.TeamService;
    }

    const anyLoaded = results.some(r => r.status === 'fulfilled');
    if (anyLoaded) {
      console.log('[TeamManagementAdapter] Services loaded successfully');
    }

    return anyLoaded;
  } catch (error) {
    console.warn('[TeamManagementAdapter] Failed to load services:', error);
    return false;
  }
}

async function loadMiddleware(): Promise<boolean> {
  if (!isPluginInstalled()) {
    return false;
  }

  try {
    const middlewareBase = path.join(PLUGIN_DIR, 'middleware', 'team-auth.middleware');
    const module = await dynamicImport(middlewareBase);
    cachedServices.applyTeamContext = module.applyTeamContext;
    console.log('[TeamManagementAdapter] Middleware loaded successfully');
    return true;
  } catch (error) {
    console.warn('[TeamManagementAdapter] Failed to load middleware:', error);
    return false;
  }
}

export async function initializeAdapter(): Promise<void> {
  if (loadAttempted && Object.keys(cachedServices).length > 0) {
    return;
  }

  loadAttempted = true;
  await Promise.all([loadServices(), loadMiddleware()]);
}

export function getTeamAuthService(): any | null {
  return cachedServices.TeamAuthService || null;
}

export function getAdminTeamService(): any | null {
  return cachedServices.AdminTeamService || null;
}

export function getTeamService(): any | null {
  return cachedServices.TeamService || null;
}

export function getApplyTeamContext(): any | null {
  return cachedServices.applyTeamContext || null;
}

export function getTeamContextMiddleware(): (req: Request, res: Response, next: NextFunction) => void {
  const applyTeamContext = getApplyTeamContext();

  if (applyTeamContext) {
    return applyTeamContext() as unknown as (req: Request, res: Response, next: NextFunction) => void;
  }

  return (_req: Request, _res: Response, next: NextFunction) => {
    next();
  };
}

export async function validateUserTeamSession(token: string): Promise<TeamMemberContext | null> {
  if (!cachedServices.TeamAuthService && !loadAttempted) {
    await loadServices();
  }

  const TeamAuthService = getTeamAuthService();

  if (!TeamAuthService) {
    return null;
  }

  try {
    return await TeamAuthService.validateSession(token);
  } catch (error) {
    console.error('[TeamManagementAdapter] User team session validation error:', error);
    return null;
  }
}

export async function validateAdminTeamSession(token: string): Promise<AdminTeamMemberContext | null> {
  if (!cachedServices.AdminTeamService && !loadAttempted) {
    await loadServices();
  }

  const AdminTeamService = getAdminTeamService();

  if (!AdminTeamService) {
    return null;
  }

  try {
    const session = await AdminTeamService.validateSession(token);

    if (!session) {
      return null;
    }

    return {
      memberId: session.memberId,
      teamId: session.teamId,
      userId: session.adminId,
      roleId: session.roleId,
      roleName: session.roleName,
      permissions: session.permissions,
      isAdminTeam: true,
      adminId: session.adminId,
    };
  } catch (error) {
    console.error('[TeamManagementAdapter] Admin team session validation error:', error);
    return null;
  }
}

export function isTeamManagementInstalled(): boolean {
  return isPluginInstalled();
}

export function clearCache(): void {
  pluginAvailable = null;
  cachedServices = {};
  loadAttempted = false;
}

