import { useEffect, useState, useRef } from "react";
import { motion, useInView } from "framer-motion";
import { UsersRound, PhoneCall, Crosshair, Timer, BadgeDollarSign } from "lucide-react";

interface StatItemProps {
  icon: typeof UsersRound;
  value: number;
  label: string;
  prefix?: string;
  suffix?: string;
  delay: number;
  testId: string;
  iconColor: string;
  shadowColor: string;
}

function AnimatedCounter({ 
  value, 
  prefix = "", 
  suffix = "",
  isInView 
}: { 
  value: number; 
  prefix?: string; 
  suffix?: string;
  isInView: boolean;
}) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!isInView) return;

    const duration = 2000;
    const steps = 60;
    const stepDuration = duration / steps;
    const increment = value / steps;

    let current = 0;
    const timer = setInterval(() => {
      current += increment;
      if (current >= value) {
        setCount(value);
        clearInterval(timer);
      } else {
        setCount(Math.floor(current));
      }
    }, stepDuration);

    return () => clearInterval(timer);
  }, [value, isInView]);

  const formatNumber = (num: number) => {
    if (num >= 1000000) {
      return Math.round(num / 1000000) + 'M';
    }
    if (num >= 1000) {
      return Math.round(num / 1000) + 'K';
    }
    return num.toLocaleString();
  };

  return (
    <span className="tabular-nums">
      {prefix}{formatNumber(count)}{suffix}
    </span>
  );
}

function StatItem({ icon: Icon, value, label, prefix, suffix, delay, testId, iconColor, shadowColor }: StatItemProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 30 }}
      animate={isInView ? { opacity: 1, y: 0 } : {}}
      transition={{ duration: 0.6, delay }}
      className="text-center group"
      data-testid={testId}
    >
      <motion.div 
        className={`relative inline-flex items-center justify-center w-14 h-14 mb-4 rounded-xl bg-gradient-to-br ${iconColor} shadow-lg ${shadowColor}`}
        initial={{ scale: 1, rotate: 0 }}
        whileInView={{ 
          scale: [1, 1.1, 1],
          rotate: [0, 5, -5, 0]
        }}
        viewport={{ once: true }}
        transition={{ 
          delay: delay + 0.1,
          duration: 0.6,
          ease: "easeOut"
        }}
        whileHover={{ 
          scale: 1.1,
          rotate: 5
        }}
      >
        <Icon className="h-7 w-7 text-white" />
      </motion.div>
      <div className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-bold text-foreground mb-2">
        <AnimatedCounter 
          value={value} 
          prefix={prefix} 
          suffix={suffix} 
          isInView={isInView} 
        />
      </div>
      <div className="text-muted-foreground font-medium">{label}</div>
    </motion.div>
  );
}

export function PlatformStatsSection() {
  const displayStats = {
