  });

  const purchaseMutation = useMutation({
    mutationFn: async ({ phoneNumber, friendlyName }: { phoneNumber: string; friendlyName?: string }) => {
      const res = await apiRequest("POST", "/api/admin/phone-numbers/buy-system", { phoneNumber, friendlyName });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/phone-numbers"] });
      resetAndClose();
      toast({ 
        title: t("admin.systemNumbers.purchaseSuccess"), 
        description: t("admin.systemNumbers.purchaseSuccessDesc") 
      });
    },
    onError: (error: any) => {
      toast({
        title: t("admin.systemNumbers.purchaseFailed"),
        description: error.message || t("common.tryAgain"),
        variant: "destructive",
      });
    },
  });

  const releaseMutation = useMutation({
    mutationFn: async (sid: string) => {
      const res = await apiRequest("DELETE", `/api/admin/phone-numbers/release/${sid}`);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/phone-numbers"] });
      refetchTwilio();
      toast({ 
        title: t("admin.systemNumbers.releaseSuccess"), 
        description: t("admin.systemNumbers.releaseSuccessDesc") 
      });
    },
    onError: (error: any) => {
      toast({
        title: t("admin.systemNumbers.releaseFailed"),
        description: error.message || t("common.tryAgain"),
        variant: "destructive",
      });
    },
  });

  const handleImport = () => {
    if (!selectedImportNumber) return;
    importMutation.mutate({
      phoneNumber: selectedImportNumber.phoneNumber,
      friendlyName: importFriendlyName || selectedImportNumber.friendlyName,
      sid: selectedImportNumber.sid,
      capabilities: selectedImportNumber.capabilities,
    });
  };

  const handlePurchase = () => {
    if (!selectedPurchaseNumber) return;
    purchaseMutation.mutate({
      phoneNumber: selectedPurchaseNumber.phoneNumber,
      friendlyName: purchaseFriendlyName || undefined,
    });
  };

  const handleRelease = (number: TwilioNumber) => {
    if (confirm(t("admin.systemNumbers.releaseConfirm", { number: formatPhoneNumber(number.phoneNumber) }))) {
      releaseMutation.mutate(number.sid);
    }
  };

  const handleSearch = () => {
    setSearchTriggered(true);
    setSelectedPurchaseNumber(null);
    refetchSearch();
  };

  const resetAndClose = () => {
    onOpenChange(false);
    setSelectedImportNumber(null);
    setImportFriendlyName("");
    setSelectedPurchaseNumber(null);
    setPurchaseFriendlyName("");
    setSearchContains("");
    setSearchTriggered(false);
    setActiveTab("import");
  };

  const formatPhoneNumber = (phone: string) => {
    const cleaned = phone.replace(/\D/g, "");
    if (cleaned.length === 11 && cleaned.startsWith("1")) {
      return `+1 (${cleaned.substring(1, 4)}) ${cleaned.substring(4, 7)}-${cleaned.substring(7)}`;
    }
    return phone;
  };

  const detectNumberType = (phoneNumber: string): string => {
    if (/^\+1(800|888|877|866|855|844|833)/.test(phoneNumber)) return 'Toll-Free';
    if (/^\+971800/.test(phoneNumber)) return 'Toll-Free';
    if (/^\+44(800|808)/.test(phoneNumber)) return 'Toll-Free';
    if (/^\+61(1800|1300)/.test(phoneNumber)) return 'Toll-Free';
    if (/^\+49(800)/.test(phoneNumber)) return 'Toll-Free';
    if (/^\+33(800|805)/.test(phoneNumber)) return 'Toll-Free';
    return 'Local';
  };

  const getCountryFlag = (phoneNumber: string): string | null => {
    if (phoneNumber.startsWith('+971')) return 'AE';
    if (phoneNumber.startsWith('+966')) return 'SA';
    if (phoneNumber.startsWith('+974')) return 'QA';
    if (phoneNumber.startsWith('+44')) return 'GB';
    if (phoneNumber.startsWith('+61')) return 'AU';
    if (phoneNumber.startsWith('+49')) return 'DE';
    if (phoneNumber.startsWith('+33')) return 'FR';
    if (phoneNumber.startsWith('+1')) return 'US';
    return null;
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle>{t("admin.systemNumbers.title")}</DialogTitle>
          <DialogDescription>
            {t("admin.systemNumbers.description")}
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="import" data-testid="tab-import-existing">{t("admin.systemNumbers.importExisting")}</TabsTrigger>
            <TabsTrigger value="purchase" data-testid="tab-purchase-new">{t("admin.systemNumbers.purchaseNew")}</TabsTrigger>
          </TabsList>

          <TabsContent value="import" className="space-y-6">
            <div className="space-y-3">
              <div className="flex items-center justify-between flex-wrap gap-2">
                <div>
                  <Label>{t("admin.systemNumbers.activeTwilioNumbers")}</Label>
                  <p className="text-xs text-muted-foreground mt-1">
                    {t("admin.systemNumbers.activeTwilioDesc")}
                  </p>
                </div>
                <Button
                  variant="outline"
                  onClick={() => refetchTwilio()}
                  disabled={loadingNumbers}
                  data-testid="button-load-twilio-numbers"
                >
                  {loadingNumbers ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <>
                      <Download className="h-4 w-4 mr-2" />
                      {t("admin.systemNumbers.loadFromTwilio")}
                    </>
                  )}
                </Button>
              </div>
            </div>

            {twilioNumbers.length > 0 && (
              <div className="space-y-3">
                <Label>{t("admin.systemNumbers.availableCount", { count: twilioNumbers.length })}</Label>
                <ScrollArea className="h-[300px] border rounded-lg">
                  <div className="p-4 space-y-2">
                    {twilioNumbers.map((number) => (
                      <div
                        key={number.sid}
                        className={`p-4 rounded-lg border transition-all hover-elevate ${
                          selectedImportNumber?.sid === number.sid
                            ? "border-primary bg-primary/5"
                            : "border-border"
                        }`}
                        data-testid={`number-import-${number.phoneNumber}`}
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div 
                            className="flex-1 space-y-2 cursor-pointer"
                            onClick={() => setSelectedImportNumber(number)}
                          >
                            <div className="flex items-center gap-2 flex-wrap">
                              <Phone className="h-4 w-4 text-muted-foreground" />
                              <span className="font-mono font-semibold text-lg">
                                {formatPhoneNumber(number.phoneNumber)}
                              </span>
                              {getCountryFlag(number.phoneNumber) && (
                                <Badge variant="outline" className="text-xs">
                                  <Globe className="h-3 w-3 mr-1" />
                                  {getCountryFlag(number.phoneNumber)}
                                </Badge>
                              )}
                            </div>
                            <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                              <span>{number.friendlyName}</span>
                              {detectNumberType(number.phoneNumber) === 'Toll-Free' && (
                                <Badge variant="outline" className="text-xs">Toll-Free</Badge>
                              )}
                            </div>
                            {number.pricing && (
                              <div className="text-sm space-y-1">
                                <div>
                                  <span className="font-semibold text-foreground">${number.pricing.purchasePrice}</span>
                                  <span className="text-muted-foreground"> {t("admin.systemNumbers.purchase")}</span>
                                </div>
                                <div>
                                  <span className="font-semibold text-foreground">${number.pricing.monthlyPrice}</span>
                                  <span className="text-muted-foreground">{t("admin.systemNumbers.perMonth")}</span>
                                </div>
                              </div>
                            )}
                            {number.capabilities && (
                              <div className="flex gap-2 flex-wrap">
                                {number.capabilities.voice && (
                                  <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.voice")}</Badge>
                                )}
                                {number.capabilities.sms && (
                                  <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.sms")}</Badge>
                                )}
                                {number.capabilities.mms && (
                                  <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.mms")}</Badge>
                                )}
                              </div>
                            )}
                          </div>
                          <div className="flex flex-col gap-2 items-end">
                            {selectedImportNumber?.sid === number.sid && (
                              <CheckCircle2 className="h-5 w-5 text-primary flex-shrink-0" />
                            )}
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleRelease(number)}
                              disabled={releaseMutation.isPending}
                              data-testid={`button-release-${number.phoneNumber}`}
                            >
                              <Trash2 className="h-3 w-3 mr-1" />
                              {t("admin.systemNumbers.release")}
                            </Button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </div>
            )}

            {twilioNumbers.length === 0 && !loadingNumbers && (
              <div className="text-center py-8 text-muted-foreground">
                <Phone className="h-12 w-12 mx-auto mb-3 opacity-20" />
                <p>{t("admin.systemNumbers.clickToFetch")}</p>
              </div>
            )}

            {selectedImportNumber && (
              <div className="space-y-3 p-4 border rounded-lg bg-muted/30">
                <h4 className="font-semibold">{t("admin.systemNumbers.configureSystemNumber")}</h4>
                <div className="space-y-2">
                  <Label htmlFor="import-friendly-name">{t("admin.systemNumbers.friendlyNameOptional")}</Label>
                  <Input
                    id="import-friendly-name"
                    placeholder={selectedImportNumber.friendlyName}
                    value={importFriendlyName}
                    onChange={(e) => setImportFriendlyName(e.target.value)}
                    data-testid="input-import-friendly-name"
                  />
                </div>
                <div className="text-sm text-muted-foreground">
                  <p>{t("admin.systemNumbers.selected")} <span className="font-mono font-semibold text-foreground">{formatPhoneNumber(selectedImportNumber.phoneNumber)}</span></p>
                  <p className="mt-1">{t("admin.systemNumbers.importNote")}</p>
                </div>
              </div>
            )}

            <div className="flex justify-end gap-3 pt-4 border-t flex-wrap">
              <Button
                variant="outline"
                onClick={resetAndClose}
                disabled={importMutation.isPending}
                data-testid="button-cancel-import"
              >
                {t("common.cancel")}
              </Button>
              <Button
                onClick={handleImport}
                disabled={!selectedImportNumber || importMutation.isPending}
                data-testid="button-import-to-system-pool"
              >
                {importMutation.isPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    {t("admin.systemNumbers.importing")}
                  </>
                ) : (
                  t("admin.systemNumbers.importToSystemPool")
                )}
              </Button>
            </div>
          </TabsContent>

          <TabsContent value="purchase" className="space-y-6">
            <div className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <div className="space-y-2">
                  <Label>Country</Label>
                  <Select value={searchCountry} onValueChange={setSearchCountry}>
                    <SelectTrigger data-testid="select-country">
                      <SelectValue placeholder="Select country" />
                    </SelectTrigger>
                    <SelectContent>
                      {COUNTRIES.map((c) => (
                        <SelectItem key={c.code} value={c.code}>
                          {c.name} ({c.prefix})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Number Type</Label>
                  <Select value={searchNumberType} onValueChange={setSearchNumberType}>
                    <SelectTrigger data-testid="select-number-type">
                      <SelectValue placeholder="Select type" />
                    </SelectTrigger>
                    <SelectContent>
                      {NUMBER_TYPES.map((t) => (
                        <SelectItem key={t.value} value={t.value}>
                          {t.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Contains (optional)</Label>
                  <Input
                    placeholder="e.g. 800"
                    value={searchContains}
                    onChange={(e) => setSearchContains(e.target.value)}
                    data-testid="input-search-contains"
                  />
                </div>
              </div>
              <Button
                variant="outline"
                onClick={handleSearch}
                disabled={searchLoading}
                className="w-full sm:w-auto"
                data-testid="button-search-numbers"
              >
                {searchLoading ? (
                  <Loader2 className="h-4 w-4 animate-spin mr-2" />
                ) : (
                  <Search className="h-4 w-4 mr-2" />
                )}
                Search Available Numbers
              </Button>
            </div>

            {availableNumbers.length > 0 && (
              <div className="space-y-3">
                <Label>{t("admin.systemNumbers.availableNumbers")} ({availableNumbers.length})</Label>
                <ScrollArea className="h-[300px] border rounded-lg">
                  <div className="p-4 space-y-2">
                    {availableNumbers.map((number) => (
                      <div
                        key={number.phoneNumber}
                        className={`p-4 rounded-lg border cursor-pointer transition-all hover-elevate ${
                          selectedPurchaseNumber?.phoneNumber === number.phoneNumber
                            ? "border-primary bg-primary/5"
                            : "border-border"
                        }`}
                        onClick={() => setSelectedPurchaseNumber(number)}
                        data-testid={`number-purchase-${number.phoneNumber}`}
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1 space-y-2">
                            <div className="flex items-center gap-2 flex-wrap">
                              <Phone className="h-4 w-4 text-muted-foreground" />
                              <span className="font-mono font-semibold text-lg">
                                {number.phoneNumber}
                              </span>
                              {number.numberType === 'toll_free' && (
                                <Badge variant="outline" className="text-xs">Toll-Free</Badge>
                              )}
                              {number.isoCountry && (
                                <Badge variant="secondary" className="text-xs">
                                  <Globe className="h-3 w-3 mr-1" />
                                  {number.isoCountry}
                                </Badge>
                              )}
                            </div>
                            {(number.locality || number.region) && (
                              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                <MapPin className="h-3 w-3" />
                                <span>
                                  {[number.locality, number.region].filter(Boolean).join(", ")}
                                </span>
                              </div>
                            )}
                            <div className="flex gap-2 flex-wrap">
                              {number.capabilities.voice && (
                                <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.voice")}</Badge>
                              )}
                              {number.capabilities.sms && (
                                <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.sms")}</Badge>
                              )}
                              {number.capabilities.mms && (
                                <Badge variant="secondary" className="text-xs">{t("admin.systemNumbers.mms")}</Badge>
                              )}
                            </div>
                          </div>
                          {selectedPurchaseNumber?.phoneNumber === number.phoneNumber && (
                            <CheckCircle2 className="h-5 w-5 text-primary flex-shrink-0" />
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </div>
            )}

            {searchTriggered && availableNumbers.length === 0 && !searchLoading && (
              <div className="text-center py-6 text-muted-foreground space-y-3">
                <Phone className="h-10 w-10 mx-auto mb-2 opacity-20" />
                <p className="text-sm">No numbers available for purchase in this country/type.</p>
                <p className="text-sm">If you already have a number provisioned in your Twilio account, switch to the <strong>Import Existing</strong> tab and click <strong>Load from Twilio</strong> to import it.</p>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setActiveTab("import")}
                  data-testid="button-switch-to-import"
                >
                  <Download className="h-4 w-4 mr-2" />
                  Go to Import Existing
                </Button>
              </div>
            )}

            {selectedPurchaseNumber && (
              <div className="space-y-3 p-4 border rounded-lg bg-muted/30">
                <h4 className="font-semibold">{t("admin.systemNumbers.configureSystemNumber")}</h4>
                <div className="space-y-2">
                  <Label htmlFor="purchase-friendly-name">{t("admin.systemNumbers.friendlyNameOptional")}</Label>
                  <Input
                    id="purchase-friendly-name"
                    placeholder="e.g., System Pool - UAE Toll-Free"
                    value={purchaseFriendlyName}
                    onChange={(e) => setPurchaseFriendlyName(e.target.value)}
                    data-testid="input-purchase-friendly-name"
                  />
                </div>
                <div className="text-sm text-muted-foreground">
                  <p>{t("admin.systemNumbers.selected")} <span className="font-mono font-semibold text-foreground">{selectedPurchaseNumber.phoneNumber}</span></p>
                  <p className="mt-1">{t("admin.systemNumbers.purchaseNote")}</p>
                </div>
              </div>
            )}

            <div className="flex justify-end gap-3 pt-4 border-t flex-wrap">
              <Button
                variant="outline"
                onClick={resetAndClose}
                disabled={purchaseMutation.isPending}
                data-testid="button-cancel-purchase"
              >
                {t("common.cancel")}
              </Button>
              <Button
                onClick={handlePurchase}
                disabled={!selectedPurchaseNumber || purchaseMutation.isPending}
                data-testid="button-purchase-to-system-pool"
              >
                {purchaseMutation.isPending ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    {t("admin.systemNumbers.purchasing")}
                  </>
                ) : (
                  t("admin.systemNumbers.purchaseAndAdd")
                )}
              </Button>
            </div>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

server/routes/admin/phone-numbers-routes.content:
'use strict';
import { Router, Response } from 'express';
import { storage } from '../../storage';
import { AdminRequest } from '../../middleware/admin-auth';
import { db } from '../../db';
import { eq, isNull, and, sql, isNotNull, or, inArray, desc } from 'drizzle-orm';
import { phoneNumbers, agents, incomingAgents, incomingConnections, calls, users } from '@shared/schema';
import { ElevenLabsPoolService } from '../../services/elevenlabs-pool';
import { ElevenLabsService } from '../../services/elevenlabs';
import { z } from 'zod';

export function registerPhoneNumbersRoutes(router: Router) {
  router.get('/phone-numbers', async (req: AdminRequest, res: Response) => {
    try {
      const numbers = await storage.getAllPhoneNumbers();
      res.json(numbers);
    } catch (error) {
      console.error('Error fetching phone numbers:', error);
      res.status(500).json({ error: 'Failed to fetch phone numbers' });
    }
  });

  router.get('/phone-numbers/twilio-active', async (req: AdminRequest, res: Response) => {
    try {
      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.json([]);
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      const incomingNumbers = await client.incomingPhoneNumbers.list({ limit: 100 });

      console.log(`[Twilio Active] Found ${incomingNumbers.length} numbers in Twilio account:`);
      incomingNumbers.forEach(n => {
        console.log(`  - ${n.phoneNumber} (${n.friendlyName}) SID: ${n.sid}`);
      });

      const existingNumbers = await db.select({ phoneNumber: phoneNumbers.phoneNumber }).from(phoneNumbers);
      const existingSet = new Set(existingNumbers.map(n => n.phoneNumber));

      console.log(`[Twilio Active] Already imported numbers: ${Array.from(existingSet).join(', ')}`);

      const numbers = incomingNumbers
        .filter(n => !existingSet.has(n.phoneNumber))
        .map(n => ({
          sid: n.sid,
          phoneNumber: n.phoneNumber,
          friendlyName: n.friendlyName,
          capabilities: n.capabilities
        }));

      console.log(`[Twilio Active] Returning ${numbers.length} available for import`);

      res.json(numbers);
    } catch (error: any) {
      console.error('Error fetching Twilio numbers:', error);
      res.status(500).json({ error: error.message || 'Failed to fetch Twilio numbers' });
    }
  });

  router.get('/phone-numbers/search-available', async (req: AdminRequest, res: Response) => {
    try {
      const { country, numberType, areaCode, contains } = req.query;

      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.status(400).json({ error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      const countryCode = (country as string) || 'US';
      const type = (numberType as string) || 'local';
      const listOptions: any = { limit: 20 };

      if (contains) listOptions.contains = contains as string;

      let numbers: any[] = [];
      let resolvedType = type;

      if (type === 'toll_free' || type === 'tollFree') {
        numbers = await client.availablePhoneNumbers(countryCode).tollFree.list(listOptions);
      } else if (type === 'mobile') {
        if (areaCode) listOptions.areaCode = parseInt(areaCode as string, 10);
        try {
          numbers = await client.availablePhoneNumbers(countryCode).mobile.list(listOptions);
        } catch (err: any) {
          if (err.code === 20404 || err.status === 404) {
            const tfOptions: any = { limit: 20 };
            if (contains) tfOptions.contains = contains as string;
            try {
              numbers = await client.availablePhoneNumbers(countryCode).tollFree.list(tfOptions);
              resolvedType = 'toll_free';
            } catch (tfErr: any) {
              if (tfErr.code === 20404 || tfErr.status === 404) {
                numbers = [];
              } else {
                throw tfErr;
              }
            }
          } else {
            throw err;
          }
        }
      } else {
        if (areaCode) listOptions.areaCode = parseInt(areaCode as string, 10);
        try {
          numbers = await client.availablePhoneNumbers(countryCode).local.list(listOptions);
        } catch (err: any) {
          if (err.code === 20404 || err.status === 404) {
            const tfOptions: any = { limit: 20 };
            if (contains) tfOptions.contains = contains as string;
            try {
              numbers = await client.availablePhoneNumbers(countryCode).tollFree.list(tfOptions);
              resolvedType = 'toll_free';
            } catch (tfErr: any) {
              if (tfErr.code === 20404 || tfErr.status === 404) {
                numbers = [];
              } else {
                throw tfErr;
              }
            }
          } else {
            throw err;
          }
        }
      }

      res.json(numbers.map((num: any) => ({
        phoneNumber: num.phoneNumber,
        friendlyName: num.friendlyName,
        locality: num.locality,
        region: num.region,
        isoCountry: num.isoCountry,
        numberType: resolvedType,
        capabilities: {
          voice: num.capabilities?.voice ?? false,
          sms: num.capabilities?.sms ?? false,
          mms: num.capabilities?.mms ?? false,
        }
      })));
    } catch (error: any) {
      console.error('Error searching available numbers:', error);
      res.status(500).json({ error: error.message || 'Failed to search available numbers' });
    }
  });

  router.post('/phone-numbers/import', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumber, twilioSid, provider, friendlyName, capabilities, numberType } = req.body;

      if (!phoneNumber) {
        return res.status(400).json({ error: 'Phone number is required' });
      }

      const existing = await db.select().from(phoneNumbers).where(eq(phoneNumbers.phoneNumber, phoneNumber));
      if (existing.length > 0) {
        return res.status(400).json({ error: 'Phone number already exists' });
      }

      const countryPrefixMap: Record<string, string> = {
        '+971': 'AE', '+966': 'SA', '+974': 'QA', '+973': 'BH', '+968': 'OM', '+965': 'KW',
        '+353': 'IE', '+351': 'PT', '+358': 'FI',
        '+61': 'AU', '+44': 'GB', '+49': 'DE', '+33': 'FR', '+39': 'IT',
        '+34': 'ES', '+31': 'NL', '+32': 'BE', '+43': 'AT', '+41': 'CH',
        '+46': 'SE', '+47': 'NO', '+45': 'DK',
        '+48': 'PL', '+64': 'NZ', '+65': 'SG', '+81': 'JP', '+82': 'KR',
        '+91': 'IN', '+86': 'CN', '+55': 'BR', '+52': 'MX',
        '+27': 'ZA', '+60': 'MY', '+63': 'PH', '+66': 'TH',
        '+1': 'US',
      };
      let detectedCountry = 'US';
      const sortedPrefixes = Object.keys(countryPrefixMap).sort((a, b) => b.length - a.length);
      for (const prefix of sortedPrefixes) {
        if (phoneNumber.startsWith(prefix)) {
          detectedCountry = countryPrefixMap[prefix];
          break;
        }
      }

      let detectedNumberType = numberType || 'local';
      if (!numberType || numberType === 'local') {
        if (/^\+1(800|888|877|866|855|844|833)/.test(phoneNumber)) detectedNumberType = 'toll_free';
        else if (/^\+971800/.test(phoneNumber)) detectedNumberType = 'toll_free';
        else if (/^\+44(800|808)/.test(phoneNumber)) detectedNumberType = 'toll_free';
        else if (/^\+61(1800|1300)/.test(phoneNumber)) detectedNumberType = 'toll_free';
        else if (/^\+49(800)/.test(phoneNumber)) detectedNumberType = 'toll_free';
        else if (/^\+33(800|805)/.test(phoneNumber)) detectedNumberType = 'toll_free';
      }

      const [newNumber] = await db.insert(phoneNumbers).values({
        phoneNumber: phoneNumber,
        twilioSid: twilioSid || 'imported-' + Date.now(),
        friendlyName: friendlyName || phoneNumber,
        country: detectedCountry,
        capabilities: capabilities || null,
        numberType: detectedNumberType,
        status: 'active',
        isSystemPool: true,
      }).returning();

      res.json({ success: true, phoneNumber: newNumber });
    } catch (error: any) {
      console.error('Error importing phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to import phone number' });
    }
  });

  router.delete('/phone-numbers/release/:sid', async (req: AdminRequest, res: Response) => {
    try {
      const { sid } = req.params;

      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.status(400).json({ error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      await client.incomingPhoneNumbers(sid).remove();

      await db.delete(phoneNumbers).where(eq(phoneNumbers.twilioSid, sid));

      res.json({ success: true });
    } catch (error: any) {
      console.error('Error releasing phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to release phone number' });
    }
  });

  router.get('/phone-numbers/all', async (req: AdminRequest, res: Response) => {
    try {
      const allNumbers = await db
        .select({
          id: phoneNumbers.id,
          phoneNumber: phoneNumbers.phoneNumber,
          status: phoneNumbers.status,
          userId: phoneNumbers.userId,
          twilioSid: phoneNumbers.twilioSid,
          country: phoneNumbers.country,
          numberType: phoneNumbers.numberType,
          createdAt: phoneNumbers.createdAt,
          userName: users.name,
          userEmail: users.email
        })
        .from(phoneNumbers)
        .leftJoin(users, eq(phoneNumbers.userId, users.id))
        .orderBy(desc(phoneNumbers.createdAt));

      res.json(allNumbers);
    } catch (error) {
      console.error('Error fetching all phone numbers:', error);
      res.status(500).json({ error: 'Failed to fetch phone numbers' });
    }
  });

  router.patch('/phone-numbers/:id/assign', async (req: AdminRequest, res: Response) => {
    try {
      const { id } = req.params;
      const { userId } = req.body;

      const phoneNumber = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, id));
      if (phoneNumber.length === 0) {
        return res.status(404).json({ error: 'Phone number not found' });
      }

      if (userId) {
        const user = await storage.getUser(userId);
        if (!user) {
          return res.status(404).json({ error: 'User not found' });
        }
      }

      await db.update(phoneNumbers)
        .set({ 
          userId: userId || null,
          status: userId ? 'assigned' : 'available'
        })
        .where(eq(phoneNumbers.id, id));

      res.json({ success: true });
    } catch (error) {
      console.error('Error assigning phone number:', error);
      res.status(500).json({ error: 'Failed to assign phone number' });
    }
  });

  router.post('/phone-numbers/configure-webhooks', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberIds, webhookUrl } = req.body;

      if (!phoneNumberIds || !Array.isArray(phoneNumberIds) || phoneNumberIds.length === 0) {
        return res.status(400).json({ error: 'Phone number IDs are required' });
      }

      if (!webhookUrl) {
        return res.status(400).json({ error: 'Webhook URL is required' });
      }

      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.status(400).json({ error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      const results: any[] = [];

      for (const id of phoneNumberIds) {
        const phoneNumberRecord = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, id));
        if (phoneNumberRecord.length === 0 || !phoneNumberRecord[0].twilioSid) {
          results.push({ id, success: false, error: 'Phone number not found or no Twilio SID' });
          continue;
        }

        try {
          await client.incomingPhoneNumbers(phoneNumberRecord[0].twilioSid).update({
            voiceUrl: webhookUrl,
            voiceMethod: 'POST'
          });
          results.push({ id, success: true });
        } catch (err: any) {
          results.push({ id, success: false, error: err.message });
        }
      }

      res.json({ success: true, results });
    } catch (error: any) {
      console.error('Error configuring webhooks:', error);
      res.status(500).json({ error: error.message || 'Failed to configure webhooks' });
    }
  });

  router.get('/phone-numbers/migration-status', async (req: AdminRequest, res: Response) => {
    try {
      const numbersNeedingMigration = await db
        .select({
          id: phoneNumbers.id,
          number: phoneNumbers.phoneNumber,
          status: phoneNumbers.status
        })
        .from(phoneNumbers)
        .where(
          and(
            eq(phoneNumbers.status, 'active'),
            isNull(phoneNumbers.elevenLabsPhoneNumberId)
          )
        );

      res.json({
        needsMigration: numbersNeedingMigration.length,
        numbers: numbersNeedingMigration
      });
    } catch (error) {
      console.error('Error getting migration status:', error);
      res.status(500).json({ error: 'Failed to get migration status' });
    }
  });

  router.post('/phone-numbers/migrate/:phoneNumberId', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberId } = req.params;

      const phoneNumber = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, phoneNumberId));
      if (phoneNumber.length === 0) {
        return res.status(404).json({ error: 'Phone number not found' });
      }

      await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: 'migrated-' + Date.now() })
        .where(eq(phoneNumbers.id, phoneNumberId));

      res.json({ success: true, message: 'Phone number marked as migrated' });
    } catch (error: any) {
      console.error('Error migrating phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate phone number' });
    }
  });

  router.post('/phone-numbers/migrate-all', async (req: AdminRequest, res: Response) => {
    try {
      const result = await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: 'migrated-' + Date.now() })
        .where(isNull(phoneNumbers.elevenLabsPhoneNumberId));

      res.json({ success: true, message: 'All phone numbers marked as migrated' });
    } catch (error: any) {
      console.error('Error migrating all phone numbers:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate phone numbers' });
    }
  });

  router.post('/phone-numbers/migrate-agent/:agentId', async (req: AdminRequest, res: Response) => {
    try {
      const { agentId } = req.params;

      res.json({ success: true, message: 'Agent migration endpoint - not implemented' });
    } catch (error: any) {
      console.error('Error migrating agent:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate agent' });
    }
  });

  router.post('/phone-numbers/cleanup', async (req: AdminRequest, res: Response) => {
    try {
      const orphanedNumbers = await db
        .select()
        .from(phoneNumbers)
        .where(
          and(
            isNotNull(phoneNumbers.userId),
            eq(phoneNumbers.status, 'assigned')
          )
        );

      let cleaned = 0;
      for (const number of orphanedNumbers) {
        if (number.userId) {
          const user = await storage.getUser(number.userId);
          if (!user) {
            await db.update(phoneNumbers)
              .set({ userId: null, status: 'available' })
              .where(eq(phoneNumbers.id, number.id));
            cleaned++;
          }
        }
      }

      res.json({ success: true, cleaned });
    } catch (error) {
      console.error('Error cleaning up phone numbers:', error);
      res.status(500).json({ error: 'Failed to cleanup phone numbers' });
    }
  });

  router.post('/phone-numbers/clear-sync-status', async (req: AdminRequest, res: Response) => {
    try {
      await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: null })
        .where(isNotNull(phoneNumbers.elevenLabsPhoneNumberId));

      res.json({ success: true, message: 'Sync status cleared for all phone numbers' });
    } catch (error) {
      console.error('Error clearing sync status:', error);
      res.status(500).json({ error: 'Failed to clear sync status' });
    }
  });

  router.post('/phone-numbers/sync-to-elevenlabs', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberIds } = req.body;

      if (!phoneNumberIds || !Array.isArray(phoneNumberIds)) {
        return res.status(400).json({ error: 'Phone number IDs array is required' });
      }

      res.json({ success: true, message: 'Sync to ElevenLabs - functionality placeholder' });
    } catch (error: any) {
      console.error('Error syncing to ElevenLabs:', error);
      res.status(500).json({ error: error.message || 'Failed to sync to ElevenLabs' });
    }
  });
}

