  const [isAddKeyDialogOpen, setIsAddKeyDialogOpen] = useState(false);
  const [newKeyPath, setNewKeyPath] = useState("");
  const [newKeyValue, setNewKeyValue] = useState("");
  const [syncKeyToAll, setSyncKeyToAll] = useState(true);
  const [keyPathError, setKeyPathError] = useState<string | null>(null);

  const [isDeleteKeyDialogOpen, setIsDeleteKeyDialogOpen] = useState(false);
  const [keyToDelete, setKeyToDelete] = useState<string | null>(null);
  const [deleteFromAll, setDeleteFromAll] = useState(true);

  const { data: languages = [], isLoading } = useQuery<PlatformLanguage[]>({
    queryKey: ["/api/admin/platform-languages"],
  });

  const englishLanguage = useMemo(() => 
    languages.find(l => l.code === "en"), 
    [languages]
  );

  const seedLanguagesMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("POST", "/api/admin/platform-languages/seed");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      toast({
        title: t("common.success"),
        description: "Default languages have been seeded successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const createLanguageMutation = useMutation({
    mutationFn: async (data: {
      code: string;
      name: string;
      nativeName: string;
      flag?: string;
      direction: "ltr" | "rtl";
      translations: Record<string, unknown>;
    }) => {
      return apiRequest("POST", "/api/admin/platform-languages", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      setIsAddDialogOpen(false);
      resetAddForm();
      toast({
        title: t("common.success"),
        description: "Language created successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const updateLanguageMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: Partial<PlatformLanguage> }) => {
      return apiRequest("PATCH", `/api/admin/platform-languages/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      setIsEditDialogOpen(false);
      setIsTranslationEditorOpen(false);
      setHasTranslationChanges(false);
      toast({
        title: t("common.success"),
        description: "Language updated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const deleteLanguageMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest("DELETE", `/api/admin/platform-languages/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      setIsDeleteDialogOpen(false);
      setSelectedLanguage(null);
      toast({
        title: t("common.success"),
        description: "Language deleted successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const addKeyMutation = useMutation({
    mutationFn: async (data: { keyPath: string; values: Record<string, string>; syncToAll: boolean }) => {
      return apiRequest("POST", "/api/admin/platform-languages/add-key", data);
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      setIsAddKeyDialogOpen(false);
      setNewKeyPath("");
      setNewKeyValue("");
      setSyncKeyToAll(true);
      setKeyPathError(null);
      setIsTranslationEditorOpen(false);
      toast({
        title: t("common.success"),
        description: "Translation key added successfully. Reopen the editor to see the new key.",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const deleteKeyMutation = useMutation({
    mutationFn: async (data: { keyPath: string; languageId?: string }) => {
      return apiRequest("POST", "/api/admin/platform-languages/delete-key", data);
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["/api/admin/platform-languages"] });
      setIsDeleteKeyDialogOpen(false);
      setKeyToDelete(null);
      setDeleteFromAll(true);
      setIsTranslationEditorOpen(false);
      toast({
        title: t("common.success"),
        description: "Translation key deleted successfully. Reopen the editor to see updated translations.",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: t("common.error"),
        description: error.message,
      });
    },
  });

  const resetAddForm = () => {
    setNewLanguageCode("");
    setNewLanguageName("");
    setNewLanguageNativeName("");
    setNewLanguageFlag("");
    setNewLanguageDirection("ltr");
    setCopyFromLanguage("none");
  };

  const handleAddLanguage = () => {
    let translations: Record<string, unknown> = {};

    if (copyFromLanguage && copyFromLanguage !== "none") {
      const sourceLanguage = languages.find(l => l.code === copyFromLanguage);
      if (sourceLanguage) {
        translations = sourceLanguage.translations as Record<string, unknown>;
      }
    }

    createLanguageMutation.mutate({
      code: newLanguageCode,
      name: newLanguageName,
      nativeName: newLanguageNativeName,
      flag: newLanguageFlag || undefined,
      direction: newLanguageDirection,
      translations,
    });
  };

  const handleOpenEdit = (language: PlatformLanguage) => {
    setSelectedLanguage(language);
    setEditName(language.name);
    setEditNativeName(language.nativeName);
    setEditFlag(language.flag || "");
    setEditDirection(language.direction as "ltr" | "rtl");
    setIsEditDialogOpen(true);
  };

  const handleSaveEdit = () => {
    if (!selectedLanguage) return;
    updateLanguageMutation.mutate({
      id: selectedLanguage.id,
      data: {
        name: editName,
        nativeName: editNativeName,
        flag: editFlag || undefined,
        direction: editDirection,
      },
    });
  };

  const handleToggleEnabled = (language: PlatformLanguage) => {
    updateLanguageMutation.mutate({
      id: language.id,
      data: { isEnabled: !language.isEnabled },
    });
  };

  const handleSetDefault = (language: PlatformLanguage) => {
    if (language.isDefault) return;
    updateLanguageMutation.mutate({
      id: language.id,
      data: { isDefault: true },
    });
  };

  const handleOpenTranslationEditor = (language: PlatformLanguage) => {
    setSelectedLanguage(language);
    setEditedTranslations(language.translations as Record<string, unknown>);
    setHasTranslationChanges(false);
    setTranslationSearch("");
    setExpandedSections(new Set());
    setIsTranslationEditorOpen(true);
  };

  const handleTranslationChange = (path: string[], value: string) => {
    const newTranslations = setNestedValue(editedTranslations, path, value);
    setEditedTranslations(newTranslations);
    setHasTranslationChanges(true);
  };

  const handleSaveTranslations = () => {
    if (!selectedLanguage) return;
    updateLanguageMutation.mutate({
      id: selectedLanguage.id,
      data: { translations: editedTranslations },
    });
  };

  const toggleSection = (section: string) => {
    const newExpanded = new Set(expandedSections);
    if (newExpanded.has(section)) {
      newExpanded.delete(section);
    } else {
      newExpanded.add(section);
    }
    setExpandedSections(newExpanded);
  };

  const filteredTranslationEntries = useMemo(() => {
    const flattened = flattenTranslations(editedTranslations);
    const englishFlattened = englishLanguage 
      ? Object.fromEntries(
          flattenTranslations(englishLanguage.translations as Record<string, unknown>)
            .map(e => [e.key, e.value])
        )
      : {};

    const entries: TranslationEntry[] = flattened.map(entry => ({
      key: entry.key,
      path: entry.key.split("."),
      value: String(entry.value ?? ""),
      englishValue: String(englishFlattened[entry.key] ?? ""),
      isCustom: entry.key.startsWith("custom."),
    }));

    if (!translationSearch) return entries;

    const search = translationSearch.toLowerCase();
    return entries.filter(
      entry => 
        entry.key.toLowerCase().includes(search) ||
        entry.value.toLowerCase().includes(search) ||
        entry.englishValue.toLowerCase().includes(search)
    );
  }, [editedTranslations, englishLanguage, translationSearch]);

  const validateKeyPath = (path: string): string | null => {
    if (!path) return "Key path is required";
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*(\.[a-zA-Z_][a-zA-Z0-9_]*)*$/.test(path)) {
      return "Invalid format. Use: section.subsection.key (letters, numbers, underscores only)";
    }
    const existingKeys = flattenTranslations(editedTranslations).map(e => e.key);
    if (existingKeys.includes(path)) {
      return "This key already exists";
    }
    return null;
  };

  const handleAddKey = () => {
    if (!selectedLanguage) return;
    const error = validateKeyPath(newKeyPath);
    if (error) {
      setKeyPathError(error);
      return;
    }

    const values: Record<string, string> = {
      [selectedLanguage.code]: newKeyValue,
    };

    addKeyMutation.mutate({
      keyPath: newKeyPath,
      values,
      syncToAll: syncKeyToAll,
    });
  };

  const handleDeleteKey = () => {
    if (!keyToDelete) return;

    deleteKeyMutation.mutate({
      keyPath: keyToDelete,
      languageId: deleteFromAll ? undefined : selectedLanguage?.id,
    });
  };

  const openDeleteKeyDialog = (keyPath: string) => {
    setKeyToDelete(keyPath);
    setDeleteFromAll(true);
    setIsDeleteKeyDialogOpen(true);
  };

  const groupedTranslations = useMemo(() => {
    const groups: Record<string, TranslationEntry[]> = {};
    for (const entry of filteredTranslationEntries) {
      const section = entry.path[0];
      if (!groups[section]) {
        groups[section] = [];
      }
      groups[section].push(entry);
    }
    return groups;
  }, [filteredTranslationEntries]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (languages.length === 0) {
    return (
      <div className="space-y-6">
        <div>
          <h2 className="text-2xl font-bold">{t("admin.languages.title") || "Language Management"}</h2>
          <p className="text-muted-foreground">
            {t("admin.languages.description") || "Manage platform languages and translations"}
          </p>
        </div>

        <Card>
          <CardContent className="flex flex-col items-center justify-center py-12 gap-4">
            <div className="rounded-full bg-muted p-4">
              <Languages className="h-8 w-8 text-muted-foreground" />
            </div>
            <div className="text-center">
              <h3 className="text-lg font-semibold">No Languages Configured</h3>
              <p className="text-muted-foreground mt-1">
                Get started by seeding the default platform languages
              </p>
            </div>
            <Button
              size="lg"
              onClick={() => seedLanguagesMutation.mutate()}
              disabled={seedLanguagesMutation.isPending}
              data-testid="button-seed-languages"
            >
              {seedLanguagesMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Sprout className="mr-2 h-4 w-4" />
              )}
              Seed Default Languages
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-row items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold">{t("admin.languages.title") || "Language Management"}</h2>
          <p className="text-muted-foreground">
            {t("admin.languages.description") || "Manage platform languages and translations"}
          </p>
        </div>
        <Button onClick={() => setIsAddDialogOpen(true)} data-testid="button-add-language">
          <Plus className="mr-2 h-4 w-4" />
          Add Language
        </Button>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Globe className="h-5 w-5" />
            Platform Languages
          </CardTitle>
          <CardDescription>
            {languages.length} language{languages.length !== 1 ? "s" : ""} configured
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-16">Flag</TableHead>
                <TableHead>Language</TableHead>
                <TableHead>Native Name</TableHead>
                <TableHead className="w-20">Code</TableHead>
                <TableHead className="w-24">Direction</TableHead>
                <TableHead className="w-20 text-center">
                  <div className="flex items-center justify-center gap-1">
                    <ArrowUpDown className="h-3 w-3" />
                    Order
                  </div>
                </TableHead>
                <TableHead className="w-24 text-center">Enabled</TableHead>
                <TableHead className="w-24 text-center">Default</TableHead>
                <TableHead className="w-40 text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {languages.map((language) => (
                <TableRow key={language.id} data-testid={`row-language-${language.id}`}>
                  <TableCell className="text-2xl">{language.flag || "🌐"}</TableCell>
                  <TableCell className="font-medium">{language.name}</TableCell>
                  <TableCell>{language.nativeName}</TableCell>
                  <TableCell>
                    <Badge variant="outline" className="font-mono">
                      {language.code}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <Badge variant={language.direction === "rtl" ? "secondary" : "outline"}>
                      {language.direction.toUpperCase()}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-center text-muted-foreground">
                    {language.sortOrder}
                  </TableCell>
                  <TableCell className="text-center">
                    <Switch
                      checked={language.isEnabled}
                      onCheckedChange={() => handleToggleEnabled(language)}
                      disabled={language.isDefault || updateLanguageMutation.isPending}
                      data-testid={`switch-enabled-${language.id}`}
                    />
                  </TableCell>
                  <TableCell className="text-center">
                    {language.isDefault ? (
                      <Badge className="bg-amber-500/10 text-amber-600 border-amber-500/20">
                        <Star className="h-3 w-3 mr-1 fill-current" />
                        Default
                      </Badge>
                    ) : (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleSetDefault(language)}
                        disabled={updateLanguageMutation.isPending}
                        data-testid={`button-set-default-${language.id}`}
                      >
                        Set Default
                      </Button>
                    )}
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleOpenTranslationEditor(language)}
                        data-testid={`button-translations-${language.id}`}
                      >
                        <Languages className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleOpenEdit(language)}
                        data-testid={`button-edit-${language.id}`}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => {
                          setSelectedLanguage(language);
                          setIsDeleteDialogOpen(true);
                        }}
                        disabled={language.isDefault}
                        data-testid={`button-delete-${language.id}`}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add New Language</DialogTitle>
            <DialogDescription>
              Add a new language to the platform
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="languageCode">Language Code *</Label>
              <Input
                id="languageCode"
                placeholder="e.g., en, es, zh-CN"
                value={newLanguageCode}
                onChange={(e) => setNewLanguageCode(e.target.value)}
                maxLength={5}
                data-testid="input-language-code"
              />
              <p className="text-xs text-muted-foreground">2-5 characters, ISO 639-1 format</p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="languageName">Display Name *</Label>
              <Input
                id="languageName"
                placeholder="e.g., English, Spanish"
                value={newLanguageName}
                onChange={(e) => setNewLanguageName(e.target.value)}
                data-testid="input-language-name"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="nativeName">Native Name *</Label>
              <Input
                id="nativeName"
                placeholder="e.g., English, Español"
                value={newLanguageNativeName}
                onChange={(e) => setNewLanguageNativeName(e.target.value)}
                data-testid="input-native-name"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="flag">Flag Emoji</Label>
                <Input
                  id="flag"
                  placeholder="🇺🇸"
                  value={newLanguageFlag}
                  onChange={(e) => setNewLanguageFlag(e.target.value)}
                  data-testid="input-flag"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="direction">Text Direction</Label>
                <Select value={newLanguageDirection} onValueChange={(v) => setNewLanguageDirection(v as "ltr" | "rtl")}>
                  <SelectTrigger data-testid="select-direction">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ltr">LTR (Left to Right)</SelectItem>
                    <SelectItem value="rtl">RTL (Right to Left)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="copyFrom">Copy Translations From</Label>
              <Select value={copyFromLanguage} onValueChange={setCopyFromLanguage}>
                <SelectTrigger data-testid="select-copy-from">
                  <SelectValue placeholder="Start with empty translations" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Start with empty translations</SelectItem>
                  {languages.map((lang) => (
                    <SelectItem key={lang.code} value={lang.code}>
                      {lang.flag} {lang.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                Optionally copy existing translations as a starting point
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsAddDialogOpen(false)} data-testid="button-cancel-add">
              Cancel
            </Button>
            <Button
              onClick={handleAddLanguage}
              disabled={!newLanguageCode || !newLanguageName || !newLanguageNativeName || createLanguageMutation.isPending}
              data-testid="button-confirm-add"
            >
              {createLanguageMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Add Language
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Edit Language</DialogTitle>
            <DialogDescription>
              Update language details for {selectedLanguage?.name}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="editName">Display Name</Label>
              <Input
                id="editName"
                value={editName}
                onChange={(e) => setEditName(e.target.value)}
                data-testid="input-edit-name"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="editNativeName">Native Name</Label>
              <Input
                id="editNativeName"
                value={editNativeName}
                onChange={(e) => setEditNativeName(e.target.value)}
                data-testid="input-edit-native-name"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="editFlag">Flag Emoji</Label>
                <Input
                  id="editFlag"
                  value={editFlag}
                  onChange={(e) => setEditFlag(e.target.value)}
                  data-testid="input-edit-flag"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="editDirection">Text Direction</Label>
                <Select value={editDirection} onValueChange={(v) => setEditDirection(v as "ltr" | "rtl")}>
                  <SelectTrigger data-testid="select-edit-direction">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="ltr">LTR</SelectItem>
                    <SelectItem value="rtl">RTL</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditDialogOpen(false)} data-testid="button-cancel-edit">
              Cancel
            </Button>
            <Button
              onClick={handleSaveEdit}
              disabled={!editName || !editNativeName || updateLanguageMutation.isPending}
              data-testid="button-confirm-edit"
            >
              {updateLanguageMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Save Changes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Delete Language</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete {selectedLanguage?.name}? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          {selectedLanguage?.isDefault && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                Cannot delete the default language. Set another language as default first.
              </AlertDescription>
            </Alert>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDeleteDialogOpen(false)} data-testid="button-cancel-delete">
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={() => selectedLanguage && deleteLanguageMutation.mutate(selectedLanguage.id)}
              disabled={selectedLanguage?.isDefault || deleteLanguageMutation.isPending}
              data-testid="button-confirm-delete"
            >
              {deleteLanguageMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isTranslationEditorOpen} onOpenChange={setIsTranslationEditorOpen}>
        <DialogContent className="max-w-5xl max-h-[90vh]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <span className="text-2xl">{selectedLanguage?.flag}</span>
              {selectedLanguage?.name} Translations
            </DialogTitle>
            <DialogDescription>
              Edit translations for {selectedLanguage?.nativeName}. English reference values are shown for comparison.
            </DialogDescription>
          </DialogHeader>

          <div className="flex items-center gap-4 mb-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search translations by key or value..."
                value={translationSearch}
                onChange={(e) => setTranslationSearch(e.target.value)}
                className="pl-10"
                data-testid="input-translation-search"
              />
            </div>
            {hasTranslationChanges && (
              <Badge variant="secondary" className="animate-pulse">
                Unsaved changes
              </Badge>
            )}
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setNewKeyPath("custom.");
                setNewKeyValue("");
                setKeyPathError(null);
                setIsAddKeyDialogOpen(true);
              }}
              data-testid="button-add-custom-key"
            >
              <Key className="mr-2 h-4 w-4" />
              Add Custom Key
            </Button>
          </div>

          <Alert className="mb-4">
            <Key className="h-4 w-4" />
            <AlertDescription>
              <strong>Tip:</strong> Use <code className="bg-muted px-1 rounded">custom.</code> prefix for new keys (e.g., <code className="bg-muted px-1 rounded">custom.welcomeMessage</code>). Custom keys can be safely deleted.
            </AlertDescription>
          </Alert>

          <ScrollArea className="h-[500px] border rounded-lg">
            <div className="p-4 space-y-2">
              {Object.entries(groupedTranslations).map(([section, entries]) => (
                <div key={section} className="border rounded-lg overflow-hidden">
                  <button
                    type="button"
                    className="w-full flex items-center justify-between p-3 bg-muted/50 hover-elevate transition-colors"
                    onClick={() => toggleSection(section)}
                    data-testid={`button-section-${section}`}
                  >
                    <span className="font-medium flex items-center gap-2">
                      {expandedSections.has(section) ? (
                        <ChevronDown className="h-4 w-4" />
                      ) : (
                        <ChevronRight className="h-4 w-4" />
                      )}
                      {section}
                    </span>
                    <Badge variant="outline" className="text-xs">
                      {entries.length} keys
                    </Badge>
                  </button>

                  {expandedSections.has(section) && (
                    <div className="divide-y">
                      {entries.map((entry) => (
                        <div key={entry.key} className="p-3 grid grid-cols-12 gap-4 items-start">
                          <div className="col-span-3">
                            <div className="flex items-center gap-2">
                              <p className="text-xs font-mono text-muted-foreground break-all flex-1">
                                {entry.key}
                              </p>
                              {entry.isCustom && (
                                <Badge variant="secondary" className="text-xs shrink-0">
                                  Custom
                                </Badge>
                              )}
                            </div>
                          </div>
                          <div className="col-span-4">
                            <p className="text-xs text-muted-foreground mb-1">English reference:</p>
                            <p className="text-sm bg-muted/30 p-2 rounded text-muted-foreground">
                              {entry.englishValue || <span className="italic">No English value</span>}
                            </p>
                          </div>
                          <div className="col-span-4">
                            <p className="text-xs text-muted-foreground mb-1">Translation:</p>
                            <Input
                              value={entry.value}
                              onChange={(e) => handleTranslationChange(entry.path, e.target.value)}
                              className="text-sm"
                              data-testid={`input-translation-${entry.key.replace(/\./g, "-")}`}
                            />
                          </div>
                          <div className="col-span-1 flex justify-end">
                            {entry.isCustom && (
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <Button
                                    variant="ghost"
                                    size="icon"
                                    className="h-8 w-8 text-destructive hover:text-destructive"
                                    onClick={() => openDeleteKeyDialog(entry.key)}
                                    data-testid={`button-delete-key-${entry.key.replace(/\./g, "-")}`}
                                  >
                                    <Trash2 className="h-4 w-4" />
                                  </Button>
                                </TooltipTrigger>
                                <TooltipContent>
                                  Delete this custom key
                                </TooltipContent>
                              </Tooltip>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}

              {Object.keys(groupedTranslations).length === 0 && (
                <div className="text-center py-12 text-muted-foreground">
                  {translationSearch ? (
                    <p>No translations matching "{translationSearch}"</p>
                  ) : (
                    <p>No translations available</p>
                  )}
                </div>
              )}
            </div>
          </ScrollArea>

          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => {
                setIsTranslationEditorOpen(false);
                setHasTranslationChanges(false);
              }} 
              data-testid="button-cancel-translations"
            >
              Cancel
            </Button>
            <Button
              onClick={handleSaveTranslations}
              disabled={!hasTranslationChanges || updateLanguageMutation.isPending}
              data-testid="button-save-translations"
            >
              {updateLanguageMutation.isPending ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Save className="mr-2 h-4 w-4" />
              )}
              Save Translations
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isAddKeyDialogOpen} onOpenChange={setIsAddKeyDialogOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Key className="h-5 w-5" />
              Add Custom Translation Key
            </DialogTitle>
            <DialogDescription>
              Add a new translation key to {selectedLanguage?.name}. Use the <code className="bg-muted px-1 rounded">custom.</code> prefix for easy identification.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="newKeyPath">Key Path *</Label>
              <Input
                id="newKeyPath"
                placeholder="e.g., custom.welcomeMessage"
                value={newKeyPath}
                onChange={(e) => {
                  setNewKeyPath(e.target.value);
                  setKeyPathError(null);
                }}
                className={keyPathError ? "border-destructive" : ""}
                data-testid="input-new-key-path"
              />
              {keyPathError ? (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {keyPathError}
                </p>
              ) : (
                <p className="text-xs text-muted-foreground">
                  Format: section.subsection.key (letters, numbers, underscores)
                </p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="newKeyValue">Translation Value for {selectedLanguage?.name}</Label>
              <Input
                id="newKeyValue"
                placeholder="Enter the translation..."
                value={newKeyValue}
                onChange={(e) => setNewKeyValue(e.target.value)}
                data-testid="input-new-key-value"
              />
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox
                id="syncToAll"
                checked={syncKeyToAll}
                onCheckedChange={(checked) => setSyncKeyToAll(checked as boolean)}
                data-testid="checkbox-sync-to-all"
              />
              <Label htmlFor="syncToAll" className="text-sm font-normal cursor-pointer">
                Add this key to all languages (with empty value as placeholder)
              </Label>
            </div>
          </div>
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => {
                setIsAddKeyDialogOpen(false);
                setNewKeyPath("");
                setNewKeyValue("");
                setKeyPathError(null);
              }}
              data-testid="button-cancel-add-key"
            >
              Cancel
            </Button>
            <Button
              onClick={handleAddKey}
              disabled={!newKeyPath || addKeyMutation.isPending}
              data-testid="button-confirm-add-key"
            >
              {addKeyMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Add Key
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <Dialog open={isDeleteKeyDialogOpen} onOpenChange={setIsDeleteKeyDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-destructive">
              <AlertTriangle className="h-5 w-5" />
              Delete Translation Key
            </DialogTitle>
            <DialogDescription>
              Are you sure you want to delete the key <code className="bg-muted px-1 rounded font-mono">{keyToDelete}</code>?
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                This action cannot be undone. The translation value will be permanently removed.
              </AlertDescription>
            </Alert>
            <div className="flex items-center space-x-2">
              <Checkbox
                id="deleteFromAll"
                checked={deleteFromAll}
                onCheckedChange={(checked) => setDeleteFromAll(checked as boolean)}
                data-testid="checkbox-delete-from-all"
              />
              <Label htmlFor="deleteFromAll" className="text-sm font-normal cursor-pointer">
                Delete from all languages (recommended)
              </Label>
            </div>
            {!deleteFromAll && (
              <p className="text-xs text-muted-foreground">
                This will only delete the key from {selectedLanguage?.name}. Other languages will keep this key.
              </p>
            )}
          </div>
          <DialogFooter>
            <Button 
              variant="outline" 
              onClick={() => {
                setIsDeleteKeyDialogOpen(false);
                setKeyToDelete(null);
              }}
              data-testid="button-cancel-delete-key"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDeleteKey}
              disabled={deleteKeyMutation.isPending}
              data-testid="button-confirm-delete-key"
            >
              {deleteKeyMutation.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Delete Key
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

server/engines/twilio-openai/routes/twil.content:
'use strict';
/**
 * ============================================================
 * Twilio-OpenAI Webhook Routes
 * 
 * Handles incoming Twilio webhooks for the OpenAI Realtime engine.
 * Completely isolated from the Twilio + ElevenLabs integration.
 * ============================================================
 */

import { Router, Request, Response } from 'express';
import { db } from '../../../db';
import { agents, twilioOpenaiCalls, phoneNumbers, incomingConnections, users, creditTransactions, flows } from '@shared/schema';
import { eq, and, sql } from 'drizzle-orm';
import { nanoid } from 'nanoid';
import { 
  generateTwiML, 
  getStreamWebhookUrl,
  getStatusWebhookUrl,
  getRecordingWebhookUrl,
  TWILIO_OPENAI_CONFIG
} from '../config/twilio-openai-config';
import { OpenAIPoolService } from '../../plivo/services/openai-pool.service';
import { OpenAIAgentFactory } from '../services/openai-agent-factory';
import { TwilioOpenAIAudioBridge } from '../services/audio-bridge.service';
import { getTwilioClient } from '../../../services/twilio-connector';
import { logger } from '../../../utils/logger';
import { webhookDeliveryService } from '../../../services/webhook-delivery';
import { validateTwilioWebhook } from '../../../middleware/webhookValidation';
import type { TwilioWebhookParams } from '../types';

const router = Router();

// Apply Twilio webhook signature validation to all voice routes
router.use('/voice', validateTwilioWebhook);

/**
 * Normalize phone number for database lookup.
 * Database stores phone numbers with + prefix (e.g., +14159038188).
 * Twilio may send with or without + prefix.
 */
function normalizePhoneForLookup(phone: string): string {
  // Remove spaces, dashes, parentheses but KEEP the + if present
  let cleaned = phone.replace(/[\s\-\(\)]/g, '');
  // Ensure + prefix for E.164 format matching
  if (!cleaned.startsWith('+')) {
    cleaned = '+' + cleaned;
  }
  return cleaned;
}

/**
 * Normalize phone number for storage (preserves + prefix).
 */
function normalizePhoneForStorage(phone: string): string {
  let cleaned = phone.replace(/[\s\-\(\)]/g, '');
  if (!cleaned.startsWith('+')) {
    cleaned = '+' + cleaned;
  }
  return cleaned;
}

router.post('/voice/incoming', async (req: Request, res: Response) => {
  const params = req.body as TwilioWebhookParams;
  const { CallSid, From, To, Direction } = params;

  logger.info(`Incoming call: ${CallSid}`, undefined, 'TwilioOpenAI');
  logger.info(`From: ${From}, To: ${To}, Direction: ${Direction}`, undefined, 'TwilioOpenAI');

  // Trigger inbound_call.received early - we have the call but haven't processed it yet
  // This fires before any validation to capture ALL incoming calls
  let phoneRecordForWebhook: any = null;
  let agentForWebhook: any = null;

  try {
    const normalizedTo = normalizePhoneForLookup(To);

    const [phoneRecord] = await db
      .select()
      .from(phoneNumbers)
      .where(eq(phoneNumbers.phoneNumber, normalizedTo))
      .limit(1);

    phoneRecordForWebhook = phoneRecord;

    // Trigger inbound_call.received as soon as we have the phone record
    if (phoneRecord?.userId) {
      try {
        await webhookDeliveryService.triggerEvent(phoneRecord.userId, 'inbound_call.received', {
          callId: null,
          callSid: CallSid,
          direction: 'inbound',
          status: 'received',
          fromNumber: normalizePhoneForStorage(From),
          toNumber: normalizedTo,
          agentId: null,
          phoneNumberId: phoneRecord.id,
        });
        logger.info(`Triggered inbound_call.received webhook for incoming call ${CallSid}`, undefined, 'TwilioOpenAI');
      } catch (webhookError: any) {
        logger.error(`Failed to trigger inbound_call.received webhook: ${webhookError.message}`, undefined, 'TwilioOpenAI');
      }
    }

    if (!phoneRecord) {
      logger.info(`Phone number not found: ${normalizedTo}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, this number is not configured for AI calls.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    const [connection] = await db
      .select()
      .from(incomingConnections)
      .where(eq(incomingConnections.phoneNumberId, phoneRecord.id))
      .limit(1);

    if (!connection) {
      logger.info(`No agent connection for: ${normalizedTo}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, no AI agent is available for this number.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    const [agent] = await db
      .select()
      .from(agents)
      .where(eq(agents.id, connection.agentId))
      .limit(1);

    if (!agent) {
      logger.info(`Agent not found: ${connection.agentId}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, the AI agent is not available.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    // Check user has credits before connecting
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.id, phoneRecord.userId || ''))
      .limit(1);

    if (!user || user.credits < 1) {
      logger.info(`Insufficient credits for user: ${phoneRecord.userId}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, there are no credits available for this call. Please top up your account.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    const credential = await OpenAIPoolService.reserveSlot();
    if (!credential) {
      logger.info('No OpenAI capacity available', undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, all AI agents are busy. Please try again later.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    const callId = nanoid();

    // Store agent configuration in metadata for the stream handler to use
    // Session will be created when the WebSocket stream connects (on 'start' event)
    // This prevents the 5-8 second delay where audio was lost before stream connected
    const callMetadata: Record<string, unknown> = {
      incomingCall: true,
      agentId: agent.id,
      userId: phoneRecord.userId,
      knowledgeBaseIds: agent.knowledgeBaseIds || [],
      transferEnabled: agent.transferEnabled,
      transferPhoneNumber: agent.transferPhoneNumber,
      endConversationEnabled: agent.endConversationEnabled,
      detectLanguageEnabled: agent.detectLanguageEnabled,
      appointmentBookingEnabled: agent.appointmentBookingEnabled,
      systemPrompt: agent.systemPrompt,
      firstMessage: agent.firstMessage,
      temperature: agent.temperature,
      language: agent.language || 'en',
    };

    // For flow agents, load and store compiled flow data including tools with metadata
    if (agent.type === 'flow' && agent.flowId) {
      logger.info(`Loading flow data for incoming call to flow agent ${agent.id}`, undefined, 'TwilioOpenAI');
      const [flow] = await db
        .select()
        .from(flows)
        .where(eq(flows.id, agent.flowId))
        .limit(1);

      if (flow && flow.compiledSystemPrompt && flow.compiledTools) {
        callMetadata.isFlowAgent = true;
        callMetadata.flowId = flow.id;
        callMetadata.systemPrompt = flow.compiledSystemPrompt;
        callMetadata.firstMessage = flow.compiledFirstMessage || agent.firstMessage;
        // Store compiled tools with their _metadata intact for rehydration in stream handler
        callMetadata.compiledTools = flow.compiledTools;
        logger.info(`Stored ${(flow.compiledTools as any[]).length} compiled flow tools for incoming call`, undefined, 'TwilioOpenAI');
      }
    }

    await db.insert(twilioOpenaiCalls).values({
      id: callId,
      userId: phoneRecord.userId,
      agentId: agent.id,
      twilioPhoneNumberId: phoneRecord.id,
      openaiCredentialId: credential.id,
      twilioCallSid: CallSid,
      fromNumber: normalizePhoneForStorage(From),
      toNumber: normalizedTo,
      openaiVoice: (agent.openaiVoice as any) || TWILIO_OPENAI_CONFIG.defaultVoice,
      openaiModel: TWILIO_OPENAI_CONFIG.openaiRealtimeModel,
      status: 'in-progress',
      callDirection: 'inbound',
      startedAt: new Date(),
      answeredAt: new Date(),
      metadata: callMetadata,
    });

    // Start call recording if enabled
    if (TWILIO_OPENAI_CONFIG.recordCalls) {
      try {
        const twilioClient = await getTwilioClient();
        const recordingCallback = getRecordingWebhookUrl();
        await twilioClient.calls(CallSid).recordings.create({
          recordingStatusCallback: recordingCallback,
          recordingStatusCallbackEvent: ['completed'],
          recordingChannels: 'dual',
        });
        logger.info(`Recording started for call ${callId}`, undefined, 'TwilioOpenAI');
      } catch (recordError: any) {
        logger.error('Failed to start recording', recordError, 'TwilioOpenAI');
      }
    }

    // NOTE: Session creation is now deferred to the stream handler
    // This ensures the Twilio WebSocket is connected before OpenAI starts sending audio
    logger.info(`Incoming call ${callId} prepared, session will be created when stream connects`, undefined, 'TwilioOpenAI');

    // Trigger call.started webhook event for incoming calls
    try {
      await webhookDeliveryService.triggerEvent(phoneRecord.userId!, 'call.started', {
        call: {
          id: callId,
          callSid: CallSid,
          direction: 'inbound',
          status: 'in-progress',
          startedAt: new Date().toISOString(),
          fromNumber: normalizePhoneForStorage(From),
          toNumber: normalizedTo,
        },
        agent: {
          id: agent.id,
          name: agent.name || null,
        },
        campaign: null,
      });
      logger.info(`Triggered call.started webhook for incoming call ${callId}`, undefined, 'TwilioOpenAI');
    } catch (webhookError: any) {
      logger.error(`Failed to trigger call.started webhook: ${webhookError.message}`, undefined, 'TwilioOpenAI');
    }

    // Trigger inbound_call.answered webhook - the call has been answered by the AI agent
    try {
      await webhookDeliveryService.triggerEvent(phoneRecord.userId!, 'inbound_call.answered', {
        callId: callId,
        callSid: CallSid,
        direction: 'inbound',
        status: 'in-progress',
        fromNumber: normalizePhoneForStorage(From),
        toNumber: normalizedTo,
        agentId: agent.id,
        phoneNumberId: phoneRecord.id,
      });
      logger.info(`Triggered inbound_call.answered webhook for call ${callId}`, undefined, 'TwilioOpenAI');
    } catch (webhookError: any) {
      logger.error(`Failed to trigger inbound_call.answered webhook: ${webhookError.message}`, undefined, 'TwilioOpenAI');
    }

    const streamUrl = getStreamWebhookUrl(CallSid);
    const twiml = generateTwiML({
      streamUrl,
      customParameters: {
        callId,
        agentId: agent.id,
      },
    });

    logger.info(`Call ${callId} connected to stream: ${streamUrl}`, undefined, 'TwilioOpenAI');

    res.type('text/xml');
    res.send(twiml);

  } catch (error: any) {
    logger.error('Error handling incoming call', error, 'TwilioOpenAI');
    res.type('text/xml');
    res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Sorry, an error occurred. Please try again.</Say>
  <Hangup/>
</Response>`);
  }
});

router.post('/voice/answer', async (req: Request, res: Response) => {
  const params = req.body as TwilioWebhookParams;
  const { CallSid, From, To } = params;

  logger.info(`Outbound call answered: ${CallSid}`, undefined, 'TwilioOpenAI');

  try {
    const [callRecord] = await db
      .select()
      .from(twilioOpenaiCalls)
      .where(eq(twilioOpenaiCalls.twilioCallSid, CallSid))
      .limit(1);

    if (!callRecord) {
      logger.info(`Call record not found for: ${CallSid}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Call setup error. Goodbye.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    await db
      .update(twilioOpenaiCalls)
      .set({ 
        status: 'in-progress',
        answeredAt: new Date(),
      })
      .where(eq(twilioOpenaiCalls.id, callRecord.id));

    const session = TwilioOpenAIAudioBridge.getSession(CallSid);
    if (!session) {
      logger.info(`No session found for: ${CallSid}`, undefined, 'TwilioOpenAI');
      res.type('text/xml');
      res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>Session not found. Goodbye.</Say>
  <Hangup/>
</Response>`);
      return;
    }

    // Start call recording for outbound calls (after session validation)
    if (TWILIO_OPENAI_CONFIG.recordCalls) {
      try {
        const twilioClient = await getTwilioClient();
        const recordingCallback = getRecordingWebhookUrl();
        await twilioClient.calls(CallSid).recordings.create({
          recordingStatusCallback: recordingCallback,
          recordingStatusCallbackEvent: ['completed'],
          recordingChannels: 'dual',
        });
        logger.info(`Recording started for outbound call ${callRecord.id}`, undefined, 'TwilioOpenAI');
      } catch (recordError: any) {
        logger.error('Failed to start recording for outbound call', recordError, 'TwilioOpenAI');
      }
    }

    const streamUrl = getStreamWebhookUrl(CallSid);
    const twiml = generateTwiML({
      streamUrl,
      customParameters: {
        callId: callRecord.id,
        agentId: callRecord.agentId || '',
      },
    });

    res.type('text/xml');
    res.send(twiml);

  } catch (error: any) {
    logger.error('Error handling answer', error, 'TwilioOpenAI');
    res.type('text/xml');
    res.send(`<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say>An error occurred.</Say>
  <Hangup/>
</Response>`);
  }
});

router.post('/voice/status', async (req: Request, res: Response) => {
  const params = req.body as TwilioWebhookParams;
  const { CallSid, CallStatus, CallDuration, RecordingUrl, RecordingDuration } = params;

  logger.info(`Call status update: ${CallSid} -> ${CallStatus}`, undefined, 'TwilioOpenAI');

  try {
    const [callRecord] = await db
      .select()
      .from(twilioOpenaiCalls)
      .where(eq(twilioOpenaiCalls.twilioCallSid, CallSid))
      .limit(1);

    if (!callRecord) {
      logger.info(`Call record not found for status update: ${CallSid}`, undefined, 'TwilioOpenAI');
      res.sendStatus(200);
      return;
    }

    // Trigger webhook events for specific call statuses
    if (callRecord.userId) {
      try {
        const webhookPayload = {
          callId: callRecord.id,
          callSid: CallSid,
          direction: callRecord.callDirection || 'outbound',
          status: CallStatus,
          fromNumber: callRecord.fromNumber,
          toNumber: callRecord.toNumber,
          contactId: callRecord.contactId,
          campaignId: callRecord.campaignId,
        };

        if (CallStatus === 'ringing') {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.ringing', webhookPayload, callRecord.campaignId);
          logger.info(`Triggered call.ringing webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        } else if (CallStatus === 'in-progress') {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.answered', webhookPayload, callRecord.campaignId);
          logger.info(`Triggered call.answered webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        } else if (CallStatus === 'no-answer') {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.no_answer', webhookPayload, callRecord.campaignId);
          logger.info(`Triggered call.no_answer webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        } else if (CallStatus === 'busy') {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.busy', webhookPayload, callRecord.campaignId);
          logger.info(`Triggered call.busy webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        }

        // Check for voicemail detection from Twilio AMD (Answering Machine Detection)
        const AnsweredBy = (params as any).AnsweredBy;
        if (AnsweredBy === 'machine_start' || AnsweredBy === 'machine_end_beep' || AnsweredBy === 'machine_end_silence') {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.voicemail', webhookPayload, callRecord.campaignId);
          logger.info(`Triggered call.voicemail webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        }
      } catch (webhookError: any) {
        logger.error(`Failed to trigger status webhook for call ${callRecord.id}: ${webhookError.message}`, webhookError, 'TwilioOpenAI');
      }
    }

    const updates: any = {
      status: CallStatus as any,
    };

    // Capture recording data if available from status callback (add .mp3 extension for direct access)
    if (RecordingUrl) {
      updates.recordingUrl = RecordingUrl.endsWith('.mp3') ? RecordingUrl : `${RecordingUrl}.mp3`;
    }
    if (RecordingDuration) {
      updates.recordingDuration = parseInt(RecordingDuration, 10);
    }

    if (CallStatus === 'completed' || CallStatus === 'busy' || 
        CallStatus === 'failed' || CallStatus === 'no-answer' || CallStatus === 'canceled') {
      updates.endedAt = new Date();

      const duration = CallDuration ? parseInt(CallDuration, 10) : 0;
      if (duration > 0) {
        updates.duration = duration;
      }

      const sessionResult = await TwilioOpenAIAudioBridge.endSession(CallSid);
      if (sessionResult.transcript) {
        updates.transcript = sessionResult.transcript;
      }

      if (callRecord.openaiCredentialId) {
        await OpenAIPoolService.releaseSlot(callRecord.openaiCredentialId);
      }

      // Note: Credit deduction is handled in the stream close handler (twilio-openai-stream.ts)
      // to prevent double-charging. The stream handler has more accurate duration tracking.

      // Trigger call.completed webhook event
      if (callRecord.userId && (CallStatus === 'completed' || CallStatus === 'failed' || CallStatus === 'busy' || CallStatus === 'no-answer')) {
        try {
          await webhookDeliveryService.triggerEvent(callRecord.userId, 'call.completed', {
            call: {
              id: callRecord.id,
              callSid: CallSid,
              direction: callRecord.callDirection || 'outbound',
              status: CallStatus,
              duration: duration,
              startedAt: callRecord.startedAt?.toISOString() || null,
              endedAt: new Date().toISOString(),
              fromNumber: callRecord.fromNumber || null,
              toNumber: callRecord.toNumber || null,
              transcript: updates.transcript || null,
              recordingUrl: updates.recordingUrl || callRecord.recordingUrl || null,
            },
            agent: callRecord.agentId ? { id: callRecord.agentId } : null,
            campaign: callRecord.campaignId ? { id: callRecord.campaignId } : null,
          });
          logger.info(`Triggered call.completed webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
        } catch (webhookError: any) {
          logger.error(`Failed to trigger call.completed webhook: ${webhookError.message}`, undefined, 'TwilioOpenAI');
        }
      }

      // Trigger inbound_call.completed or inbound_call.missed for inbound calls
      if (callRecord.userId && callRecord.callDirection === 'inbound') {
        try {
          const inboundPayload = {
            callId: callRecord.id,
            callSid: CallSid,
            direction: 'inbound',
            status: CallStatus,
            fromNumber: callRecord.fromNumber,
            toNumber: callRecord.toNumber,
            agentId: callRecord.agentId,
            phoneNumberId: callRecord.twilioPhoneNumberId,
            duration: duration,
          };

          if (CallStatus === 'completed') {
            await webhookDeliveryService.triggerEvent(callRecord.userId, 'inbound_call.completed', inboundPayload);
            logger.info(`Triggered inbound_call.completed webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
          } else if (CallStatus === 'no-answer' || CallStatus === 'canceled') {
            await webhookDeliveryService.triggerEvent(callRecord.userId, 'inbound_call.missed', inboundPayload);
            logger.info(`Triggered inbound_call.missed webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
          }
        } catch (webhookError: any) {
          logger.error(`Failed to trigger inbound call webhook: ${webhookError.message}`, undefined, 'TwilioOpenAI');
        }
      }

      // Trigger flow.completed or flow.failed for flow-based agents
      if (callRecord.userId && callRecord.agentId) {
        try {
          const [agent] = await db
            .select()
            .from(agents)
            .where(eq(agents.id, callRecord.agentId))
            .limit(1);

          if (agent && agent.type === 'flow' && agent.flowId) {
            const [flow] = await db
              .select()
              .from(flows)
              .where(eq(flows.id, agent.flowId))
              .limit(1);

            const flowPayload = {
              flowId: agent.flowId,
              flowName: flow?.name || 'Unknown Flow',
              callId: callRecord.id,
              callSid: CallSid,
              agentId: agent.id,
              userId: callRecord.userId,
              duration: duration,
            };

            if (CallStatus === 'completed') {
              await webhookDeliveryService.triggerEvent(callRecord.userId, 'flow.completed', {
                ...flowPayload,
                nodesExecuted: flow?.nodes ? (flow.nodes as any[]).length : 0,
              });
              logger.info(`Triggered flow.completed webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
            } else if (CallStatus === 'failed' || CallStatus === 'busy' || CallStatus === 'no-answer') {
              await webhookDeliveryService.triggerEvent(callRecord.userId, 'flow.failed', {
                ...flowPayload,
                error: {
                  code: 'CALL_ENDED',
                  message: `Call ended with status: ${CallStatus}`,
                },
              });
              logger.info(`Triggered flow.failed webhook for call ${callRecord.id}`, undefined, 'TwilioOpenAI');
            }
          }
        } catch (flowWebhookError: any) {
          logger.error(`Failed to trigger flow webhook: ${flowWebhookError.message}`, undefined, 'TwilioOpenAI');
        }
      }

      // CRM Lead Creation for outbound calls (campaigns) - inbound calls are handled in stream handler
      // Only process completed outbound calls to avoid duplicate processing
      if (callRecord.userId && CallStatus === 'completed' && callRecord.callDirection === 'outbound') {
        try {
          const { CRMLeadProcessor } = await import('../../crm/lead-processor.service');
          const result = await CRMLeadProcessor.processTwilioOpenAICall(callRecord.id);
          if (result?.leadId) {
            logger.info(`CRM lead created from outbound call: ${result.leadId} (${result.qualification.category})`, undefined, 'TwilioOpenAI');
          } else if (result) {
            logger.info(`Outbound call ${callRecord.id} did not qualify for CRM lead`, undefined, 'TwilioOpenAI');
          }
        } catch (crmError: any) {
          logger.error(`Failed to create CRM lead from outbound call: ${crmError.message}`, crmError, 'TwilioOpenAI');
        }
      }
    }

    await db
      .update(twilioOpenaiCalls)
      .set(updates)
      .where(eq(twilioOpenaiCalls.id, callRecord.id));

    res.sendStatus(200);

  } catch (error: any) {
    logger.error('Error handling status', error, 'TwilioOpenAI');
    res.sendStatus(200);
  }
});

/**
 * Recording status callback - called when recording completes
 */
router.post('/voice/recording', async (req: Request, res: Response) => {
  const { CallSid, RecordingUrl, RecordingSid, RecordingDuration, RecordingStatus } = req.body;

  logger.info(`Recording status: ${RecordingSid} for call ${CallSid} -> ${RecordingStatus}`, undefined, 'TwilioOpenAI');

  try {
    if (RecordingStatus !== 'completed') {
      res.sendStatus(200);
      return;
    }

    const [callRecord] = await db
      .select()
      .from(twilioOpenaiCalls)
      .where(eq(twilioOpenaiCalls.twilioCallSid, CallSid))
      .limit(1);

    if (!callRecord) {
      logger.info(`Call record not found for recording: ${CallSid}`, undefined, 'TwilioOpenAI');
      res.sendStatus(200);
      return;
    }

    // Save recording URL (append .mp3 for direct audio access)
    const recordingUrlWithFormat = RecordingUrl ? `${RecordingUrl}.mp3` : null;

    await db
      .update(twilioOpenaiCalls)
      .set({
        recordingUrl: recordingUrlWithFormat,
        recordingDuration: RecordingDuration ? parseInt(RecordingDuration, 10) : null,
      })
      .where(eq(twilioOpenaiCalls.id, callRecord.id));

    logger.info(`Recording saved for call ${callRecord.id}: ${recordingUrlWithFormat}`, undefined, 'TwilioOpenAI');

    res.sendStatus(200);

  } catch (error: any) {
    logger.error('Error handling recording status', error, 'TwilioOpenAI');
    res.sendStatus(200);
  }
});

export default router;

