        if (!price) price = isYearly ? plan.yearlyPrice : plan.monthlyPrice;
        break;
      case 'stripe':
      default:
        price = isYearly ? plan.yearlyPrice : plan.monthlyPrice;
        break;
    }

    return price ? parseFloat(price).toLocaleString() : '0';
  };

