                  <FormItem>
                    <FormLabel>Model Tier</FormLabel>
                    <Select value={field.value} onValueChange={field.onChange}>
                      <FormControl>
                        <SelectTrigger data-testid="select-tier">
                          <SelectValue />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="free">Free</SelectItem>
                        <SelectItem value="pro">Pro</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <div className="grid grid-cols-2 gap-4">
                <FormField
                  control={addForm.control}
                  name="maxConcurrency"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Max Concurrency</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="number"
                          data-testid="input-max-concurrency"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={addForm.control}
                  name="maxAgentsThreshold"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Max Agents Threshold</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="number"
                          data-testid="input-max-agents"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
              <DialogFooter>
                <Button type="button" variant="outline" onClick={() => setAddDialogOpen(false)}>
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={addCredential.isPending}
                  data-testid="button-save-credential"
                >
                  {addCredential.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  Add Key
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      <Dialog open={editDialogOpen} onOpenChange={setEditDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Edit Credential</DialogTitle>
            <DialogDescription>
              Update the OpenAI credential settings.
            </DialogDescription>
          </DialogHeader>
          <Form {...editForm}>
            <form onSubmit={editForm.handleSubmit((data) => {
              if (selectedCredential) {
                updateCredential.mutate({ id: selectedCredential.id, updates: data });
              }
            })} className="space-y-4 py-4">
              <FormField
                control={editForm.control}
                name="name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Name</FormLabel>
                    <FormControl>
                      <Input
                        {...field}
                        data-testid="input-edit-name"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={editForm.control}
                name="modelTier"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Model Tier</FormLabel>
                    <Select value={field.value} onValueChange={field.onChange}>
                      <FormControl>
                        <SelectTrigger data-testid="select-edit-tier">
                          <SelectValue />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="free">Free</SelectItem>
                        <SelectItem value="pro">Pro</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <div className="grid grid-cols-2 gap-4">
                <FormField
                  control={editForm.control}
                  name="maxConcurrency"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Max Concurrency</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="number"
                          data-testid="input-edit-max-concurrency"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={editForm.control}
                  name="maxAgentsThreshold"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Max Agents Threshold</FormLabel>
                      <FormControl>
                        <Input
                          {...field}
                          type="number"
                          data-testid="input-edit-max-agents"
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
              <DialogFooter>
                <Button type="button" variant="outline" onClick={() => setEditDialogOpen(false)}>
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={updateCredential.isPending}
                  data-testid="button-update-credential"
                >
                  {updateCredential.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  Update
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Credential</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{selectedCredential?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleteCredential.isPending}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (selectedCredential) {
                  deleteCredential.mutate(selectedCredential.id);
                }
              }}
              disabled={deleteCredential.isPending}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              data-testid="button-confirm-delete"
            >
              {deleteCredential.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Card>
  );
}

server/services/oauth.ts.content:
'use strict';
import crypto from 'crypto';
import { getOAuthProvider, isOAuthProvider, type OAuthProviderConfig } from './oauth-providers';

const OAUTH_STATE_SECRET = process.env.LOOP9_WEBHOOK_SECRET || 'loop9-default-secret';
const STATE_EXPIRY_MS = 10 * 60 * 1000;

export interface UserOAuthCredentials {
  clientId: string;
  clientSecret: string;
}

interface OAuthState {
  integrationId: string;
  userId: string;
  slug: string;
  timestamp: number;
}

function getBaseUrl(): string {
  if (process.env.REPLIT_DEV_DOMAIN) {
    return `https://${process.env.REPLIT_DEV_DOMAIN}`;
  }
  if (process.env.REPL_SLUG && process.env.REPL_OWNER) {
    return `https://${process.env.REPL_SLUG}.${process.env.REPL_OWNER}.repl.co`;
  }
  return process.env.APP_BASE_URL || 'http://localhost:5000';
}

export const oauthService = {
  getRedirectUri: (): string => {
    return `${getBaseUrl()}/api/integrations/oauth/callback`;
  },

  generateState: (integrationId: string, userId: string, slug: string): string => {
    const stateData: OAuthState = {
      integrationId,
      userId,
      slug,
      timestamp: Date.now(),
    };
    const payload = JSON.stringify(stateData);
    const encoded = Buffer.from(payload).toString('base64url');
    const signature = crypto
      .createHmac('sha256', OAUTH_STATE_SECRET)
      .update(payload)
      .digest('base64url');
    return `${encoded}.${signature}`;
  },

  verifyState: (state: string): OAuthState | null => {
    try {
      const [encoded, signature] = state.split('.');
      if (!encoded || !signature) return null;

      const payload = Buffer.from(encoded, 'base64url').toString('utf-8');
      const expectedSignature = crypto
        .createHmac('sha256', OAUTH_STATE_SECRET)
        .update(payload)
        .digest('base64url');

      if (signature !== expectedSignature) {
        console.error('[OAuth] State signature mismatch');
        return null;
      }

      const data: OAuthState = JSON.parse(payload);

      if (Date.now() - data.timestamp > STATE_EXPIRY_MS) {
        console.error('[OAuth] State expired');
        return null;
      }

      return data;
    } catch (err) {
      console.error('[OAuth] State verification error:', err);
      return null;
    }
  },

  buildAuthorizationUrl: (slug: string, integrationId: string, userId: string, credentials: UserOAuthCredentials): string | null => {
    const provider = getOAuthProvider(slug);
    if (!provider || provider.authType !== 'oauth2') return null;

    const state = oauthService.generateState(integrationId, userId, slug);
    const redirectUri = oauthService.getRedirectUri();

    const params = new URLSearchParams({
      client_id: credentials.clientId,
      redirect_uri: redirectUri,
      response_type: 'code',
      state,
    });

    if (provider.scopes.length > 0) {
      params.set('scope', provider.scopes.join(' '));
    }

    if (provider.additionalAuthParams) {
      for (const [key, value] of Object.entries(provider.additionalAuthParams)) {
        params.set(key, value);
      }
    }

    return `${provider.authUrl}?${params.toString()}`;
  },

  exchangeCodeForTokens: async (
    slug: string,
    code: string,
    credentials: UserOAuthCredentials,
  ): Promise<{
    accessToken: string;
    refreshToken?: string;
    expiresIn?: number;
    tokenType?: string;
    rawResponse: Record<string, any>;
  } | null> => {
    const provider = getOAuthProvider(slug);
    if (!provider) return null;

    const redirectUri = oauthService.getRedirectUri();

    const body = new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      redirect_uri: redirectUri,
      client_id: credentials.clientId,
      client_secret: credentials.clientSecret,
    });

    try {
      const response = await fetch(provider.tokenUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error(`[OAuth] Token exchange failed for ${slug}: ${response.status} ${errorText}`);
        return null;
      }

      const data = await response.json();

      return {
        accessToken: data.access_token,
        refreshToken: data.refresh_token,
        expiresIn: data.expires_in,
        tokenType: data.token_type,
        rawResponse: data,
      };
    } catch (err) {
      console.error(`[OAuth] Token exchange error for ${slug}:`, err);
      return null;
    }
  },

  refreshAccessToken: async (
    slug: string,
    refreshToken: string,
    credentials: UserOAuthCredentials,
  ): Promise<{
    accessToken: string;
    refreshToken?: string;
    expiresIn?: number;
  } | null> => {
    const provider = getOAuthProvider(slug);
    if (!provider) return null;

    const body = new URLSearchParams({
      grant_type: 'refresh_token',
      refresh_token: refreshToken,
      client_id: credentials.clientId,
      client_secret: credentials.clientSecret,
    });

    try {
      const response = await fetch(provider.tokenUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });

      if (!response.ok) {
        console.error(`[OAuth] Token refresh failed for ${slug}: ${response.status}`);
        return null;
      }

      const data = await response.json();

      return {
        accessToken: data.access_token,
        refreshToken: data.refresh_token || refreshToken,
        expiresIn: data.expires_in,
      };
    } catch (err) {
      console.error(`[OAuth] Token refresh error for ${slug}:`, err);
      return null;
    }
  },

  fetchAccountInfo: async (
    slug: string,
    accessToken: string,
  ): Promise<{ accountId: string; accountName: string; accountEmail?: string } | null> => {
    const provider = getOAuthProvider(slug);
    if (!provider || !provider.accountInfoUrl || !provider.accountInfoHeaders || !provider.parseAccountInfo) {
      return null;
    }

    try {
      const headers = provider.accountInfoHeaders(accessToken);

      let response: Response;
      if (slug === 'monday-com') {
        response = await fetch(provider.accountInfoUrl, {
          method: 'POST',
          headers,
          body: JSON.stringify({ query: '{ me { id name email } }' }),
        });
      } else if (slug === 'hubspot') {
        response = await fetch(`${provider.accountInfoUrl}${accessToken}`, {
          headers: { 'Content-Type': 'application/json' },
        });
      } else {
        response = await fetch(provider.accountInfoUrl, { headers });
      }

      if (!response.ok) {
        console.error(`[OAuth] Account info fetch failed for ${slug}: ${response.status}`);
        return null;
      }

      const data = await response.json();
      return provider.parseAccountInfo(data);
    } catch (err) {
      console.error(`[OAuth] Account info error for ${slug}:`, err);
      return null;
    }
  },

  encryptToken: (token: string): string => {
    const key = crypto.scryptSync(OAUTH_STATE_SECRET, 'loop9-salt', 32);
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);
    let encrypted = cipher.update(token, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return `${iv.toString('hex')}:${encrypted}`;
  },

  decryptToken: (encryptedToken: string): string => {
    try {
      const [ivHex, encrypted] = encryptedToken.split(':');
      const key = crypto.scryptSync(OAUTH_STATE_SECRET, 'loop9-salt', 32);
      const iv = Buffer.from(ivHex, 'hex');
      const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return decrypted;
    } catch {
      return '';
    }
  },
};

plugins/sip-engine/routes/sip-trunk.rout.content:
'use strict';

import type { Express, Request, Response, RequestHandler } from 'express';
import { z } from 'zod';
import { ElevenLabsSipService } from '../services/elevenlabs-sip.service';
import { SIP_PROVIDERS } from '../config/sip-config';

const createTrunkSchema = z.object({
  name: z.string().min(1).max(100),
  provider: z.string().default('generic'),
  sipHost: z.string().min(1),
  sipPort: z.number().int().min(1).max(65535).optional(),
  transport: z.enum(['udp', 'tcp', 'tls']).optional(),
  mediaEncryption: z.enum(['require', 'prefer', 'none']).optional(),
  username: z.string().optional(),
  password: z.string().optional(),
  realm: z.string().optional(),
  codecsAllowed: z.array(z.string()).optional(),
  inboundTransport: z.enum(['udp', 'tcp', 'tls']).optional(),
  inboundPort: z.number().int().min(1).max(65535).optional(),
});

const updateTrunkSchema = createTrunkSchema.partial();

export function setupSipTrunkRoutes(
  app: Express,
  sessionAuth: RequestHandler
): void {
  app.get('/api/sip/providers', sessionAuth, async (req: Request, res: Response) => {
    try {
      const providers = Object.entries(SIP_PROVIDERS).map(([key, config]) => ({
        id: key,
        name: config.displayName,
        description: config.description,
        defaults: {
          port: config.defaultPort,
          transport: config.defaultTransport,
          mediaEncryption: config.defaultMediaEncryption,
          requiresRegistration: config.requiresRegistration,
        },
      }));

      res.json(providers);
    } catch (error: any) {
      console.error('[SIP Routes] Get providers error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/sip/trunks', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const trunks = await ElevenLabsSipService.getUserTrunks(userId);
      res.json(trunks);
    } catch (error: any) {
      console.error('[SIP Routes] Get trunks error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.get('/api/sip/trunks/:trunkId', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const trunk = await ElevenLabsSipService.getTrunkById(req.params.trunkId);

      if (!trunk) {
        return res.status(404).json({ error: 'Trunk not found' });
      }

      if (trunk.userId !== userId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      res.json(trunk);
    } catch (error: any) {
      console.error('[SIP Routes] Get trunk error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post('/api/sip/trunks', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const validation = createTrunkSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: 'Validation failed', details: validation.error.errors });
      }

      const trunk = await ElevenLabsSipService.createSipTrunk({
        userId,
        ...validation.data,
      });

      res.status(201).json(trunk);
    } catch (error: any) {
      console.error('[SIP Routes] Create trunk error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.patch('/api/sip/trunks/:trunkId', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const existing = await ElevenLabsSipService.getTrunkById(req.params.trunkId);

      if (!existing) {
        return res.status(404).json({ error: 'Trunk not found' });
      }

      if (existing.userId !== userId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      const validation = updateTrunkSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: 'Validation failed', details: validation.error.errors });
      }

      const trunk = await ElevenLabsSipService.updateSipTrunk(req.params.trunkId, validation.data);

      res.json(trunk);
    } catch (error: any) {
      console.error('[SIP Routes] Update trunk error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.delete('/api/sip/trunks/:trunkId', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const existing = await ElevenLabsSipService.getTrunkById(req.params.trunkId);

      if (!existing) {
        return res.status(404).json({ error: 'Trunk not found' });
      }

      if (existing.userId !== userId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      await ElevenLabsSipService.deleteSipTrunk(req.params.trunkId);

      res.json({ success: true });
    } catch (error: any) {
      console.error('[SIP Routes] Delete trunk error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post('/api/sip/trunks/:trunkId/health-check', sessionAuth, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).user?.id;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }

      const existing = await ElevenLabsSipService.getTrunkById(req.params.trunkId);

      if (!existing) {
        return res.status(404).json({ error: 'Trunk not found' });
      }

      if (existing.userId !== userId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      const result = await ElevenLabsSipService.checkTrunkHealth(req.params.trunkId);

      res.json(result);
    } catch (error: any) {
      console.error('[SIP Routes] Health check error:', error);
      res.status(500).json({ error: error.message });
    }
  });

  console.log('[SIP Engine] SIP trunk routes registered');
}

