/**
 * Team Member Authentication Utilities
 * Handles JWT-based authentication for team members
 */

const STORAGE_KEYS = {
  TEAM_TOKEN: 'team_member_token',
  TEAM_MEMBER_DATA: 'team_member_data',
  TEAM_DATA: 'team_data',
  TEAM_PERMISSIONS: 'team_permissions',
} as const;

export interface TeamMemberData {
  id: string;
  email: string;
  name?: string;
  firstName?: string;
  lastName?: string;
  role?: {
    id: string;
    name: string;
  };
}

export interface TeamData {
  id: string;
  name: string;
  type: 'user' | 'admin';
  parentUserId?: string;
}

function safeGetItem(key: string): string | null {
  try {
    if (typeof window === 'undefined' || !window.localStorage) {
      return null;
    }
    return localStorage.getItem(key);
  } catch (error) {
    console.error(`[TeamAuth] Failed to get item "${key}":`, error);
    return null;
  }
}

function safeSetItem(key: string, value: string): boolean {
  try {
    if (typeof window === 'undefined' || !window.localStorage) {
      return false;
    }
    localStorage.setItem(key, value);
    return true;
  } catch (error) {
    console.error(`[TeamAuth] Failed to set item "${key}":`, error);
    return false;
  }
}

function safeRemoveItem(key: string): boolean {
  try {
    if (typeof window === 'undefined' || !window.localStorage) {
      return false;
    }
    localStorage.removeItem(key);
    return true;
  } catch (error) {
    console.error(`[TeamAuth] Failed to remove item "${key}":`, error);
    return false;
  }
}

export const TeamAuth = {
  getToken(): string | null {
    return safeGetItem(STORAGE_KEYS.TEAM_TOKEN);
  },

  setToken(token: string): boolean {
    return safeSetItem(STORAGE_KEYS.TEAM_TOKEN, token);
  },

  removeToken(): boolean {
    return safeRemoveItem(STORAGE_KEYS.TEAM_TOKEN);
  },

  isAuthenticated(): boolean {
    const token = this.getToken();
    return token !== null && token.length > 0;
  },

  getMember(): TeamMemberData | null {
    const data = safeGetItem(STORAGE_KEYS.TEAM_MEMBER_DATA);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch {
      return null;
    }
  },

  setMember(member: TeamMemberData): boolean {
    try {
      return safeSetItem(STORAGE_KEYS.TEAM_MEMBER_DATA, JSON.stringify(member));
    } catch {
      return false;
    }
  },

  getTeam(): TeamData | null {
    const data = safeGetItem(STORAGE_KEYS.TEAM_DATA);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch {
      return null;
    }
  },

  setTeam(team: TeamData): boolean {
    try {
      return safeSetItem(STORAGE_KEYS.TEAM_DATA, JSON.stringify(team));
    } catch {
      return false;
    }
  },

  getAuthHeader(): string | null {
    const token = this.getToken();
    return token ? `Bearer ${token}` : null;
  },

  getPermissions(): Record<string, Record<string, boolean>> | null {
    const data = safeGetItem(STORAGE_KEYS.TEAM_PERMISSIONS);
    if (!data) return null;
    try {
      return JSON.parse(data);
    } catch {
      return null;
    }
  },

  setPermissions(permissions: Record<string, Record<string, boolean>>): boolean {
    try {
      return safeSetItem(STORAGE_KEYS.TEAM_PERMISSIONS, JSON.stringify(permissions));
    } catch {
      return false;
    }
  },

  hasPermission(section: string, subsection?: string): boolean {
    const permissions = this.getPermissions();
    if (!permissions) return false;
    if (!permissions[section]) return false;
    if (subsection) {
      return permissions[section][subsection] === true;
    }
    return Object.values(permissions[section]).some(v => v === true);
  },

  getTeamType(): 'user' | 'admin' | null {
    const team = this.getTeam();
    return team?.type || null;
  },

  isAdminTeamMember(): boolean {
    return this.getTeamType() === 'admin';
  },

  async validateSession(): Promise<{ valid: boolean; member?: TeamMemberData; team?: TeamData; permissions?: any }> {
    const token = this.getToken();
    if (!token) {
      return { valid: false };
    }

    const team = this.getTeam();
    const isAdminTeam = team?.type === 'admin';
    const endpoint = isAdminTeam ? '/api/admin/team/auth/me' : '/api/team/auth/me';

    try {
      const response = await fetch(endpoint, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        this.clearAuth();
        return { valid: false };
      }

      const data = await response.json();

      if (data.member) {
        this.setMember(data.member);
      }
      if (data.team) {
        this.setTeam(data.team);
      }
      if (data.permissions) {
        this.setPermissions(data.permissions);
      }

      return {
        valid: true,
        member: data.member,
        team: data.team,
        permissions: data.permissions,
      };
    } catch (error) {
      console.error('[TeamAuth] Session validation failed:', error);
      return { valid: false };
    }
  },

  clearAuth(): boolean {
    const tokenRemoved = this.removeToken();
    safeRemoveItem(STORAGE_KEYS.TEAM_MEMBER_DATA);
    safeRemoveItem(STORAGE_KEYS.TEAM_DATA);
    safeRemoveItem(STORAGE_KEYS.TEAM_PERMISSIONS);
    return tokenRemoved;
  },
};

export default TeamAuth;

'use strict';
import { Router, Response } from 'express';
import { storage } from '../../storage';
import { AdminRequest } from '../../middleware/admin-auth';
import { db } from '../../db';
import { eq, isNull, and, sql, isNotNull, or, inArray, desc } from 'drizzle-orm';
import { phoneNumbers, agents, incomingAgents, incomingConnections, calls, users } from '@shared/schema';
import { ElevenLabsPoolService } from '../../services/elevenlabs-pool';
import { ElevenLabsService } from '../../services/elevenlabs';
import { z } from 'zod';

export function registerPhoneNumbersRoutes(router: Router) {
  router.get('/phone-numbers', async (req: AdminRequest, res: Response) => {
    try {
      const numbers = await storage.getAllPhoneNumbers();
      res.json(numbers);
    } catch (error) {
      console.error('Error fetching phone numbers:', error);
      res.status(500).json({ error: 'Failed to fetch phone numbers' });
    }
  });

  router.get('/phone-numbers/twilio-active', async (req: AdminRequest, res: Response) => {
    try {
      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.json({ numbers: [], error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      const incomingNumbers = await client.incomingPhoneNumbers.list({ limit: 100 });

      res.json({
        numbers: incomingNumbers.map(n => ({
          sid: n.sid,
          phoneNumber: n.phoneNumber,
          friendlyName: n.friendlyName,
          capabilities: n.capabilities
        }))
      });
    } catch (error: any) {
      console.error('Error fetching Twilio numbers:', error);
      res.status(500).json({ error: error.message || 'Failed to fetch Twilio numbers' });
    }
  });

  router.post('/phone-numbers/import', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumber, twilioSid, provider } = req.body;

      if (!phoneNumber) {
        return res.status(400).json({ error: 'Phone number is required' });
      }

      const existing = await db.select().from(phoneNumbers).where(eq(phoneNumbers.phoneNumber, phoneNumber));
      if (existing.length > 0) {
        return res.status(400).json({ error: 'Phone number already exists' });
      }

      const [newNumber] = await db.insert(phoneNumbers).values({
        phoneNumber: phoneNumber,
        twilioSid: twilioSid || 'imported-' + Date.now(),
        status: 'active'
      }).returning();

      res.json({ success: true, phoneNumber: newNumber });
    } catch (error: any) {
      console.error('Error importing phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to import phone number' });
    }
  });

  router.delete('/phone-numbers/release/:sid', async (req: AdminRequest, res: Response) => {
    try {
      const { sid } = req.params;

      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.status(400).json({ error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      await client.incomingPhoneNumbers(sid).remove();

      await db.delete(phoneNumbers).where(eq(phoneNumbers.twilioSid, sid));

      res.json({ success: true });
    } catch (error: any) {
      console.error('Error releasing phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to release phone number' });
    }
  });

  router.get('/phone-numbers/all', async (req: AdminRequest, res: Response) => {
    try {
      const allNumbers = await db
        .select({
          id: phoneNumbers.id,
          phoneNumber: phoneNumbers.phoneNumber,
          status: phoneNumbers.status,
          userId: phoneNumbers.userId,
          twilioSid: phoneNumbers.twilioSid,
          country: phoneNumbers.country,
          createdAt: phoneNumbers.createdAt,
          userName: users.name,
          userEmail: users.email
        })
        .from(phoneNumbers)
        .leftJoin(users, eq(phoneNumbers.userId, users.id))
        .orderBy(desc(phoneNumbers.createdAt));

      res.json(allNumbers);
    } catch (error) {
      console.error('Error fetching all phone numbers:', error);
      res.status(500).json({ error: 'Failed to fetch phone numbers' });
    }
  });

  router.patch('/phone-numbers/:id/assign', async (req: AdminRequest, res: Response) => {
    try {
      const { id } = req.params;
      const { userId } = req.body;

      const phoneNumber = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, id));
      if (phoneNumber.length === 0) {
        return res.status(404).json({ error: 'Phone number not found' });
      }

      if (userId) {
        const user = await storage.getUser(userId);
        if (!user) {
          return res.status(404).json({ error: 'User not found' });
        }
      }

      await db.update(phoneNumbers)
        .set({ 
          userId: userId || null,
          status: userId ? 'assigned' : 'available'
        })
        .where(eq(phoneNumbers.id, id));

      res.json({ success: true });
    } catch (error) {
      console.error('Error assigning phone number:', error);
      res.status(500).json({ error: 'Failed to assign phone number' });
    }
  });

  router.post('/phone-numbers/configure-webhooks', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberIds, webhookUrl } = req.body;

      if (!phoneNumberIds || !Array.isArray(phoneNumberIds) || phoneNumberIds.length === 0) {
        return res.status(400).json({ error: 'Phone number IDs are required' });
      }

      if (!webhookUrl) {
        return res.status(400).json({ error: 'Webhook URL is required' });
      }

      const dbSid = await storage.getGlobalSetting('twilio_account_sid');
      const dbToken = await storage.getGlobalSetting('twilio_auth_token');

      const accountSid = (dbSid?.value as string) || process.env.TWILIO_ACCOUNT_SID;
      const authToken = (dbToken?.value as string) || process.env.TWILIO_AUTH_TOKEN;

      if (!accountSid || !authToken) {
        return res.status(400).json({ error: 'Twilio not configured' });
      }

      const twilio = (await import('twilio')).default;
      const client = twilio(accountSid, authToken);

      const results: any[] = [];

      for (const id of phoneNumberIds) {
        const phoneNumberRecord = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, id));
        if (phoneNumberRecord.length === 0 || !phoneNumberRecord[0].twilioSid) {
          results.push({ id, success: false, error: 'Phone number not found or no Twilio SID' });
          continue;
        }

        try {
          await client.incomingPhoneNumbers(phoneNumberRecord[0].twilioSid).update({
            voiceUrl: webhookUrl,
            voiceMethod: 'POST'
          });
          results.push({ id, success: true });
        } catch (err: any) {
          results.push({ id, success: false, error: err.message });
        }
      }

      res.json({ success: true, results });
    } catch (error: any) {
      console.error('Error configuring webhooks:', error);
      res.status(500).json({ error: error.message || 'Failed to configure webhooks' });
    }
  });

  router.get('/phone-numbers/migration-status', async (req: AdminRequest, res: Response) => {
    try {
      const numbersNeedingMigration = await db
        .select({
          id: phoneNumbers.id,
          number: phoneNumbers.phoneNumber,
          status: phoneNumbers.status
        })
        .from(phoneNumbers)
        .where(
          and(
            eq(phoneNumbers.status, 'active'),
            isNull(phoneNumbers.elevenLabsPhoneNumberId)
          )
        );

      res.json({
        needsMigration: numbersNeedingMigration.length,
        numbers: numbersNeedingMigration
      });
    } catch (error) {
      console.error('Error getting migration status:', error);
      res.status(500).json({ error: 'Failed to get migration status' });
    }
  });

  router.post('/phone-numbers/migrate/:phoneNumberId', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberId } = req.params;

      const phoneNumber = await db.select().from(phoneNumbers).where(eq(phoneNumbers.id, phoneNumberId));
      if (phoneNumber.length === 0) {
        return res.status(404).json({ error: 'Phone number not found' });
      }

      await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: 'migrated-' + Date.now() })
        .where(eq(phoneNumbers.id, phoneNumberId));

      res.json({ success: true, message: 'Phone number marked as migrated' });
    } catch (error: any) {
      console.error('Error migrating phone number:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate phone number' });
    }
  });

  router.post('/phone-numbers/migrate-all', async (req: AdminRequest, res: Response) => {
    try {
      const result = await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: 'migrated-' + Date.now() })
        .where(isNull(phoneNumbers.elevenLabsPhoneNumberId));

      res.json({ success: true, message: 'All phone numbers marked as migrated' });
    } catch (error: any) {
      console.error('Error migrating all phone numbers:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate phone numbers' });
    }
  });

  router.post('/phone-numbers/migrate-agent/:agentId', async (req: AdminRequest, res: Response) => {
    try {
      const { agentId } = req.params;

      res.json({ success: true, message: 'Agent migration endpoint - not implemented' });
    } catch (error: any) {
      console.error('Error migrating agent:', error);
      res.status(500).json({ error: error.message || 'Failed to migrate agent' });
    }
  });

  router.post('/phone-numbers/cleanup', async (req: AdminRequest, res: Response) => {
    try {
      const orphanedNumbers = await db
        .select()
        .from(phoneNumbers)
        .where(
          and(
            isNotNull(phoneNumbers.userId),
            eq(phoneNumbers.status, 'assigned')
          )
        );

      let cleaned = 0;
      for (const number of orphanedNumbers) {
        if (number.userId) {
          const user = await storage.getUser(number.userId);
          if (!user) {
            await db.update(phoneNumbers)
              .set({ userId: null, status: 'available' })
              .where(eq(phoneNumbers.id, number.id));
            cleaned++;
          }
        }
      }

      res.json({ success: true, cleaned });
    } catch (error) {
      console.error('Error cleaning up phone numbers:', error);
      res.status(500).json({ error: 'Failed to cleanup phone numbers' });
    }
  });

  router.post('/phone-numbers/clear-sync-status', async (req: AdminRequest, res: Response) => {
    try {
      await db.update(phoneNumbers)
        .set({ elevenLabsPhoneNumberId: null })
        .where(isNotNull(phoneNumbers.elevenLabsPhoneNumberId));

      res.json({ success: true, message: 'Sync status cleared for all phone numbers' });
    } catch (error) {
      console.error('Error clearing sync status:', error);
      res.status(500).json({ error: 'Failed to clear sync status' });
    }
  });

  router.post('/phone-numbers/sync-to-elevenlabs', async (req: AdminRequest, res: Response) => {
    try {
      const { phoneNumberIds } = req.body;

      if (!phoneNumberIds || !Array.isArray(phoneNumberIds)) {
        return res.status(400).json({ error: 'Phone number IDs array is required' });
      }

      res.json({ success: true, message: 'Sync to ElevenLabs - functionality placeholder' });
    } catch (error: any) {
      console.error('Error syncing to ElevenLabs:', error);
      res.status(500).json({ error: error.message || 'Failed to sync to ElevenLabs' });
    }
  });
}

server/engines/payment/gateways/paypal/h.content:
'use strict';
/**
 * PayPal Webhook Event Handlers
 * Pure functions for processing webhook events
 */

import { storage } from '../../../../storage';
import { NotificationService } from '../../../../services/notification-service';
import { syncUserWithSubscription, applyPlanCredits } from '../../../../services/membership-service';
import { emailService } from '../../../../services/email-service';
import { generateInvoiceForTransaction } from '../../invoice-service';
import { PaymentAuditService } from '../../audit';
import { getPayPalCurrency, fetchPayPalSubscription } from './service';

export interface HandlerResult {
  success: boolean;
  action?: string;
  error?: string;
  userId?: string;
  transactionId?: string;
}

export async function handleSubscriptionActivated(
  subscriptionId: string,
  resource: any
): Promise<HandlerResult> {
  const allSubscriptions = await storage.getAllUserSubscriptions();
  const subscription = allSubscriptions.find(s => s.paypalSubscriptionId === subscriptionId);

  if (!subscription) {
    return { success: false, error: 'Subscription not found in database' };
  }

  const startDate = new Date();
  const endDate = new Date(startDate);
  if (subscription.billingPeriod === 'yearly') {
    endDate.setFullYear(endDate.getFullYear() + 1);
  } else {
    endDate.setMonth(endDate.getMonth() + 1);
  }

  await storage.updateUserSubscription(subscription.id, {
    status: 'active',
    currentPeriodStart: startDate,
    currentPeriodEnd: endDate,
    cancelAtPeriodEnd: false,
  });

  await syncUserWithSubscription(subscription.userId);

  const plan = subscription.planId ? await storage.getPlan(subscription.planId) : null;
  if (plan) {
    // Apply plan credits (e.g., 500 credits for Pro plan)
    await applyPlanCredits(
      subscription.userId,
      plan.id,
      'paypal',
      resource?.id || subscriptionId
    );

    const currencyConfig = await getPayPalCurrency();
    const price = (subscription.billingPeriod === 'yearly')
      ? plan.paypalYearlyPrice || plan.yearlyPrice
      : plan.paypalMonthlyPrice || plan.monthlyPrice;

    try {
      const newTransaction = await storage.createPaymentTransaction({
        userId: subscription.userId,
        type: 'subscription',
        gateway: 'paypal',
        gatewayTransactionId: resource?.id || subscriptionId,
        gatewaySubscriptionId: subscriptionId,
        amount: price ? price.toString() : '0',
        currency: currencyConfig.currency.toUpperCase(),
        planId: plan.id,
        subscriptionId: subscription.id,
        description: `${plan.displayName} Subscription`,
        billingPeriod: subscription.billingPeriod || 'monthly',
        status: 'completed',
        completedAt: new Date(),
      });

      await PaymentAuditService.logSubscriptionCreated(
        'paypal',
        subscription.userId,
        subscriptionId,
        plan.id,
        subscription.billingPeriod || 'monthly',
        { amount: price, currency: currencyConfig.currency }
      );

      try {
        await generateInvoiceForTransaction(newTransaction.id);
        await emailService.sendPurchaseConfirmation(newTransaction.id);
      } catch (emailError: any) {
        console.error(`❌ [PayPal] Failed to send purchase confirmation email:`, emailError);
      }

      return { 
        success: true, 
        action: 'subscription_activated',
        userId: subscription.userId,
        transactionId: newTransaction.id,
      };
    } catch (txError: any) {
      if (!txError.message?.includes('unique') && !txError.message?.includes('duplicate')) {
        throw txError;
      }
      return { success: true, action: 'subscription_already_processed', userId: subscription.userId };
    }
  }

  return { success: true, action: 'subscription_activated_no_plan', userId: subscription.userId };
}

export async function handleSubscriptionRenewed(
  subscriptionId: string,
  resource: any
): Promise<HandlerResult> {
  const allSubscriptions = await storage.getAllUserSubscriptions();
  const subscription = allSubscriptions.find(s => s.paypalSubscriptionId === subscriptionId);

  if (!subscription) {
    return { success: false, error: 'Subscription not found in database' };
  }

  const startDate = new Date();
  const endDate = new Date(startDate);
  if (subscription.billingPeriod === 'yearly') {
    endDate.setFullYear(endDate.getFullYear() + 1);
  } else {
    endDate.setMonth(endDate.getMonth() + 1);
  }

  await storage.updateUserSubscription(subscription.id, {
    status: 'active',
    currentPeriodStart: startDate,
    currentPeriodEnd: endDate,
    cancelAtPeriodEnd: false,
  });

  await syncUserWithSubscription(subscription.userId);

  const plan = subscription.planId ? await storage.getPlan(subscription.planId) : null;
  if (plan) {
    const currencyConfig = await getPayPalCurrency();
    const price = (subscription.billingPeriod === 'yearly')
      ? plan.paypalYearlyPrice || plan.yearlyPrice
      : plan.paypalMonthlyPrice || plan.monthlyPrice;

    try {
      const newTransaction = await storage.createPaymentTransaction({
        userId: subscription.userId,
        type: 'subscription',
        gateway: 'paypal',
        gatewayTransactionId: resource?.id || `${subscriptionId}_renewal_${Date.now()}`,
        gatewaySubscriptionId: subscriptionId,
        amount: price ? price.toString() : '0',
        currency: currencyConfig.currency.toUpperCase(),
        planId: plan.id,
        subscriptionId: subscription.id,
        description: `${plan.displayName} Subscription Renewal`,
        billingPeriod: subscription.billingPeriod || 'monthly',
        status: 'completed',
        completedAt: new Date(),
      });

      await PaymentAuditService.logSubscriptionRenewed(
        'paypal',
        subscription.userId,
        subscriptionId,
        parseFloat(price?.toString() || '0'),
        currencyConfig.currency
      );

      try {
        await generateInvoiceForTransaction(newTransaction.id);
        await emailService.sendPurchaseConfirmation(newTransaction.id);
      } catch (emailError: any) {
        console.error(`❌ [PayPal] Failed to send renewal email:`, emailError);
      }

      return { 
        success: true, 
        action: 'subscription_renewed',
        userId: subscription.userId,
        transactionId: newTransaction.id,
      };
    } catch (txError: any) {
      if (!txError.message?.includes('unique') && !txError.message?.includes('duplicate')) {
        throw txError;
      }
      return { success: true, action: 'renewal_already_processed', userId: subscription.userId };
    }
  }

  return { success: true, action: 'subscription_renewed_no_plan', userId: subscription.userId };
}

export async function handleSubscriptionCancelled(
  subscriptionId: string
): Promise<HandlerResult> {
  const allSubscriptions = await storage.getAllUserSubscriptions();
  const subscription = allSubscriptions.find(s => s.paypalSubscriptionId === subscriptionId);

  if (!subscription) {
    return { success: false, error: 'Subscription not found in database' };
  }

  const freePlan = await storage.getPlanByName('free');
  if (freePlan) {
    await storage.updateUserSubscription(subscription.id, {
      planId: freePlan.id,
      status: 'cancelled',
      paypalSubscriptionId: null,
    });
    await syncUserWithSubscription(subscription.userId);
  }

  await PaymentAuditService.logSubscriptionCancelled(
    'paypal',
    subscription.userId,
    subscriptionId,
    false,
    { reason: 'subscription_cancelled_via_webhook' }
  );

  return { success: true, action: 'subscription_cancelled', userId: subscription.userId };
}

export async function handlePaymentFailed(
  subscriptionId: string,
  resource: any
): Promise<HandlerResult> {
  const allSubscriptions = await storage.getAllUserSubscriptions();
  const subscription = allSubscriptions.find(s => s.paypalSubscriptionId === subscriptionId);

  if (!subscription) {
    return { success: false, error: 'Subscription not found in database' };
  }

  await NotificationService.notifyPaymentFailed(subscription.userId);

  await PaymentAuditService.logPaymentFailed(
    'paypal',
    subscription.userId,
    'Subscription payment failed',
    { subscriptionId }
  );

  try {
    const failedAmount = resource?.billing_info?.last_payment?.amount?.value || '0';
    await emailService.sendPaymentFailed(subscription.userId, failedAmount, 'Subscription payment failed');
  } catch (emailError: any) {
    console.error(`❌ [PayPal] Failed to send payment failed email:`, emailError);
  }

  return { success: true, action: 'payment_failed_notified', userId: subscription.userId };
}

export async function handleCaptureCompleted(
  captureId: string,
  resource: any
): Promise<HandlerResult> {
  console.log(`📥 [PayPal] Payment capture completed: ${captureId}`);
  return { success: true, action: 'capture_completed' };
}

export async function handleCaptureRefunded(
  captureId: string,
  resource: any,
  eventId: string
): Promise<HandlerResult> {
  console.log(`🔄 [PayPal] External refund received for capture: ${captureId}`);

  const transaction = await storage.getPaymentTransactionByGatewayId('paypal', captureId);

  if (!transaction) {
    return { success: false, error: 'Transaction not found for refund' };
  }

  const existingRefunds = await storage.getTransactionRefunds(transaction.id);
  if (existingRefunds.length > 0) {
    return { success: true, action: 'refund_already_exists' };
  }

  const userId = transaction.userId;
  const user = await storage.getUser(userId);

  let creditsReversed = 0;
  if (transaction.type === 'credits' && transaction.creditsAwarded && user) {
    creditsReversed = transaction.creditsAwarded;
    const newCredits = Math.max(0, user.credits - creditsReversed);
    await storage.updateUserCredits(userId, newCredits);
    console.log(`🔄 [PayPal] Reversed ${creditsReversed} credits for user ${userId}`);
  }

  const refundAmount = resource?.amount?.value || transaction.amount;
  await storage.createRefund({
    transactionId: transaction.id,
    userId,
    amount: refundAmount.toString(),
    currency: resource?.amount?.currency_code || transaction.currency,
    gateway: 'paypal',
    gatewayRefundId: eventId || `paypal_refund_${captureId}`,
    reason: 'gateway_refund',
    initiatedBy: 'gateway',
    status: 'completed',
    creditsReversed: creditsReversed > 0 ? creditsReversed : undefined,
    metadata: {
      userSuspended: false,
      refundReason: 'external_refund',
    },
  });

  await storage.updatePaymentTransaction(transaction.id, { status: 'refunded' });

  await PaymentAuditService.logRefundCompleted(
    'paypal',
    userId,
    transaction.id,
    eventId || `paypal_refund_${captureId}`,
    parseFloat(refundAmount),
    transaction.currency
  );

  return { 
    success: true, 
    action: 'external_refund_processed',
    userId,
    transactionId: transaction.id,
  };
}

export async function handleDisputeCreated(
  disputeId: string,
  resource: any
): Promise<HandlerResult> {
  console.log(`🚨 [PayPal] Dispute created: ${disputeId}`);

  const disputedTransaction = resource?.disputed_transactions?.[0];
  const captureId = disputedTransaction?.seller_transaction_id || disputedTransaction?.buyer_transaction_id;

  if (!captureId) {
    return { success: false, error: 'No capture ID in dispute' };
  }

  const transaction = await storage.getPaymentTransactionByGatewayId('paypal', captureId);

  if (!transaction) {
    return { success: false, error: 'Transaction not found for dispute' };
  }

  const userId = transaction.userId;
  const user = await storage.getUser(userId);

  let creditsReversed = 0;
  if (transaction.type === 'credits' && transaction.creditsAwarded && user) {
    creditsReversed = transaction.creditsAwarded;
    const newCredits = Math.max(0, user.credits - creditsReversed);
    await storage.updateUserCredits(userId, newCredits);
    console.log(`🔄 [PayPal] Reversed ${creditsReversed} credits for user ${userId}`);
  }

  const disputeAmount = resource?.dispute_amount?.value || disputedTransaction?.gross_amount?.value || transaction.amount;
  await storage.createRefund({
    transactionId: transaction.id,
    userId,
    amount: disputeAmount.toString(),
    currency: resource?.dispute_amount?.currency_code || transaction.currency,
    gateway: 'paypal',
    gatewayRefundId: disputeId,
    reason: 'chargeback',
    initiatedBy: 'gateway',
    status: 'completed',
    creditsReversed: creditsReversed > 0 ? creditsReversed : undefined,
    metadata: {
      userSuspended: true,
      disputeReason: resource?.reason || 'unknown',
      disputeStatus: resource?.status,
      disputeLifeCycleStage: resource?.dispute_life_cycle_stage,
    },
  });

  await storage.updatePaymentTransaction(transaction.id, { status: 'refunded' });
  await storage.updateUser(userId, { isActive: false });

  await PaymentAuditService.logDisputeOpened(
    'paypal',
    userId,
    transaction.id,
    disputeId,
    parseFloat(disputeAmount),
    transaction.currency,
    resource?.reason
  );

  try {
    await emailService.sendAccountSuspended(userId, `Chargeback dispute: ${resource?.reason || 'Unknown reason'}`);
  } catch (emailError: any) {
    console.error(`❌ [PayPal] Failed to send account suspended email:`, emailError);
  }

  console.log(`⛔ [PayPal] User ${userId} suspended due to chargeback. Dispute ID: ${disputeId}, Reason: ${resource?.reason}`);

  return { 
    success: true, 
    action: 'user_suspended_chargeback',
    userId,
    transactionId: transaction.id,
  };
}

export async function handleCreditsPayment(
  orderId: string,
  captureId: string,
  metadata: { userId: string; packageId: string; credits: number }
): Promise<HandlerResult> {
  const pkg = await storage.getCreditPackage(metadata.packageId);
  if (!pkg) {
    return { success: false, error: 'Package not found' };
  }

  try {
    await storage.addCreditsAtomic(
      metadata.userId,
      metadata.credits,
      `Purchased ${pkg.name} via PayPal`,
      `paypal_${captureId}`
    );

    const currencyConfig = await getPayPalCurrency();

    const newTransaction = await storage.createPaymentTransaction({
      userId: metadata.userId,
      type: 'credits',
      gateway: 'paypal',
      gatewayTransactionId: captureId || orderId,
      amount: pkg.paypalPrice ? pkg.paypalPrice.toString() : pkg.price.toString(),
      currency: currencyConfig.currency.toUpperCase(),
      creditPackageId: metadata.packageId,
      description: `${pkg.name} - ${metadata.credits} Credits`,
      creditsAwarded: metadata.credits,
      status: 'completed',
      completedAt: new Date(),
    });

    await PaymentAuditService.logCreditsAwarded(
      'paypal',
      metadata.userId,
      newTransaction.id,
      metadata.credits,
      { packageName: pkg.name }
    );

    try {
      await generateInvoiceForTransaction(newTransaction.id);
      await emailService.sendPurchaseConfirmation(newTransaction.id);
    } catch (emailError: any) {
      console.error(`❌ [PayPal] Failed to send purchase confirmation:`, emailError);
    }

    return { 
      success: true, 
      action: 'credits_awarded',
      userId: metadata.userId,
      transactionId: newTransaction.id,
    };
  } catch (error: any) {
    if (error.message?.includes('unique') || error.message?.includes('duplicate')) {
      return { success: true, action: 'credits_already_processed', userId: metadata.userId };
    }
    throw error;
  }
}

