  --sidebar-ring: 217 91% 60%;

  --popover: 0 0% 100%;

  --popover-foreground: 220 9% 18%;

  --popover-border: 220 13% 91%;

  --primary: 217 91% 60%;

  --primary-foreground: 0 0% 100%;

  --secondary: 220 14% 96%;

  --secondary-foreground: 220 9% 35%;

  --muted: 220 14% 96%;

  --muted-foreground: 220 9% 46%;

  --accent: 217 91% 96%;

  --accent-foreground: 217 91% 45%;

  --destructive: 0 84% 60%;

