  --sidebar-accent: 217 33% 20%;

  --sidebar-accent-foreground: 217 91% 70%;

  --sidebar-ring: 217 91% 60%;

  --popover: 222 47% 13%;

  --popover-foreground: 210 40% 98%;

  --popover-border: 217 33% 17%;

  --primary: 217 91% 60%;

  --primary-foreground: 0 0% 100%;

  --secondary: 217 33% 17%;

  --secondary-foreground: 210 40% 98%;

  --muted: 217 33% 17%;

  --muted-foreground: 215 20% 65%;

  --accent: 217 33% 20%;

  --accent-foreground: 217 91% 70%;

  --destructive: 0 63% 51%;

  --destructive-foreground: 0 0% 100%;

  --input: 217 33% 17%;
  --ring: 217 91% 60%;
  --chart-1: 203.8863 88.2845% 53.1373%;
  --chart-2: 159.7826 100% 36.0784%;
  --chart-3: 42.0290 92.8251% 56.2745%;
  --chart-4: 147.1429 78.5047% 41.9608%;
  --chart-5: 341.4894 75.2000% 50.9804%;

  --shadow-2xs: 0px 1px 1px 0px hsl(210 6% 0% / 0.12);
  --shadow-xs: 0px 1px 2px 0px hsl(210 6% 0% / 0.18);
  --shadow-sm: 0px 1px 2px 0px hsl(210 6% 0% / 0.20), 0px 1px 3px -1px hsl(210 6% 0% / 0.24);
  --shadow: 0px 1px 3px 0px hsl(210 6% 0% / 0.24), 0px 1px 2px -1px hsl(210 6% 0% / 0.28);
  --shadow-md: 0px 2px 4px -1px hsl(210 6% 0% / 0.24), 0px 4px 6px -1px hsl(210 6% 0% / 0.30);
  --shadow-lg: 0px 4px 6px -1px hsl(210 6% 0% / 0.28), 0px 10px 15px -3px hsl(210 6% 0% / 0.32);
  --shadow-xl: 0px 10px 10px -5px hsl(210 6% 0% / 0.30), 0px 20px 25px -5px hsl(210 6% 0% / 0.34);
  --shadow-2xl: 0px 25px 50px -12px hsl(210 6% 0% / 0.40);

}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/**
 * Using the elevate system.
 * Automatic contrast adjustment.
 *
 * <element className="hover-elevate" />
 * <element className="active-elevate-2" />
 *
 * // Using the tailwind utility when a data attribute is "on"
 * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
 * // Or manually controlling the toggle state
 * <element className="toggle-elevate toggle-elevated" />
 *
 * Elevation systems have to handle many states.
 * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
 * - toggled or not
 * - focused or not (this is not handled with these utilities)
 *
 * Even without handling focused or not, this is six possible combinations that
 * need to be distinguished from eachother visually.
 */
@layer utilities {

  /* Hide ugly search cancel button in Chrome until we can style it properly */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   * buttons/badges can remove the automatic brightness adjustment on interactions
   * and program their own. */
  .no-default-hover-elevate {}

  .no-default-active-elevate {}


  /**
   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   * This way they can stack/compound. Both will overlap the parent's borders!
   * So borders will be automatically adjusted both on toggle, and hover/active,
   * and they will be compounded.
   */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: -1;
    /* sits behind content but above backdrop */
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Does not work on elements with overflow:hidden! */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: 999;
    /* sits in front of content */
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }

  /* Shake animation for error feedback */
  @keyframes shake {
    0%, 100% { transform: translateX(0); }
    10%, 30%, 50%, 70%, 90% { transform: translateX(-4px); }
    20%, 40%, 60%, 80% { transform: translateX(4px); }
  }

  .animate-shake {
    animation: shake 0.5s ease-in-out;
  }

  /* Shimmer animation for silver/premium UI elements */
  @keyframes shimmer {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
  }
}

/* ========================
   RTL (Right-to-Left) Support
   ======================== */

/* Arabic font family support */
html[lang="ar"] {
  --font-sans: 'IBM Plex Sans Arabic', 'Cairo', 'Segoe UI', sans-serif;
  --font-serif: 'IBM Plex Sans Arabic', 'Cairo', serif;
}

/* RTL specific adjustments */
html[dir="rtl"] {
  direction: rtl;
  text-align: right;
}

/* Flip directional icons in RTL */
html[dir="rtl"] .rtl-flip {
  transform: scaleX(-1);
}

/* Don't flip certain icons that should remain the same in RTL */
html[dir="rtl"] .rtl-no-flip {
  transform: none !important;
}

/* RTL sidebar positioning - use inset-inline-start/end for auto-mirroring */
html[dir="rtl"] [data-slot="sidebar-container"] {
  left: auto;
  right: 0;
  border-right: none;
  border-left: 1px solid hsl(var(--sidebar-border));
}

html[dir="rtl"] [data-slot="sidebar-container"][data-side="left"] {
  left: auto;
  right: 0;
}

html[dir="rtl"] [data-state="collapsed"] [data-slot="sidebar-container"] {
  right: calc(var(--sidebar-width) * -1);
  left: auto;
}

/* RTL sidebar inner border */
html[dir="rtl"] [data-sidebar="sidebar"] {
  border-left: 1px solid hsl(var(--sidebar-border));
  border-right: none;
}

/* RTL sidebar gap mirror */
html[dir="rtl"] [data-slot="sidebar-gap"] {
  margin-left: 0;
  margin-right: 0;
}

/* RTL form adjustments */
html[dir="rtl"] input,
html[dir="rtl"] textarea,
html[dir="rtl"] select {
  text-align: right;
}

/* Keep numbers LTR within RTL context */
html[dir="rtl"] .ltr-numbers {
  direction: ltr;
  unicode-bidi: embed;
}

/* Phone numbers should always be LTR */
html[dir="rtl"] input[type="tel"],
html[dir="rtl"] .phone-number {
  direction: ltr;
  text-align: left;
}

/* Flow builder canvas should stay LTR (standard for diagrams) */
html[dir="rtl"] .react-flow,
html[dir="rtl"] .flow-builder-canvas {
  direction: ltr;
}

/* RTL dropdown menu alignment */
html[dir="rtl"] [data-radix-popper-content-wrapper] {
  --radix-popper-anchor-width: auto;
}

/* RTL dialog positioning */
html[dir="rtl"] [role="dialog"] {
  text-align: right;
}

/* RTL table header alignment */
html[dir="rtl"] th {
  text-align: right;
}

/* RTL table data alignment */
html[dir="rtl"] td {
  text-align: right;
}

/* RTL badge/chip positioning - use logical properties */
html[dir="rtl"] .badge-position-start {
  left: auto;
  right: 0;
  inset-inline-start: 0;
  inset-inline-end: auto;
}

html[dir="rtl"] .badge-position-end {
  right: auto;
  left: 0;
  inset-inline-start: auto;
  inset-inline-end: 0;
}

/* RTL margin/padding logical replacements - comprehensive coverage */

/* Margin auto */
html[dir="rtl"] .ml-auto { margin-left: 0; margin-right: auto; }
html[dir="rtl"] .mr-auto { margin-right: 0; margin-left: auto; }

/* Margin 0 */
html[dir="rtl"] .ml-0 { margin-left: initial; margin-right: 0; }
html[dir="rtl"] .mr-0 { margin-right: initial; margin-left: 0; }

/* Margin 1 (0.25rem) */
html[dir="rtl"] .ml-1 { margin-left: 0; margin-right: 0.25rem; }
html[dir="rtl"] .mr-1 { margin-right: 0; margin-left: 0.25rem; }

/* Margin 2 (0.5rem) */
html[dir="rtl"] .ml-2 { margin-left: 0; margin-right: 0.5rem; }
html[dir="rtl"] .mr-2 { margin-right: 0; margin-left: 0.5rem; }

