  message?: string;
  waitForResponse?: boolean;
  question?: string;
  variableName?: string;
  condition?: string;
  trueBranch?: string;
  falseBranch?: string;
  phoneNumber?: string;
  transferType?: "phone" | "agent";
  transferAgentId?: string;
  duration?: number;
  webhookUrl?: string;
