import { db } from "./db";
import { plans } from "@shared/schema";

const PLANS_SEED_DATA = [
  {
    name: "free",
    displayName: "Free",
    description: "Perfect for trying out AI calling. Get started with basic features at no cost.",
    monthlyPrice: "0.00",
    yearlyPrice: "0.00",
